func (h *Handler) DownloadAttachmentWithCapability(w http.ResponseWriter, r *http.Request) {
	attachmentID := chi.URLParam(r, "id")
	query := r.URL.Query()
	// dl=1 is the forced-attachment ("download button") intent. It is covered by
	// a distinct signature, so a load-intent link cannot flip itself to a
	// download by appending dl=1 — the verification below would fail.
	intent := ""
	if query.Get("dl") == "1" {
		intent = attachmentCapabilityDownloadIntent
	}
	if !verifyAttachmentCapability(attachmentID, query.Get("exp"), query.Get("sig"), intent, time.Now()) {
		// One generic rejection for every reason, so a caller cannot
		// distinguish "expired" from "forged" from "wrong attachment"
		// and use the difference to probe the signer.
		writeError(w, http.StatusForbidden, "invalid or expired download link")
		return
	}

	attUUID, ok := parseUUIDOrBadRequest(w, attachmentID, "attachment id")
	if !ok {
		return
	}
	att, err := h.Queries.GetAttachmentByIDOnly(r.Context(), attUUID)
	if err != nil {
		writeError(w, http.StatusNotFound, "attachment not found")
		return
	}
	if h.Storage == nil {
		writeFeatureDisabled(w, "storage_not_configured", "storage not configured")
		return
	}

	h.setAttachmentPreviewSecurityHeaders(w)
	// The signature travels in the query string. If the streamed body is
	// itself a document that loads subresources, no-referrer keeps that
	// query out of the outbound Referer.
	w.Header().Set("Referrer-Policy", "no-referrer")

	h.proxyAttachmentDownload(w, r, att, h.Storage.KeyFromURL(att.Url), intent == attachmentCapabilityDownloadIntent)
}

func (h *Handler) ServeAvatar(w http.ResponseWriter, r *http.Request) {
	if h.Storage == nil {
		http.NotFound(w, r)
		return
	}

	key, err := url.PathUnescape(chi.URLParam(r, "*"))
	if err != nil || key == "" {
		http.NotFound(w, r)
		return
	}
	contentType := avatarContentType(key)
	// Deny shape is a flat 404 for a bad signature, an unknown key, a
	// non-image key, and an object that is not avatar-class alike, so the
	// route is not an oracle for any of them. The publishable check runs on
	// every request rather than only at write time: it is what bounds rows
	// written before the write-side gate existed, and it revokes the URL if
	// the object is later bound to a comment or chat.
	if contentType == "" ||
		!avatarKeySignatureValid(key, chi.URLParam(r, "sig")) ||
		!h.avatarKeyIsPublishable(r.Context(), key) {
		http.NotFound(w, r)
		return
	}

	objectURL := h.Storage.ObjectURL(key)
	h.setAttachmentPreviewSecurityHeaders(w)

	switch h.resolveAttachmentDownloadMode(objectURL) {
	case attachmentDownloadModeCloudFront:
		if h.CFSigner == nil {
			writeError(w, http.StatusInternalServerError, "cloudfront avatar downloads are not configured")
			return
		}
		setAvatarCacheControl(w, h.avatarRedirectMaxAge())
		http.Redirect(w, r, h.CFSigner.SignedURL(objectURL, time.Now().Add(h.attachmentDownloadURLTTL())), http.StatusFound)
	case attachmentDownloadModePresign:
		presigner, ok := h.Storage.(storage.DownloadPresigner)
		if !ok {
			writeError(w, http.StatusInternalServerError, "avatar storage does not support presigned downloads")
			return
		}
		// Empty disposition inherits the object's stored Content-Disposition
		// (inline for images), which is what keeps the redirect renderable in
		// an <img> instead of triggering a download.
		signedURL, err := presigner.PresignGetWithContentDisposition(r.Context(), key, h.attachmentDownloadURLTTL(), "")
		if err != nil {
			slog.Error("failed to presign avatar", "key", key, "error", err)
			writeError(w, http.StatusBadGateway, "failed to create avatar URL")
			return
		}
		setAvatarCacheControl(w, h.avatarRedirectMaxAge())
		http.Redirect(w, r, signedURL, http.StatusFound)
	case attachmentDownloadModeProxy:
		h.proxyAvatar(w, r, key, contentType)
	default:
		writeError(w, http.StatusInternalServerError, "invalid attachment download mode")
	}
}

func (h *Handler) ServePluginSurface(w http.ResponseWriter, r *http.Request) {
	origin, err := parsePluginSurfaceOrigin(h.cfg.PluginSurfaceOrigin)
	if err != nil || !h.pluginSurfaceOriginIsDedicated(origin) || !strings.EqualFold(r.Host, origin.Host) {
		http.NotFound(w, r)
		return
	}
	// Enforce the deployment promise at the request boundary. A broad parent-
	// domain auth cookie must make the surface fail visibly, not quietly arrive
	// on a host that was supposed to be cookie-free.
	if r.Header.Get("Cookie") != "" || r.Header.Get("Authorization") != "" {
		writeError(w, http.StatusBadRequest, "the Plugin content origin must not receive app credentials")
		return
	}
	claims, err := h.openPluginSurfaceToken(chi.URLParam(r, "token"))
	if err != nil {
		http.NotFound(w, r)
		return
	}
	workspaceID, err := util.ParseUUID(claims.WorkspaceID)
	if err != nil {
		http.NotFound(w, r)
		return
	}
	installation, err := h.PluginService.InstallationForWorkspace(r.Context(), workspaceID, claims.InstallationID)
	if err != nil || !installation.Enabled || util.UUIDToString(installation.PackageVersionID) != claims.VersionID {
		http.NotFound(w, r)
		return
	}
	script, err := h.PluginService.SurfaceScript(r.Context(), installation, claims.SurfaceKey)
	if err != nil || !hmac.Equal([]byte(script.Digest), []byte(claims.Digest)) {
		http.NotFound(w, r)
		return
	}
	var scopes []string
	if err := json.Unmarshal(installation.GrantedScopes, &scopes); err != nil {
		http.NotFound(w, r)
		return
	}

	document := buildPluginSurfaceDocument(script.Code, claims.Challenge)
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	w.Header().Set("Cache-Control", "private, no-store")
	w.Header().Set("Referrer-Policy", "no-referrer")
	w.Header().Set("X-Content-Type-Options", "nosniff")
	w.Header().Set("Permissions-Policy", "camera=(), microphone=(), geolocation=(), payment=(), usb=()")
	w.Header().Set("Cross-Origin-Resource-Policy", "cross-origin")
	w.Header().Set("Content-Security-Policy", pluginSurfaceCSP(scopes))
	w.WriteHeader(http.StatusOK)
	_, _ = w.Write([]byte(document))
}

func (h *Handler) CreateContactSales(w http.ResponseWriter, r *http.Request) {
	r.Body = http.MaxBytesReader(w, r.Body, contactSalesBodyLimit)
	var req CreateContactSalesRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid request body")
		return
	}

	firstName, ok := requireTrimmedField(w, req.FirstName, "first_name", contactSalesMaxFirstName)
	if !ok {
		return
	}
	lastName, ok := requireTrimmedField(w, req.LastName, "last_name", contactSalesMaxLastName)
	if !ok {
		return
	}
	companyName, ok := requireTrimmedField(w, req.CompanyName, "company_name", contactSalesMaxCompanyName)
	if !ok {
		return
	}

	email, ok := canonicalBusinessEmail(req.BusinessEmail)
	if !ok {
		writeError(w, http.StatusBadRequest, "business_email is invalid")
		return
	}
	if len(email) > contactSalesMaxEmail {
		writeError(w, http.StatusBadRequest, "business_email is too long")
		return
	}
	if !isBusinessEmailDomain(email) {
		writeError(w, http.StatusBadRequest, "please use a business email address")
		return
	}

	companySize := strings.TrimSpace(req.CompanySize)
	if !slices.Contains(contactSalesAllowedCompanySize, companySize) {
		writeError(w, http.StatusBadRequest, "company_size is invalid")
		return
	}

	countryRegion := strings.TrimSpace(req.CountryRegion)
	if countryRegion == "" {
		writeError(w, http.StatusBadRequest, "country_region is required")
		return
	}
	// Bound the dropdown value at a generous length — we accept any string
	// the frontend submits (country list is large) but cap it so an
	// attacker can't stuff the column.
	if len(countryRegion) > 80 {
		writeError(w, http.StatusBadRequest, "country_region is too long")
		return
	}

	useCase := strings.TrimSpace(req.UseCase)
	if !slices.Contains(contactSalesAllowedUseCase, useCase) {
		writeError(w, http.StatusBadRequest, "use_case is invalid")
		return
	}

	goals := strings.TrimSpace(req.Goals)
	if len(goals) > contactSalesMaxGoals {
		writeError(w, http.StatusBadRequest, "goals is too long")
		return
	}

	// Per-email hourly cap: keeps a single business address from being
	// used as a re-submit channel after one valid pass. DB-backed so it
	// works across replicas and survives a restart.
	count, err := h.Queries.CountRecentContactSalesByEmail(r.Context(), email)
	if err != nil {
		slog.Warn("count recent contact sales failed", append(logger.RequestAttrs(r), "error", err)...)
		writeError(w, http.StatusInternalServerError, "failed to submit inquiry")
		return
	}
	if count >= contactSalesHourlyEmailCap {
		writeError(w, http.StatusTooManyRequests, "too many recent inquiries from this email")
		return
	}

	inquiry, err := h.Queries.CreateContactSalesInquiry(r.Context(), db.CreateContactSalesInquiryParams{
		FirstName:       firstName,
		LastName:        lastName,
		BusinessEmail:   email,
		CompanyName:     companyName,
		CompanySize:     companySize,
		CountryRegion:   countryRegion,
		UseCase:         useCase,
		Goals:           goals,
		ConsentOutreach: req.ConsentOutreach,
		ConsentUpdates:  req.ConsentUpdates,
		UserAgent:       truncateString(r.UserAgent(), 512),
		SubmitterIp:     submitterIP(r),
	})
	if err != nil {
		slog.Warn("create contact sales failed", append(logger.RequestAttrs(r), "error", err)...)
		writeError(w, http.StatusInternalServerError, "failed to submit inquiry")
		return
	}

	inquiryID := uuidToString(inquiry.ID)
	slog.Info("contact sales submitted",
		append(logger.RequestAttrs(r),
			"inquiry_id", inquiryID,
			"company_size", companySize,
			"country_region", countryRegion,
			"use_case", useCase,
		)...)

	formSource := strings.TrimSpace(req.Source)
	if formSource == "" {
		formSource = "page"
	}

	obsmetrics.RecordEvent(h.Analytics, h.Metrics, analytics.ContactSalesSubmitted(
		inquiryID,
		companySize,
		countryRegion,
		useCase,
		formSource,
		goals != "",
	))

	writeJSON(w, http.StatusCreated, ContactSalesResponse{
		ID:        inquiryID,
		CreatedAt: timestampToString(inquiry.CreatedAt),
	})
}

func (h *Handler) GetSiteStar(w http.ResponseWriter, r *http.Request) {
	turns, err := h.Queries.GetSiteCounter(r.Context(), siteStarCounter)
	if err != nil && !errors.Is(err, pgx.ErrNoRows) {
		slog.Warn("get site star failed", append(logger.RequestAttrs(r), "error", err)...)
		writeError(w, http.StatusInternalServerError, "failed to read star")
		return
	}
	writeJSON(w, http.StatusOK, siteStarResponse{Turns: turns})
}

func (h *Handler) AddSiteStarTurns(w http.ResponseWriter, r *http.Request) {
	r.Body = http.MaxBytesReader(w, r.Body, siteStarBodyLimit)
	var req addSiteStarTurnsRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid request body")
		return
	}
	if req.Turns < 1 || req.Turns > siteStarMaxTurnsPerRequest {
		writeError(w, http.StatusBadRequest, "turns is out of range")
		return
	}
	turns, err := h.Queries.AddSiteCounter(r.Context(), db.AddSiteCounterParams{Name: siteStarCounter, Value: req.Turns})
	if err != nil {
		slog.Warn("add site star turns failed", append(logger.RequestAttrs(r), "error", err)...)
		writeError(w, http.StatusInternalServerError, "failed to spin star")
		return
	}
	writeJSON(w, http.StatusOK, siteStarResponse{Turns: turns})
}

func (h *Handler) GetShareLinkInfo(w http.ResponseWriter, r *http.Request) {
	code := chi.URLParam(r, "code")
	code = strings.TrimSpace(code)
	if code == "" {
		writeError(w, http.StatusBadRequest, "code is required")
		return
	}

	row, err := h.Queries.GetShareLinkInfoByCode(r.Context(), code)
	if err != nil {
		writeError(w, http.StatusNotFound, "share link not found or expired")
		return
	}

	writeJSON(w, http.StatusOK, ShareLinkInfoResponse{
		WorkspaceName: row.WorkspaceName,
		WorkspaceSlug: row.WorkspaceSlug,
		CreatorName:   row.CreatorName,
		Role:          row.Role,
	})
}

func (h *Handler) HandleAutopilotWebhook(w http.ResponseWriter, r *http.Request) {
	token := chi.URLParam(r, "token")
	if token == "" {
		writeError(w, http.StatusNotFound, "webhook not found")
		return
	}

	// 1. Always retain a high absolute ceiling. The lower shared-IP limiter
	//    tracks only requests already classified as bad credentials, so a NAT
	//    full of legitimate GitHub hooks does not consume its budget.
	ip := h.clientIPForRateLimit(r)
	if ip != "" && h.WebhookAbsoluteIPRateLimiter != nil && !h.WebhookAbsoluteIPRateLimiter.Allow(r.Context(), ip) {
		writeWebhookRateLimit(w, r, h.WebhookAbsoluteIPRateLimiter, ip, "absolute_ip", h.Metrics)
		return
	}
	if ip != "" && h.WebhookIPRateLimiter != nil && !slidingWindowLimiterCheck(r.Context(), h.WebhookIPRateLimiter, ip) {
		writeWebhookRateLimit(w, r, h.WebhookIPRateLimiter, ip, "bad_credential_ip", h.Metrics)
		return
	}

	// 2. Token lookup. Distinguish "no row" from "DB error": collapsing both
	//    to 404 means a transient DB blip silently drops real deliveries
	//    (providers like GitHub don't retry on 404). For no-row we still
	//    return a generic message so we don't leak which tokens existed.
	trigRow, err := h.Queries.GetWebhookTriggerByToken(r.Context(), pgtype.Text{String: token, Valid: true})
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			if ip != "" && h.WebhookIPRateLimiter != nil {
				h.WebhookIPRateLimiter.Allow(r.Context(), ip)
			}
			writeError(w, http.StatusNotFound, "webhook not found")
			return
		}
		slog.Error("webhook: token lookup failed", "error", err)
		writeError(w, http.StatusInternalServerError, "internal error")
		return
	}

	middleware.SetWebhookTriggerID(r, uuidToString(trigRow.ID))

	// 3. Body size cap + JSON validation. http.MaxBytesReader stops the read
	//    mid-stream once the cap is exceeded so an oversized payload is
	//    rejected before being fully buffered.
	r.Body = http.MaxBytesReader(w, r.Body, maxWebhookBodyBytes)
	body, err := io.ReadAll(r.Body)
	if err != nil {
		var mbe *http.MaxBytesError
		if errors.As(err, &mbe) {
			writeError(w, http.StatusRequestEntityTooLarge, "payload too large")
			return
		}
		writeError(w, http.StatusBadRequest, "failed to read request body")
		return
	}

	// 4. Cross-check autopilot/workspace consistency BEFORE we persist the
	//    delivery — webhook_delivery.workspace_id is NOT NULL and a stale FK
	//    row would otherwise fail INSERT after we've already paid the body
	//    read. Same ErrNoRows-vs-DB-error split as token lookup.
	autopilot, err := h.Queries.GetAutopilot(r.Context(), trigRow.AutopilotID)
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			writeError(w, http.StatusNotFound, "webhook not found")
			return
		}
		slog.Error("webhook: autopilot lookup failed",
			"error", err,
			"trigger_id", uuidToString(trigRow.ID),
		)
		writeError(w, http.StatusInternalServerError, "internal error")
		return
	}
	if uuidToString(autopilot.WorkspaceID) != uuidToString(trigRow.AutopilotWorkspaceID) {
		slog.Warn("webhook: trigger workspace mismatch",
			"trigger_id", uuidToString(trigRow.ID),
			"autopilot_id", uuidToString(autopilot.ID),
		)
		writeError(w, http.StatusNotFound, "webhook not found")
		return
	}

	// 5. Normalize body. Invalid JSON → 400 without persistence: we have no
	//    dedupe identifier from the body, and replaying an unparsable payload
	//    is not useful.
	envelope, err := normalizeWebhookPayload(body, r.Header)
	if err != nil {
		writeError(w, http.StatusBadRequest, err.Error())
		return
	}
	envelopeBytes, err := json.Marshal(envelope)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "failed to encode envelope")
		return
	}
	// 6. Provider + dedupe + signature.
	provider := trigRow.Provider
	if provider == "" {
		provider = "generic"
	}
	dedupeKey, dedupeSource := extractDedupeKey(provider, r.Header)
	sigStatus := verifyWebhookSignatureForProvider(provider, trigRow.SigningSecret.String, r.Header, body)

	// 7. Persist (INSERT delivery). Dedupe collision → bump existing row.
	delivery, dup, err := h.persistInboundDelivery(r, persistDeliveryInput{
		WorkspaceID:     autopilot.WorkspaceID,
		AutopilotID:     autopilot.ID,
		TriggerID:       trigRow.ID,
		Provider:        provider,
		Event:           envelope.Event,
		DedupeKey:       dedupeKey,
		DedupeSource:    dedupeSource,
		SignatureStatus: sigStatus,
		ContentType:     envelope.Request.ContentType,
		RawBody:         body,
		SelectedHeaders: selectedHeadersJSON(r.Header),
	})
	if err != nil {
		slog.Error("webhook: persist delivery failed",
			"error", err,
			"trigger_id", uuidToString(trigRow.ID),
		)
		writeError(w, http.StatusInternalServerError, "internal error")
		return
	}
	if dup {
		// A previous delivery already covered this dedupe key. Return the
		// original delivery_id + admitted run_id with 200 so the caller can
		// correlate. The delivery row is not linked until worker completion,
		// so retrying before then must fall back to the run's durable delivery
		// anchor.
		resp := map[string]any{
			"status":      "duplicate",
			"delivery_id": uuidToString(delivery.ID),
		}
		runID := delivery.AutopilotRunID
		if !runID.Valid {
			run, runErr := h.Queries.GetAutopilotRunByWebhookDelivery(r.Context(), delivery.ID)
			switch {
			case runErr == nil:
				runID = run.ID
			case !errors.Is(runErr, pgx.ErrNoRows):
				slog.Error("webhook: resolve duplicate run failed",
					"delivery_id", uuidToString(delivery.ID),
					"error", runErr,
				)
				writeError(w, http.StatusInternalServerError, "internal error")
				return
			}
		}
		if runID.Valid {
			resp["run_id"] = uuidToString(runID)
		}
		if delivery.Status == deliveryStatusQueued && h.WebhookDeliveryWorker != nil {
			h.WebhookDeliveryWorker.Notify()
		}
		writeJSON(w, http.StatusOK, resp)
		return
	}

	// 8. Signature failure → rejected delivery + 401. No dispatch, no replay.
	//    Providers will look for 4xx feedback when their secret is wrong.
	if sigStatus == sigStatusInvalid || sigStatus == sigStatusMissing {
		reason := "invalid_signature"
		if sigStatus == sigStatusMissing {
			reason = "missing_signature"
		}
		respBody := map[string]any{
			"status":      "rejected",
			"delivery_id": uuidToString(delivery.ID),
			"reason":      reason,
		}
		if ip != "" && h.WebhookIPRateLimiter != nil {
			h.WebhookIPRateLimiter.Allow(r.Context(), ip)
		}
		h.finaliseDeliveryTerminal(r, delivery.ID, deliveryStatusRejected, http.StatusUnauthorized, respBody, reason)
		writeJSON(w, http.StatusUnauthorized, respBody)
		return
	}

	// 9. Trigger disabled / autopilot paused / archived → ignored. We return
	//     200 so the sender's webhook-retry machinery doesn't keep hammering
	//     us; the "ignored" status + delivery row makes the no-op visible if
	//     the operator inspects the delivery log.
	if !trigRow.Enabled {
		respBody := map[string]any{"status": "ignored", "delivery_id": uuidToString(delivery.ID), "reason": "trigger_disabled"}
		h.finaliseDeliveryTerminal(r, delivery.ID, deliveryStatusIgnored, http.StatusOK, respBody, "trigger_disabled")
		writeJSON(w, http.StatusOK, respBody)
		return
	}
	if autopilot.Status == "archived" {
		respBody := map[string]any{"status": "ignored", "delivery_id": uuidToString(delivery.ID), "reason": "autopilot_archived"}
		h.finaliseDeliveryTerminal(r, delivery.ID, deliveryStatusIgnored, http.StatusOK, respBody, "autopilot_archived")
		writeJSON(w, http.StatusOK, respBody)
		return
	}
	if autopilot.Status != "active" {
		respBody := map[string]any{"status": "ignored", "delivery_id": uuidToString(delivery.ID), "reason": "autopilot_paused"}
		h.finaliseDeliveryTerminal(r, delivery.ID, deliveryStatusIgnored, http.StatusOK, respBody, "autopilot_paused")
		writeJSON(w, http.StatusOK, respBody)
		return
	}

	// 10. Event filter scope → ignored. If the trigger declares a concrete
	//     event_filters list and the incoming event is outside that scope,
	//     record an ignored delivery without creating an expensive run/task.
	if decision := evaluateWebhookTriggerScope(trigRow.EventFilters, envelope); !decision.Allowed {
		respBody := map[string]any{
			"status":      "ignored",
			"delivery_id": uuidToString(delivery.ID),
			"reason":      decision.ReasonCode,
			"event":       envelope.Event,
		}
		h.finaliseDeliveryTerminal(r, delivery.ID, deliveryStatusIgnored, http.StatusOK, respBody, decision.storedError(), decision.ReasonCode)
		writeJSON(w, http.StatusOK, respBody)
		return
	}

	// 11. Allocate the idempotent run synchronously so existing webhook clients
	//     keep the v0.4.0 response contract. The queued delivery remains the
	//     durable dispatch source: the worker resumes this run after the response
	//     and can recover it after a process crash.
	run, err := h.AutopilotService.AdmitAutopilotWebhookDelivery(
		r.Context(),
		autopilot,
		trigRow.ID,
		envelopeBytes,
		delivery.ID,
	)
	if err != nil {
		var quotaErr *service.AutopilotQuotaExceededError
		if errors.As(err, &quotaErr) {
			respBody := map[string]any{
				"status": "ignored", "delivery_id": uuidToString(delivery.ID),
				"reason_code": "quota_exceeded",
			}
			h.finaliseDeliveryTerminal(r, delivery.ID, deliveryStatusIgnored, http.StatusOK, respBody, quotaErr.Error(), "quota_exceeded")
			writeJSON(w, http.StatusOK, respBody)
			return
		}
		slog.Warn("webhook admission failed",
			"trigger_id", uuidToString(trigRow.ID),
			"autopilot_id", uuidToString(autopilot.ID),
			"delivery_id", uuidToString(delivery.ID),
			"error", err,
		)
		if h.WebhookDeliveryWorker != nil {
			h.WebhookDeliveryWorker.Notify()
		}
		writeError(w, http.StatusInternalServerError, "failed to admit autopilot")
		return
	}

	respBody := map[string]any{
		"status":       "accepted",
		"delivery_id":  uuidToString(delivery.ID),
		"run_id":       uuidToString(run.ID),
		"autopilot_id": uuidToString(autopilot.ID),
		"trigger_id":   uuidToString(trigRow.ID),
	}
	if run.Status == "skipped" {
		respBody = map[string]any{
			"status":      "skipped",
			"delivery_id": uuidToString(delivery.ID),
			"run_id":      uuidToString(run.ID),
		}
		if run.FailureReason.Valid {
			respBody["reason"] = run.FailureReason.String
		}
	}
	bodyJSON, _ := json.Marshal(respBody)
	if _, err := h.Queries.AcknowledgeWebhookDelivery(r.Context(), db.AcknowledgeWebhookDeliveryParams{
		ID:             delivery.ID,
		ResponseStatus: pgtype.Int4{Int32: http.StatusOK, Valid: true},
		ResponseBody:   pgtype.Text{String: string(bodyJSON), Valid: true},
	}); err != nil {
		slog.Warn("webhook: persist acknowledgement metadata failed",
			"delivery_id", uuidToString(delivery.ID),
			"error", err,
		)
	}
	if h.WebhookDeliveryWorker != nil {
		h.WebhookDeliveryWorker.Notify()
	}
	writeJSON(w, http.StatusOK, respBody)
}

func (h *Handler) HandleGitHubWebhook(w http.ResponseWriter, r *http.Request) {
	body, err := io.ReadAll(io.LimitReader(r.Body, 10<<20)) // 10 MiB cap
	if err != nil {
		writeError(w, http.StatusBadRequest, "read body failed")
		return
	}
	secret := githubWebhookSecret()
	if secret == "" {
		// Refusing to process webhooks at all is safer than treating an
		// unconfigured deployment as "all signatures valid".
		writeError(w, http.StatusNotFound, "not found")
		return
	}
	sigHeader := r.Header.Get("X-Hub-Signature-256")
	if !verifyWebhookSignature(secret, sigHeader, body) {
		writeError(w, http.StatusUnauthorized, "invalid signature")
		return
	}
	event := r.Header.Get("X-GitHub-Event")
	ctx := r.Context()
	switch event {
	case "ping":
		writeJSON(w, http.StatusOK, map[string]string{"ok": "pong"})
		return
	case "installation":
		h.handleInstallationEvent(ctx, body)
	case "pull_request":
		h.handlePullRequestEvent(ctx, body)
	case "check_suite", "check_run", "status":
		// CI events are pure triggers under Plan C (MUL-5265): their payload is
		// never read for display. Each just asks the API pipeline to re-fetch
		// the authoritative snapshot for the PR(s) it concerns.
		h.triggerPRRefreshFromCIEvent(ctx, body)
	default:
		// Acknowledge every event so GitHub doesn't mark the endpoint failing,
		// but ignore types we don't model.
	}
	w.WriteHeader(http.StatusAccepted)
}

func (h *Handler) GitHubSetupCallback(w http.ResponseWriter, r *http.Request) {
	q := r.URL.Query()
	installationIDStr := q.Get("installation_id")
	state := q.Get("state")
	frontend := strings.TrimSpace(os.Getenv("FRONTEND_ORIGIN"))
	if frontend == "" {
		frontend = "http://localhost:3000"
	}
	settingsURL := githubSettingsURL(frontend)

	if state == "" {
		http.Redirect(w, r, settingsURL+"&github_error=missing_params", http.StatusFound)
		return
	}
	workspaceID, connectionID, ok := verifyGitHubState(state)
	if !ok {
		http.Redirect(w, r, settingsURL+"&github_error=invalid_state", http.StatusFound)
		return
	}
	if installationIDStr == "" {
		http.Redirect(w, r, settingsURL+"&github_error=missing_params", http.StatusFound)
		return
	}
	installationID, err := strconv.ParseInt(installationIDStr, 10, 64)
	if err != nil || installationID <= 0 {
		http.Redirect(w, r, settingsURL+"&github_error=bad_installation_id", http.StatusFound)
		return
	}
	wsUUID, err := parseStrictUUID(workspaceID)
	if err != nil {
		http.Redirect(w, r, settingsURL+"&github_error=bad_workspace", http.StatusFound)
		return
	}
	workspace, err := h.Queries.GetWorkspace(r.Context(), wsUUID)
	if err != nil {
		http.Redirect(w, r, settingsURL+"&github_error=bad_workspace", http.StatusFound)
		return
	}
	settingsURL = strings.TrimRight(frontend, "/") + "/" + url.PathEscape(workspace.Slug) + "/settings?tab=code"
	rows, err := h.Queries.ListGitHubInstallationsByWorkspace(r.Context(), wsUUID)
	if err != nil {
		http.Redirect(w, r, settingsURL+"&github_error=verification_failed", http.StatusFound)
		return
	}
	var inst db.GithubInstallation
	existing := false
	for _, row := range rows {
		if row.InstallationID == installationID {
			inst, existing = row, true
			break
		}
	}
	// Repository-selection updates may carry no OAuth code. Reuse only a
	// binding this workspace already has, without recreating or changing it.
	if !existing {
		if err := verifyGitHubInstallationOwnership(r.Context(), q.Get("code"), installationID); err != nil {
			slog.Warn("github: refused unverified installation bind", "err", err,
				"workspace_id", workspaceID, "installation_id", installationID)
			http.Redirect(w, r, settingsURL+"&github_error="+githubOwnershipErrorCode(err), http.StatusFound)
			return
		}
		// Resolve the installation against GitHub's API to capture display info.
		// If the App auth is not configured we still create the row with the
		// minimum we know; webhook events will refresh it as soon as one fires.
		login, accountType, avatar := fetchInstallationAccount(r.Context(), installationID)

		// Best-effort capture of the connecting user (may be nil if the public
		// callback was hit without a session — e.g. user wasn't logged in to
		// Workpal when they finished the GitHub install). Either way we save
		// the row so the workspace owner sees the connection on next reload.
		connectedBy := pgtype.UUID{}
		if userID := requestUserID(r); userID != "" {
			if u, err := parseStrictUUID(userID); err == nil {
				connectedBy = u
			}
		}

		inst, err = h.Queries.CreateGitHubInstallation(r.Context(), db.CreateGitHubInstallationParams{
			WorkspaceID:      wsUUID,
			InstallationID:   installationID,
			AccountLogin:     login,
			AccountType:      accountType,
			AccountAvatarUrl: ptrToText(avatar),
			ConnectedByID:    connectedBy,
		})
		if err != nil {
			slog.Error("github: failed to persist installation", "err", err, "installation_id", installationID)
			http.Redirect(w, r, settingsURL+"&github_error=persist_failed", http.StatusFound)
			return
		}
		inst, err = h.consumePendingGitHubInstallation(r.Context(), inst)
		if err != nil {
			slog.Error("github: failed to apply pending installation metadata", "err", err, "installation_id", installationID)
			http.Redirect(w, r, settingsURL+"&github_error=persist_failed", http.StatusFound)
			return
		}
	}
	h.publish(protocol.EventGitHubInstallationCreated, workspaceID, "system", "", map[string]any{
		"installation":  githubInstallationToBroadcast(inst),
		"connection_id": connectionID,
	})
	if strings.HasPrefix(connectionID, "desktop-") {
		w.Header().Set("Content-Type", "text/html; charset=utf-8")
		_, _ = io.WriteString(w, `<!doctype html><html lang="en"><meta charset="utf-8"><title>GitHub connected</title><body><h1>GitHub connected</h1><p>Return to Workpal to confirm your repositories. You can close this tab.</p></body></html>`)
		return
	}
	http.Redirect(w, r, settingsURL+"&github_connected=1&github_installation="+url.QueryEscape(uuidToString(inst.ID)), http.StatusFound)
}

func (h *Handler) HandleVCSWebhook(w http.ResponseWriter, r *http.Request) {
	// Where the integration is off (the managed cloud) the endpoint behaves as
	// if it does not exist — a bare 404 that reveals nothing about config, the
	// same response a genuinely unknown connection id gets below.
	if !h.isVCSAvailable() {
		writeError(w, http.StatusNotFound, "unknown connection")
		return
	}
	if !h.isVCSConfigured() {
		writeError(w, http.StatusNotFound, "unknown connection")
		return
	}
	connUUID, ok := parseUUIDOrBadRequest(w, chi.URLParam(r, "connectionId"), "connection id")
	if !ok {
		return
	}
	body, err := io.ReadAll(io.LimitReader(r.Body, 10<<20)) // 10 MiB cap
	if err != nil {
		writeError(w, http.StatusBadRequest, "read body failed")
		return
	}

	conn, err := h.Queries.GetVCSConnectionByID(r.Context(), connUUID)
	if err != nil {
		if !errors.Is(err, pgx.ErrNoRows) {
			slog.Warn("vcs: lookup connection failed", "err", err)
		}
		writeError(w, http.StatusNotFound, "unknown connection")
		return
	}
	provider, ok := vcs.For(conn.Provider)
	if !ok {
		slog.Error("vcs: connection has unknown provider", "provider", conn.Provider)
		writeError(w, http.StatusInternalServerError, "unknown provider")
		return
	}

	secret, err := h.openVCSSecret(conn.WebhookSecretEncrypted)
	if err != nil {
		slog.Error("vcs: decrypt webhook secret failed", "err", err)
		writeError(w, http.StatusInternalServerError, "secret error")
		return
	}
	if !provider.VerifySignature(secret, r.Header, body) {
		writeError(w, http.StatusUnauthorized, "invalid signature")
		return
	}

	systemHook := conn.Provider == string(vcs.KindGitLab) && r.Header.Get("X-Gitlab-Event") == "System Hook"
	switch provider.EventKind(r.Header, body) {
	case vcs.EventPullRequest:
		if pr, err := provider.ParsePullRequest(body); err != nil {
			slog.Warn("vcs: bad pull_request payload", "provider", conn.Provider, "err", err)
		} else {
			if systemHook {
				ws, err := h.Queries.GetWorkspace(r.Context(), conn.WorkspaceID)
				if err != nil {
					slog.Warn("vcs: load workspace for system hook failed", "err", err)
					writeError(w, http.StatusServiceUnavailable, "workspace lookup failed")
					return
				}
				if !gitLabSystemHookRepoAllowed(ws.Repos, conn.InstanceUrl, pr.RepoOwner, pr.RepoName) {
					break
				}
				if checker, ok := provider.(vcs.RepositoryAccessChecker); ok {
					token, err := h.openVCSSecret(conn.AccessTokenEncrypted)
					if err != nil || token == "" {
						slog.Warn("vcs: open access token for system hook failed", "err", err)
						writeError(w, http.StatusInternalServerError, "access token error")
						return
					}
					readable, err := checker.RepositoryReadable(r.Context(), conn.InstanceUrl, pr.RepoOwner, pr.RepoName, token)
					if err != nil {
						slog.Warn("vcs: system-hook repository access lookup failed", "provider", conn.Provider, "err", err)
						writeError(w, http.StatusServiceUnavailable, "repository access lookup failed")
						return
					}
					if !readable {
						break
					}
				}
			}
			h.mirrorVCSPullRequest(r.Context(), conn, pr)
		}
	case vcs.EventCIStatus:
		if st, err := provider.ParseCIStatus(body); err != nil {
			slog.Warn("vcs: bad status payload", "provider", conn.Provider, "err", err)
		} else {
			h.mirrorVCSCIStatus(r.Context(), conn, st)
		}
	default:
		// Acknowledge unmodelled events so the provider doesn't flag the hook.
	}
	w.WriteHeader(http.StatusAccepted)
}

func (h *Handler) HandleCloudBillingStripeWebhook(w http.ResponseWriter, r *http.Request) {
	if h.CloudRuntime == nil || !h.CloudRuntime.Enabled() {
		writeFeatureDisabled(w, "cloud_runtime_not_configured", "cloud runtime is not configured")
		return
	}

	// Per-IP rate limit BEFORE reading the body or hitting upstream.
	// We deliberately reuse the same limiter as the autopilot
	// webhook: both are public unauthenticated ingress with the same
	// abuse profile, and budgeting them together gives a single knob
	// to tune.
	if h.WebhookIPRateLimiter != nil {
		if ip := h.clientIPForRateLimit(r); ip != "" {
			if !h.WebhookIPRateLimiter.Allow(r.Context(), ip) {
				writeError(w, http.StatusTooManyRequests, "rate limit exceeded")
				return
			}
		}
	}

	// Real Stripe deliveries always include Stripe-Signature; the
	// absence is a confident "not from Stripe" signal. Reject locally
	// to save the upstream RTT. NOTE: we use Header.Values to detect
	// presence rather than Get, so a header explicitly set to "" still
	// counts as missing (matches the upstream's interpretation).
	if len(r.Header.Values(stripeSignatureHeader)) == 0 {
		writeError(w, http.StatusUnauthorized, "missing Stripe-Signature header")
		return
	}

	// Body cap matches the JSON proxy. Stripe's documented payload
	// ceiling is much smaller; the limit is defense, not contract.
	r.Body = http.MaxBytesReader(w, r.Body, maxStripeWebhookBodySize)
	// io.ReadAll is appropriate here because the webhook body is
	// fully consumed before forwarding (Stripe signs the bytes; we
	// can't stream). Unlike the JSON proxy we deliberately do NOT
	// trim whitespace or json-validate — the upstream signature
	// check is computed over exactly what we received, so any
	// transformation here would silently break verification.
	body, err := io.ReadAll(r.Body)
	if err != nil {
		var maxErr *http.MaxBytesError
		if errors.As(err, &maxErr) {
			writeError(w, http.StatusRequestEntityTooLarge, "request body is too large")
			return
		}
		writeError(w, http.StatusBadRequest, "invalid request body")
		return
	}

	// Forward Stripe-Signature verbatim, plus Stripe's original
	// Content-Type (so the upstream sees the exact same header set
	// it would if Stripe were calling it directly). cloudruntime's
	// default Content-Type would override `application/json;
	// charset=utf-8` to plain `application/json`; signature
	// verification doesn't care (HMAC is over the body), but
	// preserving the exact header is cheap and removes a debug-time
	// "why does this header look different?" surprise. Caller-
	// supplied Headers in cloudruntime.Request override defaults, so
	// putting Content-Type here is enough.
	headers := http.Header{}
	if sigs := r.Header.Values(stripeSignatureHeader); len(sigs) > 0 {
		headers[stripeSignatureHeader] = sigs
	}
	if cts := r.Header.Values("Content-Type"); len(cts) > 0 {
		headers["Content-Type"] = cts
	}

	resp, err := h.CloudRuntime.Do(r.Context(), cloudruntime.Request{
		Method:    http.MethodPost,
		Path:      "/api/v1/webhooks/stripe",
		Body:      body,
		Headers:   headers,
		RequestID: cloudRuntimeRequestID(r),
		Op:        "billing",
		// Intentionally no UserID — webhook is unauthenticated by
		// design; injecting an empty header would still be harmless,
		// but staying explicit makes the contract obvious to readers.
	})
	if err != nil {
		writeCloudRuntimeError(w, r, err)
		return
	}
	writeCloudRuntimeResponse(w, resp)
}

func (h *Handler) ComposioCallback(w http.ResponseWriter, r *http.Request) {
	if h.Composio == nil || !h.composioMCPAppsEnabled(r.Context()) {
		writeFeatureDisabled(w, "composio_not_configured", "composio integration not configured")
		return
	}
	q := r.URL.Query()
	state := q.Get("state")
	status := q.Get("status")
	connectedAccountID := q.Get("connected_account_id")

	result, err := h.Composio.CompleteCallback(r.Context(), state, status, connectedAccountID)
	if err != nil {
		// Every failure (tampered/expired state, non-success status, write
		// error) collapses to the generic failure redirect — we never tell the
		// browser which check failed.
		http.Redirect(w, r, h.Composio.CallbackRedirect(result, false), http.StatusFound)
		return
	}
	if h.ConnectedApps != nil && !result.Team() {
		if userID, perr := parseUUIDStrict(result.UserID); perr == nil {
			h.ConnectedApps.ResolveConnectRequests(r.Context(), userID, result.ToolkitSlug)
		}
	}
	http.Redirect(w, r, h.Composio.CallbackRedirect(result, true), http.StatusFound)
}

func (h *Handler) AppsGateway(w http.ResponseWriter, r *http.Request) {
	if h.ConnectedApps == nil || !h.composioMCPAppsEnabled(r.Context()) {
		http.Error(w, "connected apps are not configured", http.StatusServiceUnavailable)
		return
	}
	h.ConnectedApps.ServeHTTP(w, r)
}

func (h *Handler) DaemonRegister(w http.ResponseWriter, r *http.Request) {
	var req DaemonRegisterRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid request body")
		return
	}

	req.WorkspaceID = strings.TrimSpace(req.WorkspaceID)
	req.DaemonID = strings.TrimSpace(req.DaemonID)
	req.DeviceName = strings.TrimSpace(req.DeviceName)

	if req.DaemonID == "" {
		writeError(w, http.StatusBadRequest, "daemon_id is required")
		return
	}
	if req.WorkspaceID == "" {
		writeError(w, http.StatusBadRequest, "workspace_id is required")
		return
	}
	if len(req.Runtimes) == 0 && len(req.FailedProfiles) == 0 {
		writeError(w, http.StatusBadRequest, "at least one runtime or failed profile is required")
		return
	}
	// Validate all entries before writing any registration. Custom profiles
	// launch a local command and cannot declare managed cloud execution.
	for i := range req.Runtimes {
		rt := &req.Runtimes[i]
		if rt.RuntimeMode == "" {
			rt.RuntimeMode = "local"
		}
		if (rt.RuntimeMode != "local" && rt.RuntimeMode != "cloud") || (rt.ProfileID != "" && rt.RuntimeMode != "local") {
			writeError(w, http.StatusBadRequest, "invalid runtime_mode for registration")
			return
		}
	}
	wsUUID, ok := parseUUIDOrBadRequest(w, req.WorkspaceID, "workspace_id")
	if !ok {
		return
	}
	req.WorkspaceID = uuidToString(wsUUID)
	if id := middleware.DaemonIDFromContext(r.Context()); id != "" && id != req.DaemonID {
		writeError(w, http.StatusForbidden, "daemon identity mismatch")
		return
	}
	// Qoder-managed daemon tokens are exempt from the owner binding below,
	// so the exemption is granted only after the token is proven to belong to
	// a live cloud_agent_connection — unconditionally, not just when the body
	// declares a qoder_cloud runtime (MUL-8154 review round 4). Pre-upgrade
	// tokens under this prefix were issued for ordinary runtimes and carry no
	// such binding. The bridge only ever registers one built-in qoder_cloud
	// runtime, so anything else under this namespace is refused too.
	if tokenDaemonID := middleware.DaemonIDFromContext(r.Context()); tokenDaemonID != "" && isQoderManagedDaemonID(tokenDaemonID) {
		allowed, err := h.qoderCredentialAllowed(r, req.WorkspaceID, req.DaemonID)
		if err != nil {
			writeError(w, http.StatusServiceUnavailable, "runtime authorization unavailable")
			return
		}
		if !allowed {
			writeError(w, http.StatusForbidden, "managed runtime credential required")
			return
		}
		if len(req.FailedProfiles) > 0 {
			writeError(w, http.StatusForbidden, "managed runtime registration must be a single qoder_cloud runtime")
			return
		}
		for _, rt := range req.Runtimes {
			if normalizeProvider(rt.Type) != "qoder_cloud" || strings.TrimSpace(rt.ProfileID) != "" {
				writeError(w, http.StatusForbidden, "managed runtime registration must be a single qoder_cloud runtime")
				return
			}
		}
	}
	for _, rt := range req.Runtimes {
		if normalizeProvider(rt.Type) != "qoder_cloud" {
			continue
		}
		if middleware.DaemonIDFromContext(r.Context()) != "" {
			allowed, err := h.qoderCredentialAllowed(r, req.WorkspaceID, req.DaemonID)
			if err != nil || !allowed {
				writeError(w, http.StatusForbidden, "managed runtime credential required")
				return
			}
		} else {
			member, ok := h.requireWorkspaceMember(w, r, req.WorkspaceID, "workspace not found")
			if !ok {
				return
			}
			if !roleAllowed(member.Role, "owner", "admin") {
				writeError(w, http.StatusForbidden, "workspace administrator required")
				return
			}
		}
	}

	// Verify workspace access and resolve owner.
	//   - User credential (PAT/JWT): membership check; the member is the owner.
	//   - Non-Qoder daemon token: the owner the token is bound to (MUL-8154).
	//     The same pre-check and SQL fence apply, so a token issued for one
	//     owner cannot rewrite a runtime another member re-registered under
	//     this daemon_id. Unbound tokens (pre-588) are refused.
	//   - Qoder-managed daemon token: ownerID stays zero (COALESCE keeps the
	//     existing owner); the credential was checked against its
	//     cloud_agent_connection above.
	// mergeOwnerID is set only for user credentials: daemon tokens never
	// trigger legacy merges.
	var ownerID, mergeOwnerID pgtype.UUID
	if daemonWsID := middleware.DaemonWorkspaceIDFromContext(r.Context()); daemonWsID != "" {
		if daemonWsID != req.WorkspaceID {
			writeError(w, http.StatusNotFound, "workspace not found")
			return
		}
		if !isQoderManagedDaemonID(req.DaemonID) {
			tokenOwner := middleware.DaemonTokenOwnerIDFromContext(r.Context())
			if tokenOwner == "" {
				writeError(w, http.StatusForbidden, "daemon credential is not bound to a runtime owner")
				return
			}
			ownerUUID, err := util.ParseUUID(tokenOwner)
			if err != nil {
				writeError(w, http.StatusForbidden, "daemon credential is not bound to a runtime owner")
				return
			}
			ownerID = ownerUUID
		}
	} else {
		member, ok := h.requireWorkspaceMember(w, r, req.WorkspaceID, "workspace not found")
		if !ok {
			return
		}
		ownerID = member.UserID
		mergeOwnerID = member.UserID

		// The Qoder-managed namespace is reserved for the server's bridge
		// and its daemon token, which is not owner-bound; a member must not
		// be able to own a runtime that token would reach (MUL-8154).
		if isQoderManagedDaemonID(req.DaemonID) {
			writeError(w, http.StatusForbidden, "reserved daemon_id")
			return
		}
	}

	ws, err := h.Queries.GetWorkspace(r.Context(), wsUUID)
	if err != nil {
		writeError(w, http.StatusNotFound, "workspace not found")
		return
	}

	// One transaction for the ownership pre-check and every runtime write,
	// serialized per (workspace, daemon_id) for both auth paths (MUL-8154
	// review). The pre-check and the per-provider / per-profile upserts hit
	// different conflict keys, so without this two members registering
	// different providers of the same daemon could both read "no rows" and
	// both insert — one daemon, two owners, and a daemon token minted for
	// either runtime would then reach the other's. A failure anywhere rolls
	// the whole registration back. Legacy merges, analytics and the
	// register event run only after commit.
	tx, err := h.beginDaemonRegistration(r.Context(), req.WorkspaceID, req.DaemonID)
	if err != nil {
		slog.Warn("register: begin registration failed", append(logger.RequestAttrs(r), "error", err)...)
		writeError(w, http.StatusServiceUnavailable, "failed to register runtime")
		return
	}
	defer tx.Rollback(context.Background())
	qtx := h.Queries.WithTx(tx)
	var afterCommit []func()

	if ownerID.Valid {
		// Ownership pre-check: every row this daemon_id already holds in
		// the workspace must belong to the caller — including ownerless
		// rows, which ordinary registration must not silently claim. The
		// upserts keep the same fence in SQL (required_owner_id) as
		// defense in depth.
		existing, err := qtx.ListRuntimeOwnersByDaemon(r.Context(), db.ListRuntimeOwnersByDaemonParams{
			WorkspaceID: wsUUID,
			DaemonID:    strToText(req.DaemonID),
		})
		if err != nil {
			slog.Warn("register: runtime owner pre-check failed", append(logger.RequestAttrs(r), "error", err)...)
			writeError(w, http.StatusInternalServerError, "failed to register runtime")
			return
		}
		for _, row := range existing {
			if !row.OwnerID.Valid || row.OwnerID != ownerID {
				slog.Warn("register: refused runtime owned by another user",
					"workspace_id", req.WorkspaceID, "daemon_id", req.DaemonID,
					"runtime_id", uuidToString(row.ID))
				writeError(w, http.StatusForbidden, runtimeOwnedByAnotherUserMessage)
				return
			}
		}
	}

	resp := make([]AgentRuntimeResponse, 0, len(req.Runtimes))
	for _, runtime := range req.Runtimes {
		provider := normalizeProvider(runtime.Type)
		if provider == "" {
			provider = "unknown"
		}
		name := strings.TrimSpace(runtime.Name)
		if name == "" {
			name = provider
			if req.DeviceName != "" {
				name = fmt.Sprintf("%s (%s)", provider, req.DeviceName)
			}
		}
		deviceInfo := strings.TrimSpace(req.DeviceName)
		if runtime.Version != "" && deviceInfo != "" {
			deviceInfo = fmt.Sprintf("%s · %s", deviceInfo, runtime.Version)
		} else if runtime.Version != "" {
			deviceInfo = runtime.Version
		}
		status := "online"
		if runtime.Status == "offline" {
			status = "offline"
		}
		// Persist what this daemon advertised, so surfaces that cannot see the
		// live request — the resource-save gate and the UI — decide from the
		// same signal the claim path uses, instead of re-deriving it from a
		// version string (MUL-5707).
		metadata, _ := json.Marshal(map[string]any{
			"version":      runtime.Version,
			"cli_version":  req.CLIVersion,
			"launched_by":  req.LaunchedBy,
			"capabilities": requestClientCapabilities(r),
		})

		var registered db.AgentRuntime
		var inserted bool
		isCustom := strings.TrimSpace(runtime.ProfileID) != ""

		if isCustom {
			profileUUID, pok := parseUUIDOrBadRequest(w, strings.TrimSpace(runtime.ProfileID), "profile_id")
			if !pok {
				return
			}
			// The profile must exist in this workspace and be enabled. Trust
			// the profile's stored runtime identity over the daemon-sent type so
			// the provider used for task routing cannot drift from the profile.
			prow, profile, err := h.upsertRuntimeWithProfile(
				r.Context(),
				qtx,
				wsUUID,
				profileUUID,
				func(profile db.RuntimeProfile) db.UpsertAgentRuntimeWithProfileParams {
					return db.UpsertAgentRuntimeWithProfileParams{
						WorkspaceID: wsUUID,
						DaemonID:    strToText(req.DaemonID),
						Name:        name,
						RuntimeMode: "local",
						Provider:    agent.ProfileRuntimeType(profile.RuntimeType, profile.ProtocolFamily),
						Status:      status,
						DeviceInfo:  deviceInfo,
						Metadata:    metadata,
						OwnerID:     ownerID,
						ProfileID:   profileUUID,
						// Ownership fence: zero (no fence) on the daemon-token
						// path, the caller on the user-credential path.
						RequiredOwnerID: ownerID,
					}
				},
			)
			if errors.Is(err, errRuntimeOwnedByAnotherUser) {
				writeError(w, http.StatusForbidden, runtimeOwnedByAnotherUserMessage)
				return
			}
			if errors.Is(err, pgx.ErrNoRows) {
				writeError(w, http.StatusBadRequest, "unknown runtime profile: "+runtime.ProfileID)
				return
			}
			if errors.Is(err, errRuntimeProfileDisabled) {
				writeError(w, http.StatusConflict, "runtime profile is disabled: "+runtime.ProfileID)
				return
			}
			if errors.Is(err, errRuntimeProfileMachine) {
				// Old daemons may still submit a previously shared profile.
				// Ignore it without blocking built-in runtime registration.
				continue
			}
			if err != nil {
				obsmetrics.RecordEvent(h.Analytics, h.Metrics, analytics.RuntimeFailed(
					uuidToString(ownerID),
					req.WorkspaceID,
					req.DaemonID,
					provider,
					"registration_failed",
					"db_error",
					true,
				))
				slog.Warn("register runtime failed", append(logger.RequestAttrs(r), "error", err)...)
				writeError(w, http.StatusInternalServerError, "failed to register runtime")
				return
			}
			provider = agent.ProfileRuntimeType(profile.RuntimeType, profile.ProtocolFamily)
			inserted = prow.Inserted
			registered = db.AgentRuntime{
				ID:             prow.ID,
				WorkspaceID:    prow.WorkspaceID,
				DaemonID:       prow.DaemonID,
				Name:           prow.Name,
				CustomName:     prow.CustomName,
				RuntimeMode:    prow.RuntimeMode,
				Provider:       prow.Provider,
				Status:         prow.Status,
				DeviceInfo:     prow.DeviceInfo,
				Metadata:       prow.Metadata,
				LastSeenAt:     prow.LastSeenAt,
				CreatedAt:      prow.CreatedAt,
				UpdatedAt:      prow.UpdatedAt,
				OwnerID:        prow.OwnerID,
				LegacyDaemonID: prow.LegacyDaemonID,
				Visibility:     prow.Visibility,
				SharedWith:     prow.SharedWith,
				ProfileID:      prow.ProfileID,
			}
		} else {
			row, err := qtx.UpsertAgentRuntime(r.Context(), db.UpsertAgentRuntimeParams{
				WorkspaceID: wsUUID,
				DaemonID:    strToText(req.DaemonID),
				Name:        name,
				RuntimeMode: runtime.RuntimeMode,
				Provider:    provider,
				Status:      status,
				DeviceInfo:  deviceInfo,
				Metadata:    metadata,
				OwnerID:     ownerID,
				// See the profile branch: the SQL fence that backs the
				// pre-check against a concurrent registration.
				RequiredOwnerID: ownerID,
			})
			if errors.Is(err, pgx.ErrNoRows) {
				writeError(w, http.StatusForbidden, runtimeOwnedByAnotherUserMessage)
				return
			}
			if err != nil {
				obsmetrics.RecordEvent(h.Analytics, h.Metrics, analytics.RuntimeFailed(
					uuidToString(ownerID),
					req.WorkspaceID,
					req.DaemonID,
					provider,
					"registration_failed",
					"db_error",
					true,
				))
				slog.Warn("register runtime failed", append(logger.RequestAttrs(r), "error", err)...)
				writeError(w, http.StatusInternalServerError, "failed to register runtime")
				return
			}
			inserted = row.Inserted
			registered = db.AgentRuntime{
				ID:             row.ID,
				WorkspaceID:    row.WorkspaceID,
				DaemonID:       row.DaemonID,
				Name:           row.Name,
				CustomName:     row.CustomName,
				RuntimeMode:    row.RuntimeMode,
				Provider:       row.Provider,
				Status:         row.Status,
				DeviceInfo:     row.DeviceInfo,
				Metadata:       row.Metadata,
				LastSeenAt:     row.LastSeenAt,
				CreatedAt:      row.CreatedAt,
				UpdatedAt:      row.UpdatedAt,
				OwnerID:        row.OwnerID,
				LegacyDaemonID: row.LegacyDaemonID,
				Visibility:     row.Visibility,
				SharedWith:     row.SharedWith,
				ProfileID:      row.ProfileID,
			}
		}

		// A brand-new runtime on an already-named machine inherits the machine's
		// shared custom name so the machine title stays stable as providers come
		// and go (MUL-4217). Shared with the failed-profile path below.
		registered = h.inheritMachineCustomName(r.Context(), qtx, registered, inserted)

		// Inserted is false for normal daemon reconnects/upserts, so
		// runtime_ready is a first-ready-per-runtime-row signal.
		if inserted {
			registered, provider, runtime := registered, provider, runtime
			afterCommit = append(afterCommit, func() {
				obsmetrics.RecordEvent(h.Analytics, h.Metrics, analytics.RuntimeRegistered(
					uuidToString(ownerID),
					req.WorkspaceID,
					uuidToString(registered.ID),
					req.DaemonID,
					provider,
					runtime.Version,
					req.CLIVersion,
				))
				if registered.Status == "online" {
					obsmetrics.RecordEvent(h.Analytics, h.Metrics, analytics.RuntimeReady(
						uuidToString(ownerID),
						req.WorkspaceID,
						uuidToString(registered.ID),
						req.DaemonID,
						provider,
						0,
					))
				}
			})
		}

		// Seamless migration from the previous hostname-derived identity. The
		// daemon sends every legacy daemon_id it may have registered under
		// (e.g. "host.local", "host", "host-staging"); for each match we
		// reassign agents + tasks onto the new UUID-keyed row, then delete
		// the stale row so there's only ever one runtime per machine.
		//
		// Only built-in runtimes participate: legacy rows predate custom
		// profiles, so a profile-keyed instance never has a hostname-derived
		// ancestor to merge, and mergeLegacyRuntimes scopes by provider alone
		// (no profile_id), which could otherwise fold a built-in row into a
		// custom one of the same provider.
		// Merges lock both runtime rows in their own transaction, so they
		// must run after this registration commits the new row.
		if !isCustom {
			registered, provider := registered, provider
			afterCommit = append(afterCommit, func() {
				h.mergeLegacyRuntimes(r, registered, provider, req.LegacyDaemonIDs, mergeOwnerID)
			})
		}

		resp = append(resp, runtimeToResponse(registered))
	}
	for _, failed := range req.FailedProfiles {
		profileID := strings.TrimSpace(failed.ProfileID)
		if profileID == "" {
			continue
		}
		profileUUID, pok := parseUUIDOrBadRequest(w, profileID, "profile_id")
		if !pok {
			return
		}
		reason := strings.TrimSpace(failed.Reason)
		if reason == "" {
			reason = "custom runtime command could not be resolved"
		}
		commandName := strings.TrimSpace(failed.CommandName)
		// Best effort, as before: a savepoint keeps one failed record from
		// aborting the registration transaction.
		sp, err := tx.Begin(r.Context())
		if err != nil {
			slog.Warn("failed to record runtime profile registration failure",
				"workspace_id", req.WorkspaceID, "daemon_id", req.DaemonID,
				"profile_id", profileID, "error", err)
			continue
		}
		prow, _, err := h.upsertRuntimeWithProfile(
			r.Context(),
			h.Queries.WithTx(sp),
			wsUUID,
			profileUUID,
			func(profile db.RuntimeProfile) db.UpsertAgentRuntimeWithProfileParams {
				name := profile.DisplayName
				if req.DeviceName != "" {
					name = fmt.Sprintf("%s (%s)", name, req.DeviceName)
				}
				resolvedCommandName := commandName
				if resolvedCommandName == "" {
					resolvedCommandName = profile.CommandName
				}
				// Capabilities belong on this row too. It is written AFTER the
				// successful runtimes in the same request, so its last_seen_at is
				// the newest for this daemon until the first heartbeat — and the
				// worktree gates read the newest row. Omitting them made a failed
				// profile look, for that window, like a daemon that advertises
				// nothing (and now like a capability-blind server).
				metadata, _ := json.Marshal(map[string]any{
					"version":                            "",
					"cli_version":                        req.CLIVersion,
					"launched_by":                        req.LaunchedBy,
					"capabilities":                       requestClientCapabilities(r),
					"runtime_profile_registration_error": true,
					"runtime_profile_failure_reason":     reason,
					"command_name":                       resolvedCommandName,
				})
				return db.UpsertAgentRuntimeWithProfileParams{
					WorkspaceID:     wsUUID,
					DaemonID:        strToText(req.DaemonID),
					Name:            name,
					RuntimeMode:     "local",
					Provider:        agent.ProfileRuntimeType(profile.RuntimeType, profile.ProtocolFamily),
					Status:          "offline",
					DeviceInfo:      strings.TrimSpace(req.DeviceName),
					Metadata:        metadata,
					OwnerID:         ownerID,
					ProfileID:       profileUUID,
					RequiredOwnerID: ownerID,
				}
			},
		)
		if err != nil {
			_ = sp.Rollback(r.Context())
			slog.Warn("failed to record runtime profile registration failure",
				"workspace_id", req.WorkspaceID, "daemon_id", req.DaemonID,
				"profile_id", profileID, "error", err)
			continue
		}
		if err := sp.Commit(r.Context()); err != nil {
			slog.Warn("failed to record runtime profile registration failure",
				"workspace_id", req.WorkspaceID, "daemon_id", req.DaemonID,
				"profile_id", profileID, "error", err)
			continue
		}
		// Keep the failed-profile row consistent with the machine's name so it
		// doesn't drag the machine title back to the hostname (MUL-4217).
		h.inheritMachineCustomName(r.Context(), qtx, db.AgentRuntime{
			ID:          prow.ID,
			WorkspaceID: prow.WorkspaceID,
			DaemonID:    prow.DaemonID,
			CustomName:  prow.CustomName,
		}, prow.Inserted)
	}

	if err := tx.Commit(r.Context()); err != nil {
		slog.Warn("register: commit failed", append(logger.RequestAttrs(r), "error", err)...)
		writeError(w, http.StatusInternalServerError, "failed to register runtime")
		return
	}
	for _, fn := range afterCommit {
		fn()
	}

	slog.Info("daemon registered", "workspace_id", req.WorkspaceID, "daemon_id", req.DaemonID, "runtimes_count", len(resp))

	h.publish(protocol.EventDaemonRegister, req.WorkspaceID, "system", "", map[string]any{
		"runtimes": resp,
	})

	repoResp := workspaceReposResponse(req.WorkspaceID, ws.Repos, ws.Settings, h.cfg.GitExtraCACerts)

	body := map[string]any{
		"runtimes":      resp,
		"repos":         repoResp.Repos,
		"repos_version": repoResp.ReposVersion,
		"settings":      repoResp.Settings,
	}
	if repoResp.CACerts != "" {
		body["ca_certs"] = repoResp.CACerts
	}
	writeJSON(w, http.StatusOK, body)
}

func (h *Handler) DaemonDeregister(w http.ResponseWriter, r *http.Request) {
	var req struct {
		RuntimeIDs []string `json:"runtime_ids"`
		// OfflineReasons is optional and keyed by runtime id. Present only for
		// causes the user must repair — a daemon shutting down sends none, so an
		// older daemon simply keeps today's behaviour (MUL-6164).
		OfflineReasons map[string]json.RawMessage `json:"offline_reasons"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid request body")
		return
	}

	if len(req.RuntimeIDs) == 0 {
		writeError(w, http.StatusBadRequest, "runtime_ids is required")
		return
	}
	runtimeUUIDs, ok := parseUUIDSliceOrBadRequest(w, req.RuntimeIDs, "runtime_ids")
	if !ok {
		return
	}

	// Track affected workspaces for WS notifications.
	affectedWorkspaces := make(map[string]bool)

	// Batch the runtime lookups instead of one GetAgentRuntime per id (N+1),
	// while keeping the MUL-6884 per-source attribution: getAgentRuntimes
	// records one workpal_agent_runtime_lookup_total result per requested id.
	// A read error is NOT "the rows don't exist": fail closed with 500 (like
	// ListRuntimesForClaim) so a transient blip can't report a successful
	// deregister while every runtime silently stays online until the liveness
	// sweep reaps it. GetMany keys rows by canonical UUID string so a
	// differently-cased request id still matches; a genuinely missing id is
	// simply absent from the map and falls through to the "runtime not found"
	// skip below, preserving the per-runtime verify / setOffline semantics.
	runtimesByID, err := h.getAgentRuntimes(r.Context(), obsmetrics.RuntimeLookupSourceDaemonAPI, runtimeUUIDs)
	if err != nil {
		slog.Error("deregister: batch runtime lookup failed", "error", err)
		writeError(w, http.StatusInternalServerError, "failed to load runtimes")
		return
	}

	for i, rid := range req.RuntimeIDs {
		// Look up the runtime and verify ownership. Key by the parsed UUID's
		// canonical form (runtimeUUIDs[i]) so a differently-cased request id
		// still matches the row; rid is kept for OfflineReasons and logging.
		rt, ok := runtimesByID[uuidToString(runtimeUUIDs[i])]
		if !ok {
			slog.Warn("deregister: runtime not found", "runtime_id", rid)
			continue
		}

		wsID := uuidToString(rt.WorkspaceID)
		if !h.verifyDaemonRuntimeAuthorized(r, rt) {
			slog.Warn("deregister: runtime not authorized for caller", "runtime_id", rid)
			continue
		}

		if err := h.setRuntimeOffline(r.Context(), rt.ID, req.OfflineReasons[rid]); err != nil {
			slog.Warn("deregister: failed to set offline", "runtime_id", rid, "error", err)
			continue
		}
		obsmetrics.RecordEvent(h.Analytics, h.Metrics, analytics.RuntimeOffline(
			uuidToString(rt.OwnerID),
			wsID,
			uuidToString(rt.ID),
			rt.DaemonID.String,
			rt.Provider,
		))

		affectedWorkspaces[wsID] = true
	}

	// Notify frontend clients so they re-fetch runtime list.
	for wsID := range affectedWorkspaces {
		h.publish(protocol.EventDaemonRegister, wsID, "system", "", map[string]any{
			"action": "deregister",
		})
	}

	slog.Info("daemon deregistered", "runtime_ids", req.RuntimeIDs)
	writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
}

func (h *Handler) DaemonHeartbeat(w http.ResponseWriter, r *http.Request) {
	start := time.Now()
	authPath := middleware.DaemonAuthPathFromContext(r.Context())
	var (
		outcome                                                                                            = "unauth"
		runtimeID                                                                                          string
		decodeMs, runtimeLookupMs, workspaceCheckMs                                                        int64
		authMs, updateMs, probeModelMs, popModelMs, probeSkillsMs, popSkillsMs, probeImportMs, popImportMs int64
		probeModelTimedOut, probeSkillsTimedOut, probeImportTimedOut                                       bool
	)
	defer func() {
		logHeartbeatEndpointSlow(runtimeID, outcome, authPath, start, decodeMs, runtimeLookupMs, workspaceCheckMs, authMs, updateMs, probeModelMs, popModelMs, probeSkillsMs, popSkillsMs, probeImportMs, popImportMs, probeModelTimedOut, probeSkillsTimedOut, probeImportTimedOut)
	}()

	decodeStart := time.Now()
	var req DaemonHeartbeatRequest
	decodeErr := json.NewDecoder(r.Body).Decode(&req)
	decodeMs = time.Since(decodeStart).Milliseconds()
	if decodeErr != nil {
		outcome = "bad_body"
		writeError(w, http.StatusBadRequest, "invalid request body")
		return
	}

	if req.RuntimeID == "" {
		outcome = "missing_runtime_id"
		writeError(w, http.StatusBadRequest, "runtime_id is required")
		return
	}
	runtimeID = req.RuntimeID

	// Inlined and instrumented version of requireDaemonRuntimeAccess so we
	// can attribute the runtime-lookup and workspace-check sub-stages
	// independently in slow-logs. Together with the auth_path label set by
	// DaemonAuth middleware, this lets us tell whether prod heartbeat tail
	// latency is in pgx pool acquisition (runtime_lookup_ms), in the PAT
	// fallback workspace-membership query (workspace_check_ms), or upstream.
	runtimeUUID, ok := parseUUIDOrBadRequest(w, req.RuntimeID, "runtime_id")
	if !ok {
		outcome = "bad_runtime_id"
		return
	}
	lookupStart := time.Now()
	rt, lookupErr := h.getAgentRuntime(r.Context(), obsmetrics.RuntimeLookupSourceHeartbeatHTTP, runtimeUUID)
	runtimeLookupMs = time.Since(lookupStart).Milliseconds()
	if lookupErr != nil {
		// Only pgx.ErrNoRows means the runtime row is gone. Daemon reads this
		// 404 as a signal to drop the stale runtime locally; treating a
		// transient DB error the same way would force daemons to self-cleanup
		// on a hiccup.
		if isNotFound(lookupErr) {
			outcome = "runtime_not_found"
			writeError(w, http.StatusNotFound, "runtime not found")
			return
		}
		outcome = "runtime_lookup_error"
		slog.Warn("get agent runtime failed", "runtime_id", req.RuntimeID, "error", lookupErr)
		writeError(w, http.StatusInternalServerError, "failed to load runtime")
		return
	}
	wsCheckStart := time.Now()
	wsOK := h.requireDaemonRuntimeAuthorized(w, r, uuidToString(rt.WorkspaceID), rt.DaemonID, rt.OwnerID, "runtime not found")
	workspaceCheckMs = time.Since(wsCheckStart).Milliseconds()
	if !wsOK {
		outcome = "workspace_denied"
		return
	}
	authMs = time.Since(start).Milliseconds()

	updateStart := time.Now()
	if err := h.recordHeartbeat(r.Context(), rt); err != nil {
		updateMs = time.Since(updateStart).Milliseconds()
		outcome = "error_update"
		writeError(w, http.StatusInternalServerError, "heartbeat failed")
		return
	}
	updateMs = time.Since(updateStart).Milliseconds()

	ack, m, err := h.processHeartbeat(r.Context(), runtimeID, req.SupportsBatchImport)
	probeModelMs = m.ProbeModelMs
	popModelMs = m.PopModelMs
	probeSkillsMs = m.ProbeSkillsMs
	popSkillsMs = m.PopSkillsMs
	probeImportMs = m.ProbeImportMs
	popImportMs = m.PopImportMs
	probeModelTimedOut = m.ProbeModelTimedOut
	probeSkillsTimedOut = m.ProbeSkillsTimedOut
	probeImportTimedOut = m.ProbeImportTimedOut
	if err != nil {
		outcome = "error_update"
		writeError(w, http.StatusInternalServerError, "heartbeat failed")
		return
	}

	outcome = "ok"
	// Preserve the existing HTTP response shape: the runtime_id field is new
	// in the WS path and would be redundant noise on the HTTP path where the
	// caller already knows which runtime it asked about.
	resp := map[string]any{"status": ack.Status}
	if ack.PendingUpdate != nil {
		resp["pending_update"] = ack.PendingUpdate
	}
	if ack.PendingModelList != nil {
		resp["pending_model_list"] = ack.PendingModelList
	}
	if ack.PendingLocalSkills != nil {
		resp["pending_local_skills"] = ack.PendingLocalSkills
	}
	if ack.PendingLocalSkillImport != nil {
		resp["pending_local_skill_import"] = ack.PendingLocalSkillImport
	}
	if len(ack.PendingLocalSkillImports) > 0 {
		resp["pending_local_skill_imports"] = ack.PendingLocalSkillImports
	}
	writeJSON(w, http.StatusOK, resp)
}

func (h *Handler) DaemonWebSocket(w http.ResponseWriter, r *http.Request) {
	if h.DaemonHub == nil {
		writeErrorCode(w, http.StatusInternalServerError, "daemon_websocket_misconfigured", "daemon websocket unavailable")
		return
	}

	runtimeIDs := parseRuntimeIDs(r)
	userID := requestUserID(r)
	if len(runtimeIDs) == 0 && userID == "" {
		writeError(w, http.StatusBadRequest, "runtime_ids or user identity required")
		return
	}

	identity, ok := h.buildDaemonWebSocketIdentity(w, r, runtimeIDs, userID)
	if !ok {
		return
	}
	h.DaemonHub.HandleWebSocket(w, r, identity)
}

func (h *Handler) ListDaemonWorkspaces(w http.ResponseWriter, r *http.Request) {
	var resp []DaemonWorkspaceResponse
	if userID := requestUserID(r); userID != "" {
		rows, err := dbreader.Read(
			r.Context(),
			h.ReadSelector,
			dbreader.BusinessDaemonWorkspaces,
			dbreader.EventualConsistency,
			func(ctx context.Context, q *db.Queries) ([]db.ListDaemonWorkspacesRow, error) {
				return q.ListDaemonWorkspaces(ctx, parseUUID(userID))
			},
		)
		if err != nil {
			writeError(w, http.StatusInternalServerError, "failed to list daemon workspaces")
			return
		}
		resp = make([]DaemonWorkspaceResponse, len(rows))
		for i, row := range rows {
			resp[i] = daemonWorkspaceToResponse(row.ID, row.Name)
		}
	} else {
		workspaceID := middleware.DaemonWorkspaceIDFromContext(r.Context())
		if workspaceID == "" {
			writeError(w, http.StatusUnauthorized, "daemon workspace identity required")
			return
		}
		row, err := dbreader.Read(
			r.Context(),
			h.ReadSelector,
			dbreader.BusinessDaemonWorkspaces,
			dbreader.EventualConsistency,
			func(ctx context.Context, q *db.Queries) (db.GetDaemonWorkspaceRow, error) {
				return q.GetDaemonWorkspace(ctx, parseUUID(workspaceID))
			},
		)
		if err != nil {
			writeError(w, http.StatusNotFound, "workspace not found")
			return
		}
		resp = []DaemonWorkspaceResponse{daemonWorkspaceToResponse(row.ID, row.Name)}
	}

	etag := daemonWorkspacesETag(resp)
	w.Header().Set("Cache-Control", "private, no-cache")
	w.Header().Set("ETag", etag)
	if r.Header.Get("If-None-Match") == etag {
		w.WriteHeader(http.StatusNotModified)
		return
	}
	writeJSON(w, http.StatusOK, resp)
}

func (h *Handler) GetDaemonWorkspaceRepos(w http.ResponseWriter, r *http.Request) {
	workspaceID := strings.TrimSpace(chi.URLParam(r, "workspaceId"))
	if !h.requireDaemonWorkspaceAccess(w, r, workspaceID) {
		return
	}

	ws, err := h.Queries.GetWorkspace(r.Context(), parseUUID(workspaceID))
	if err != nil {
		writeError(w, http.StatusNotFound, "workspace not found")
		return
	}

	writeJSON(w, http.StatusOK, workspaceReposResponse(workspaceID, ws.Repos, ws.Settings, h.cfg.GitExtraCACerts))
}

func (h *Handler) DaemonListRuntimeProfiles(w http.ResponseWriter, r *http.Request) {
	workspaceID := strings.TrimSpace(chi.URLParam(r, "workspaceId"))
	if !h.requireDaemonWorkspaceAccess(w, r, workspaceID) {
		return
	}
	wsUUID, ok := parseUUIDOrBadRequest(w, workspaceID, "workspace id")
	if !ok {
		return
	}

	daemonID := strings.TrimSpace(r.URL.Query().Get("daemon_id"))
	if tokenDaemonID := middleware.DaemonIDFromContext(r.Context()); tokenDaemonID != "" {
		if daemonID != "" && daemonID != tokenDaemonID {
			writeError(w, http.StatusForbidden, "daemon identity mismatch")
			return
		}
		daemonID = tokenDaemonID
	}

	if daemonID != "" {
		owners, err := h.Queries.ListRuntimeOwnersByDaemon(r.Context(), db.ListRuntimeOwnersByDaemonParams{
			WorkspaceID: wsUUID,
			DaemonID:    strToText(daemonID),
		})
		if err != nil {
			writeError(w, http.StatusInternalServerError, "failed to resolve runtime profile machine")
			return
		}
		for _, owner := range owners {
			if !daemonRuntimeBindingAllowed(r, strToText(daemonID), owner.OwnerID) {
				writeError(w, http.StatusNotFound, "machine not found")
				return
			}
		}
	}
	var profiles []db.RuntimeProfile
	var err error
	if daemonID == "" && requestUserID(r) != "" {
		userID, ok := parseUUIDOrBadRequest(w, requestUserID(r), "user id")
		if !ok {
			return
		}
		profiles, err = h.Queries.ListEnabledRuntimeProfilesForOwner(r.Context(), db.ListEnabledRuntimeProfilesForOwnerParams{WorkspaceID: wsUUID, OwnerID: userID})
	} else {
		profiles, err = h.Queries.ListEnabledRuntimeProfilesForDaemon(r.Context(), db.ListEnabledRuntimeProfilesForDaemonParams{WorkspaceID: wsUUID, DaemonID: strToText(daemonID)})
	}
	if err != nil {
		writeError(w, http.StatusInternalServerError, "failed to list runtime profiles")
		return
	}
	resp := make([]RuntimeProfileResponse, len(profiles))
	for i, p := range profiles {
		resp[i] = runtimeProfileToResponse(p)
	}
	writeJSON(w, http.StatusOK, map[string]any{
		"workspace_id":     workspaceID,
		"runtime_profiles": resp,
	})
}

func (h *Handler) InvokeAgentPluginHook(w http.ResponseWriter, r *http.Request) {
	if !h.requirePluginsV1(w, r) {
		return
	}
	task, workspaceID, ok := h.requireDaemonTaskAccessWithWorkspace(w, r, chi.URLParam(r, "id"))
	if !ok {
		return
	}

	var req invokeAgentHookRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid request body")
		return
	}
	if req.InstallationID == "" || req.HookKey == "" {
		writeError(w, http.StatusBadRequest, "installation_id and hook_key are required")
		return
	}

	// The installation must belong to the task's workspace. Without this a
	// daemon holding one valid task could name any installation id in the
	// deployment and have the server call it.
	installation, err := h.PluginService.InstallationForWorkspace(r.Context(), parseUUID(workspaceID), req.InstallationID)
	if err != nil {
		writePluginError(w, err, "failed to load the Plugin")
		return
	}

	result, err := h.PluginService.InvokeAgentHook(
		r.Context(), uuidToString(installation.ID), req.HookKey, task.AgentID, req.Input)
	if err != nil {
		// 200 with an error body, deliberately.
		//
		// The daemon turns this into a tool ERROR, and a tool error is
		// something the agent reads and works around. A transport-level failure
		// would instead look to the daemon like the broker itself is broken,
		// which is how one unreachable plugin endpoint ends up failing the
		// whole task — the outcome acceptance criterion 3 forbids.
		writeJSON(w, http.StatusOK, map[string]any{
			"status": result.Status,
			"error":  result.Error,
		})
		return
	}
	writeJSON(w, http.StatusOK, result)
}

func (c *Client) InvokeAgentPluginHook(ctx context.Context, daemonToken, taskID, installationID, hookKey string, input json.RawMessage) (json.RawMessage, error) {
	var response struct {
		Status string          `json:"status"`
		Output json.RawMessage `json:"output,omitempty"`
		Error  string          `json:"error,omitempty"`
	}
	path := fmt.Sprintf("/api/daemon/tasks/%s/plugin-hooks", url.PathEscape(taskID))
	body := map[string]any{"installation_id": installationID, "hook_key": hookKey}
	if len(input) > 0 {
		body["input"] = input
	}
	if err := c.postJSONWithToken(ctx, path, daemonToken, body, &response); err != nil {
		return nil, err
	}
	// A refused or failed hook comes back as a 200 with a status, so that the
	// caller can render it as a TOOL error rather than a broken transport —
	// an unreachable plugin endpoint must not fail the agent's task.
	if response.Status != "ok" {
		if response.Error != "" {
			return nil, errors.New(response.Error)
		}
		return nil, errors.New("the plugin hook did not succeed")
	}
	return response.Output, nil
}

func (h *Handler) ResolvePluginMCPCredential(w http.ResponseWriter, r *http.Request) {
	if !h.requirePluginsV1(w, r) {
		return
	}
	_, workspaceID, ok := h.requireDaemonTaskAccessWithWorkspace(w, r, chi.URLParam(r, "id"))
	if !ok {
		return
	}

	installationID, hookKey, ok := splitPluginContributionID(chi.URLParam(r, "contributionId"))
	if !ok {
		writeError(w, http.StatusBadRequest, "malformed contribution id")
		return
	}
	installation, err := h.PluginService.InstallationForWorkspace(r.Context(), parseUUID(workspaceID), installationID)
	if err != nil {
		writePluginError(w, err, "failed to load the Plugin")
		return
	}

	header, credential, err := h.PluginService.MCPHookCredential(r.Context(), installation, hookKey)
	if err != nil {
		writePluginError(w, err, "failed to resolve the credential")
		return
	}
	writeJSON(w, http.StatusOK, map[string]any{
		"credential_header": header,
		"credential":        credential,
	})
}

func (h *Handler) ClaimTaskByRuntime(w http.ResponseWriter, r *http.Request) {
	runtimeID := chi.URLParam(r, "runtimeId")
	start := time.Now()

	var (
		outcome                  = "unauth"
		authMs, claimMs, buildMs int64
		payloadBytes             int
		agentSkillCount          int
		builtinSkillCount        int
		skillPayloadBytes        int
		buildStart               time.Time
	)
	defer func() {
		// Emit at function exit so error / unauth paths also carry timing.
		// build_ms is computed from buildStart only when we entered the
		// response-build phase (otherwise stays 0).
		if !buildStart.IsZero() {
			buildMs = time.Since(buildStart).Milliseconds()
		}
		logClaimEndpointSlow(runtimeID, outcome, start, authMs, claimMs, buildMs, payloadBytes, agentSkillCount, builtinSkillCount, skillPayloadBytes)
	}()

	// Verify the caller owns this runtime's workspace. The runtime's
	// workspace_id is the authoritative value a claimed task must match
	// below — a task whose resolved workspace doesn't equal this runtime's
	// workspace is rejected even if it was enqueued against this
	// runtime_id (defense-in-depth against upstream routing bugs).
	runtime, ok := h.requireDaemonRuntimeAccess(w, r, runtimeID)
	if !ok {
		return
	}
	runtimeWorkspaceID := uuidToString(runtime.WorkspaceID)
	authMs = time.Since(start).Milliseconds()

	claimStart := time.Now()
	task, err := h.TaskService.ClaimTaskForRuntime(r.Context(), parseUUID(runtimeID))
	claimMs = time.Since(claimStart).Milliseconds()
	if err != nil {
		outcome = "error_claim"
		slog.Warn("claim task failed", append(logger.RequestAttrs(r), "error", err)...)
		writeError(w, http.StatusInternalServerError, "failed to claim task")
		return
	}

	if task == nil {
		slog.Debug("no task to claim", "runtime_id", runtimeID)
		payloadBytes, _ = writeMeasuredJSON(w, http.StatusOK, map[string]any{"task": nil})
		outcome = "no_task"
		return
	}
	if len(task.CoalescedCommentIds) > 0 {
		handled, failure := h.repairStaleCommentPlanIfNeeded(r.Context(), task, runtimeWorkspaceID)
		if handled {
			if failure != nil {
				outcome = failure.outcome
				writeError(w, failure.status, failure.message)
				return
			}
			outcome = "repaired_stale_comment_plan"
			payloadBytes, _ = writeMeasuredJSON(w, http.StatusOK, map[string]any{"task": nil})
			return
		}
	}

	outcome = "claimed"
	buildStart = time.Now()

	resp, deliveredCommentIDs, issueSnapshot, agentSkillCount, builtinSkillCount, failure := h.buildClaimedTaskResponse(r, task, runtime, runtimeID, runtimeWorkspaceID)
	if failure != nil {
		outcome = failure.outcome
		if failure.settled {
			payloadBytes, _ = writeMeasuredJSON(w, http.StatusOK, map[string]any{"task": nil})
			return
		}
		writeError(w, failure.status, failure.message)
		return
	}
	commentBackedTask := task.TriggerCommentID.Valid || len(task.CoalescedCommentIds) > 0
	requeueFailedClaim := func(reason string) {
		if _, err := h.TaskService.RequeueTaskAfterClaimFailure(r.Context(), *task); err != nil {
			slog.Error("task claim: failed to requeue after finalization error",
				"task_id", uuidToString(task.ID),
				"reason", reason,
				"error", err,
			)
		}
	}
	// Mint a task-scoped `mat_` token bound to (agent, task, workspace,
	// owner). The daemon will inject this as WORKPAL_TOKEN into the agent
	// process instead of its own credential, so any API call the agent
	// makes — even one that strips X-Agent-ID / X-Task-ID headers — is
	// recognized server-side as actor=agent, closing the lateral-movement
	// path on human-only endpoints (e.g. `/api/agents/{id}/env`). Runtime
	// owner is required because task tokens are still bound to an owning user;
	// without one, fail the claim explicitly instead of letting the daemon
	// fall back to a member/owner credential. MUL-3292.
	// Token expires after the queue/runtime upper bound (24h) so it survives
	// long-running tasks but cannot outlive a forgotten one.
	if !runtime.OwnerID.Valid {
		outcome = "error_token"
		slog.Error("task claim: runtime owner missing; cancelling task to avoid unscoped agent credentials",
			"task_id", uuidToString(task.ID),
			"runtime_id", runtimeID,
			"workspace_id", runtimeWorkspaceID,
		)
		if _, cerr := h.TaskService.CancelTask(r.Context(), task.ID); cerr != nil {
			slog.Error("task claim: cancel after missing runtime owner failed",
				"task_id", uuidToString(task.ID), "error", cerr)
		}
		writeError(w, http.StatusInternalServerError, "runtime owner required to mint task token")
		return
	}
	tokenStr, terr := auth.GenerateAgentTaskToken()
	if terr != nil {
		outcome = "error_token"
		slog.Error("task claim: failed to generate agent task token",
			"task_id", uuidToString(task.ID), "error", terr)
		requeueFailedClaim("token_generation")
		writeError(w, http.StatusInternalServerError, "failed to mint task token")
		return
	}
	remoteMCPToken, daemonTokens, derr := remoteMCPDaemonTokenForClaim(resp, runtime)
	if derr != nil {
		outcome = "error_remote_mcp_token"
		slog.Error("task claim: failed to generate Remote MCP daemon token",
			"task_id", uuidToString(task.ID), "error", derr)
		requeueFailedClaim("remote_mcp_token_generation")
		writeError(w, http.StatusInternalServerError, "failed to mint Remote MCP daemon token")
		return
	}
	receipt, deliveryFailure, ferr := h.finalizeClaimDelivery(r.Context(), task, runtime, runtimeID, runtimeWorkspaceID, &resp, db.CreateTaskTokenParams{
		ID:          dbid.NewV7(),
		TokenHash:   auth.HashToken(tokenStr),
		TaskID:      task.ID,
		AgentID:     task.AgentID,
		WorkspaceID: parseUUID(resp.WorkspaceID),
		UserID:      runtime.OwnerID,
		ExpiresAt:   pgtype.Timestamptz{Time: time.Now().Add(24 * time.Hour), Valid: true},
	}, deliveredCommentIDs, commentBackedTask, issueSnapshot, daemonTokens...)
	if ferr != nil {
		outcome = "error_claim_finalize"
		slog.Error("task claim: failed to finalize token and comment delivery receipt",
			"task_id", uuidToString(task.ID), "error", ferr)
		// FinalizeTaskClaim is transactional, so its newly generated token is
		// rolled back with the receipt. Never delete by task here: a stale
		// reclaim can race the original daemon starting, and broad revocation
		// would invalidate that already-authorized execution.
		requeueFailedClaim("token_and_delivery_receipt")
		writeError(w, http.StatusInternalServerError, "failed to finalize task claim")
		return
	}
	if deliveryFailure != nil {
		if !deliveryFailure.settled {
			outcome = deliveryFailure.outcome
			writeError(w, deliveryFailure.status, deliveryFailure.message)
			return
		}
		// The final delivery gate rejected the task (agent rebound, or the
		// runtime's current ownership no longer permits this agent). The task
		// is already terminal via the FailTask path — return the same empty
		// successful poll the queued-mismatch settle path returns.
		outcome = deliveryFailure.outcome
		payloadBytes, _ = writeMeasuredJSON(w, http.StatusOK, map[string]any{"task": nil})
		return
	}
	resp.AuthToken = tokenStr
	resp.RemoteMCPDaemonToken = remoteMCPToken
	task.DeliveredCommentIds = receipt
	resp.DeliveredCommentIDs = uuidStringsOrEmpty(receipt)

	slog.Info("task claimed by runtime", "task_id", uuidToString(task.ID), "runtime_id", runtimeID, "agent_id", uuidToString(task.AgentID), "prior_session", resp.PriorSessionID)
	if resp.Agent != nil && len(resp.Agent.Skills) > 0 {
		if skillPayload, err := json.Marshal(resp.Agent.Skills); err == nil {
			skillPayloadBytes = len(skillPayload)
		}
	} else if resp.Agent != nil && len(resp.Agent.SkillRefs) > 0 {
		if skillPayload, err := json.Marshal(resp.Agent.SkillRefs); err == nil {
			skillPayloadBytes = len(skillPayload)
		}
	}
	payloadBytes, _ = writeMeasuredJSON(w, http.StatusOK, map[string]any{"task": resp})
}

func (h *Handler) ClaimTasksByRuntime(w http.ResponseWriter, r *http.Request) {
	start := time.Now()
	buildDeadline, responseDeadline := batchClaimDeadlines(r.Context(), start)
	buildCtx, cancelBuild := context.WithDeadline(r.Context(), buildDeadline)
	defer cancelBuild()
	r = r.WithContext(buildCtx)
	var req struct {
		DaemonID   string   `json:"daemon_id"`
		RuntimeIDs []string `json:"runtime_ids"`
		MaxTasks   int      `json:"max_tasks"`
		// ForceRecheckRuntimeIDs is an optional, additive signal (#7452): the
		// daemon lists the runtimes woken by a targeted `task_available` since its
		// last claim so the server bypasses their cached "empty" verdict and runs
		// the real candidate SELECT, repairing a stale verdict left by a lost
		// EmptyClaim.Bump. Absent/unknown on an older daemon → behaves exactly as
		// before (TTL fallback). Parsed defensively; ids not in the authorized set
		// are dropped.
		ForceRecheckRuntimeIDs []string `json:"force_recheck_runtime_ids"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid request body")
		return
	}

	// Machine-level ownership (MUL-4257 review): the batch claim is scoped to a
	// single daemon. daemon_id is required so the server can reject any
	// runtime_id that belongs to a different machine (guards against a stale /
	// crossed runtime set claiming another daemon's tasks — which would land
	// local_directory / machine-local work on the wrong host). For an mdt_
	// token the body daemon_id must equal the token's daemon_id, so a
	// workspace-scoped token can't spoof a peer.
	if req.DaemonID == "" {
		writeError(w, http.StatusBadRequest, "daemon_id is required")
		return
	}
	if ctxDaemonID := middleware.DaemonIDFromContext(r.Context()); ctxDaemonID != "" && ctxDaemonID != req.DaemonID {
		writeError(w, http.StatusForbidden, "daemon_id does not match token")
		return
	}

	// An explicit force list also opts in for clients that predate the header.
	wantAck := len(req.ForceRecheckRuntimeIDs) > 0 || requestHasClientCapability(r, protocol.DaemonCapabilityForceRecheckV1)
	respondEmpty := func() {
		response := map[string]any{"tasks": []AgentTaskResponse{}}
		if wantAck {
			response["force_rechecked_runtime_ids"] = []string{}
		}
		writeMeasuredJSON(w, http.StatusOK, response)
	}

	// max_tasks semantics (MUL-4257 review): a negative count is malformed; zero
	// is a valid "no free slots" poll that must claim nothing — never coerce to
	// 1, which would dispatch a task the daemon cannot run and strand it until
	// stale reclaim. Positive counts are capped so one request can't build an
	// unbounded payload.
	if req.MaxTasks < 0 {
		writeError(w, http.StatusBadRequest, "max_tasks must not be negative")
		return
	}
	if req.MaxTasks == 0 {
		respondEmpty()
		return
	}
	maxTasks := req.MaxTasks
	if maxTasks > claimBatchMaxTasksCap {
		maxTasks = claimBatchMaxTasksCap
	}

	// Parse + de-dup requested ids with the NON-panicking parser (MUL-4257
	// review): the handler-local parseUUID panics on malformed input, which
	// would turn a single bad id into a 500. Invalid ids are skipped, matching
	// this endpoint's "unknown id skipped" semantics. Key by the canonical uuid
	// string so the post-claim lookup by task.RuntimeID always matches.
	idByKey := make(map[string]pgtype.UUID, len(req.RuntimeIDs))
	for _, rid := range req.RuntimeIDs {
		ruid, err := util.ParseUUID(rid)
		if err != nil {
			continue
		}
		idByKey[util.UUIDToString(ruid)] = ruid
	}
	if len(idByKey) == 0 {
		respondEmpty()
		return
	}
	ids := make([]pgtype.UUID, 0, len(idByKey))
	for _, id := range idByKey {
		ids = append(ids, id)
	}

	// Resolve all requested runtimes in one query (instead of a point lookup
	// per runtime), then authorize each; skip (don't fail) unknown/unauthorized
	// ids so a single stale runtime can't sink the whole batch.
	//
	// This read goes through RuntimeLookup like every other agent_runtime read
	// by id (MUL-6884), so the claim path is attributed on
	// workpal_agent_runtime_lookup_total instead of being invisible on it. That
	// matters more here than on any other caller: both /tasks/claim and /claim
	// route to this handler and the WebSocket claim RPC replays through it, so
	// an unattributed read here would make the busiest reader in the system
	// look idle next to once-per-shutdown deregisters.
	foundByID, err := h.getAgentRuntimes(r.Context(), obsmetrics.RuntimeLookupSourceDaemonAPI, ids)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "failed to load runtimes")
		return
	}
	// Iterate ids rather than ranging the returned map: authorized[] is passed
	// to ClaimTasksForRuntimes, where maxTasks can cut the set off partway, so
	// map iteration order would decide which runtimes get the remaining slots.
	// (ids is itself built from a map above, so this pins the order to one
	// source rather than making it fully deterministic — worth tightening, but
	// not in this change.)
	//
	// runtimeByID must end up holding ONLY authorized rows: the post-claim loop
	// below treats a miss in it as a stray cross-daemon claim and drops the
	// task. GetMany returns every row it found, so the authorized subset is
	// collected separately rather than reusing its map.
	runtimeByID := make(map[string]db.AgentRuntime, len(foundByID))
	authorized := make([]pgtype.UUID, 0, len(foundByID))
	for _, id := range ids {
		rt, ok := foundByID[uuidToString(id)]
		if !ok {
			continue
		}
		// Workspace access plus runtime ownership / daemon binding
		// (MUL-8154). For user credentials the body daemon_id is
		// caller-chosen, so the daemon_id check below is not an
		// authorization boundary on its own.
		if !h.verifyDaemonRuntimeAuthorized(r, rt) {
			continue
		}
		// Group-ownership check (mirrors the WS path, daemon_ws.go): a runtime
		// bound to a different daemon must not be claimed by this one. Runtimes
		// with a NULL daemon_id (e.g. cloud runtimes) are not machine-pinned, so
		// they stay claimable — same tolerance as the WS handler.
		if rt.DaemonID.Valid && rt.DaemonID.String != req.DaemonID {
			continue
		}
		runtimeByID[uuidToString(rt.ID)] = rt
		authorized = append(authorized, rt.ID)
	}
	if len(authorized) == 0 {
		respondEmpty()
		return
	}

	// Restrict the force-recheck set (#7452) to runtimes this daemon is
	// authorized for: an unknown or malformed id is skipped (matching this
	// endpoint's "unknown id skipped" semantics), and an id for another daemon's
	// runtime cannot force a cross-machine cache bypass.
	forceRecheck := make([]pgtype.UUID, 0, len(req.ForceRecheckRuntimeIDs))
	for _, rid := range req.ForceRecheckRuntimeIDs {
		ruid, err := util.ParseUUID(rid)
		if err != nil {
			continue
		}
		if _, ok := runtimeByID[util.UUIDToString(ruid)]; !ok {
			continue
		}
		forceRecheck = append(forceRecheck, ruid)
	}

	claimed, forceRechecked, err := h.TaskService.ClaimTasksForRuntimes(r.Context(), authorized, maxTasks, forceRecheck...)
	if err != nil {
		slog.Warn("claim tasks failed", append(logger.RequestAttrs(r), "error", err)...)
		writeError(w, http.StatusInternalServerError, "failed to claim tasks")
		return
	}

	out := make([]AgentTaskResponse, 0, len(claimed))
	for i := range claimed {
		if r.Context().Err() != nil {
			break
		}
		task := claimed[i]
		rt, ok := runtimeByID[uuidToString(task.RuntimeID)]
		if !ok {
			// Service guards claims to the authorized set; a miss here would be
			// a stray cross-daemon claim. Leave it for the owning daemon's
			// reclaim path rather than shipping it to the wrong machine.
			continue
		}
		rtWorkspaceID := uuidToString(rt.WorkspaceID)
		// Stale comment-plan repair must run for the batch path too: otherwise a
		// task whose trigger was deleted (only coalesced survive) would be
		// finalized+dispatched with no comment input, silently dropping the
		// surviving user comment. On repair (or hard failure) the task is
		// cancelled / left for reclaim and omitted from the batch.
		if handled, _ := h.repairStaleCommentPlanIfNeeded(r.Context(), &task, rtWorkspaceID); handled {
			continue
		}
		resp, deliveredCommentIDs, issueSnapshot, _, _, failure := h.buildClaimedTaskResponse(r, &task, rt, uuidToString(task.RuntimeID), rtWorkspaceID)
		if failure != nil {
			// Builder rejected this task (workspace isolation / chat-input);
			// it has already settled the task where the failure requires it.
			// Undelivered claims are recovered below with a separate budget.
			continue
		}
		if !rt.OwnerID.Valid {
			slog.Error("batch claim: runtime owner missing; cancelling task to avoid unscoped agent credentials",
				"task_id", uuidToString(task.ID), "runtime_id", uuidToString(task.RuntimeID))
			if _, cerr := h.TaskService.CancelTask(r.Context(), task.ID); cerr != nil {
				slog.Error("batch claim: cancel after missing runtime owner failed",
					"task_id", uuidToString(task.ID), "error", cerr)
			}
			continue
		}
		tokenStr, terr := auth.GenerateAgentTaskToken()
		if terr != nil {
			slog.Error("batch claim: generate task token failed; requeueing claim",
				"task_id", uuidToString(task.ID), "error", terr)
			continue
		}
		remoteMCPToken, daemonTokens, derr := remoteMCPDaemonTokenForClaim(resp, rt)
		if derr != nil {
			slog.Error("batch claim: generate Remote MCP daemon token failed; requeueing claim",
				"task_id", uuidToString(task.ID), "error", derr)
			continue
		}
		// Route through the SAME finalization as the per-runtime endpoint so the
		// token and the comment-delivery receipt (delivered_comment_ids for
		// comment/coalesced-comment tasks) are persisted atomically; on failure
		// the exact claim is requeued and omitted from this batch. The shared
		// final delivery gate re-verifies current runtime ownership inside the
		// same transaction; a rejected task is settled via FailTask and skipped
		// while valid tasks in the same batch continue.
		commentBackedTask := task.TriggerCommentID.Valid || len(task.CoalescedCommentIds) > 0
		receipt, deliveryFailure, ferr := h.finalizeClaimDelivery(r.Context(), &task, rt, uuidToString(task.RuntimeID), rtWorkspaceID, &resp, db.CreateTaskTokenParams{
			ID:          dbid.NewV7(),
			TokenHash:   auth.HashToken(tokenStr),
			TaskID:      task.ID,
			AgentID:     task.AgentID,
			WorkspaceID: parseUUID(resp.WorkspaceID),
			UserID:      rt.OwnerID,
			ExpiresAt:   pgtype.Timestamptz{Time: time.Now().Add(24 * time.Hour), Valid: true},
		}, deliveredCommentIDs, commentBackedTask, issueSnapshot, daemonTokens...)
		if ferr != nil {
			slog.Error("batch claim: finalize task claim failed; requeueing claim",
				"task_id", uuidToString(task.ID), "error", ferr)
			continue
		}
		if deliveryFailure != nil {
			if !deliveryFailure.settled {
				slog.Error("batch claim: delivery rejection settlement failed",
					"task_id", uuidToString(task.ID), "outcome", deliveryFailure.outcome,
					"error", deliveryFailure.message)
			}
			continue
		}
		resp.AuthToken = tokenStr
		resp.RemoteMCPDaemonToken = remoteMCPToken
		resp.DeliveredCommentIDs = uuidStringsOrEmpty(receipt)
		out = append(out, resp)
	}

	if len(out) > 0 {
		slog.Info("tasks claimed by runtime batch",
			"runtimes", len(authorized), "requested_max", maxTasks, "claimed", len(out),
			"total_ms", time.Since(start).Milliseconds())
	}
	response := map[string]any{"tasks": out}
	if wantAck {
		// An explicit empty list keeps outstanding hints pending. Absence
		// tells the client to fall back to legacy polling.
		if forceRechecked == nil {
			forceRechecked = []string{}
		}
		response["force_rechecked_runtime_ids"] = forceRechecked
	}
	// Only opted-in daemons understand this additive response metadata. Query
	// after the claim so a future fire_at can shorten the long healthy-WS safety
	// poll; a task that crossed fire_at during this request yields a bounded
	// follow-up hint and is promoted on the next claim. If the lookup fails,
	// omit the support bit so the daemon conservatively retains its ordinary
	// PollInterval. Omitted claims also retain that short poll in case recovery
	// failed or the task_available wakeup raced with this response.
	if len(out) == len(claimed) && len(out) < maxTasks && requestHasClientCapability(r, protocol.DaemonCapabilityClaimPollHintsV1) {
		nextDeferred, nextErr := h.Queries.NextDeferredTaskFireAtForRuntimes(r.Context(), db.NextDeferredTaskFireAtForRuntimesParams{
			RuntimeIds:       authorized,
			RuntimeStaleSecs: service.RuntimeClaimFreshnessSeconds,
		})
		if nextErr != nil {
			slog.Warn("batch claim: next deferred task lookup failed; retaining short client poll",
				"error", nextErr)
		} else {
			response["claim_poll_hint_supported"] = true
			if nextDeferred.Valid {
				response["next_deferred_task_after_ms"] = claimPollHintDelay(time.Now(), nextDeferred.Time).Milliseconds()
			}
		}
	}
	if len(out) != len(claimed) {
		// HTTP/1.1 cannot process another request until this handler returns.
		// Keep the next claim off this connection while recovery is running.
		w.Header().Set("Connection", "close")
	}
	writeMeasuredJSON(w, http.StatusOK, response)
	if len(out) != len(claimed) {
		// Deliver successful payloads before batch recovery side effects. Cache
		// invalidation, event listeners and cross-node wakeups can use their own
		// timeouts, so the recovery context alone cannot bound the response wait.
		// HTTP already advertises Content-Length; flushing sends the whole body.
		// WS keeps cleanup in the existing RPC worker after queuing its response.
		cleanup := func() {
			h.requeueUndeliveredBatchClaims(r.Context(), claimed, out, responseDeadline)
		}
		if !daemonws.AfterRPCResponse(r.Context(), cleanup) {
			_ = http.NewResponseController(w).Flush()
			cleanup()
		}
	}
}

func (h *Handler) ClaimTasksByRuntime(w http.ResponseWriter, r *http.Request) {
	start := time.Now()
	buildDeadline, responseDeadline := batchClaimDeadlines(r.Context(), start)
	buildCtx, cancelBuild := context.WithDeadline(r.Context(), buildDeadline)
	defer cancelBuild()
	r = r.WithContext(buildCtx)
	var req struct {
		DaemonID   string   `json:"daemon_id"`
		RuntimeIDs []string `json:"runtime_ids"`
		MaxTasks   int      `json:"max_tasks"`
		// ForceRecheckRuntimeIDs is an optional, additive signal (#7452): the
		// daemon lists the runtimes woken by a targeted `task_available` since its
		// last claim so the server bypasses their cached "empty" verdict and runs
		// the real candidate SELECT, repairing a stale verdict left by a lost
		// EmptyClaim.Bump. Absent/unknown on an older daemon → behaves exactly as
		// before (TTL fallback). Parsed defensively; ids not in the authorized set
		// are dropped.
		ForceRecheckRuntimeIDs []string `json:"force_recheck_runtime_ids"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid request body")
		return
	}

	// Machine-level ownership (MUL-4257 review): the batch claim is scoped to a
	// single daemon. daemon_id is required so the server can reject any
	// runtime_id that belongs to a different machine (guards against a stale /
	// crossed runtime set claiming another daemon's tasks — which would land
	// local_directory / machine-local work on the wrong host). For an mdt_
	// token the body daemon_id must equal the token's daemon_id, so a
	// workspace-scoped token can't spoof a peer.
	if req.DaemonID == "" {
		writeError(w, http.StatusBadRequest, "daemon_id is required")
		return
	}
	if ctxDaemonID := middleware.DaemonIDFromContext(r.Context()); ctxDaemonID != "" && ctxDaemonID != req.DaemonID {
		writeError(w, http.StatusForbidden, "daemon_id does not match token")
		return
	}

	// An explicit force list also opts in for clients that predate the header.
	wantAck := len(req.ForceRecheckRuntimeIDs) > 0 || requestHasClientCapability(r, protocol.DaemonCapabilityForceRecheckV1)
	respondEmpty := func() {
		response := map[string]any{"tasks": []AgentTaskResponse{}}
		if wantAck {
			response["force_rechecked_runtime_ids"] = []string{}
		}
		writeMeasuredJSON(w, http.StatusOK, response)
	}

	// max_tasks semantics (MUL-4257 review): a negative count is malformed; zero
	// is a valid "no free slots" poll that must claim nothing — never coerce to
	// 1, which would dispatch a task the daemon cannot run and strand it until
	// stale reclaim. Positive counts are capped so one request can't build an
	// unbounded payload.
	if req.MaxTasks < 0 {
		writeError(w, http.StatusBadRequest, "max_tasks must not be negative")
		return
	}
	if req.MaxTasks == 0 {
		respondEmpty()
		return
	}
	maxTasks := req.MaxTasks
	if maxTasks > claimBatchMaxTasksCap {
		maxTasks = claimBatchMaxTasksCap
	}

	// Parse + de-dup requested ids with the NON-panicking parser (MUL-4257
	// review): the handler-local parseUUID panics on malformed input, which
	// would turn a single bad id into a 500. Invalid ids are skipped, matching
	// this endpoint's "unknown id skipped" semantics. Key by the canonical uuid
	// string so the post-claim lookup by task.RuntimeID always matches.
	idByKey := make(map[string]pgtype.UUID, len(req.RuntimeIDs))
	for _, rid := range req.RuntimeIDs {
		ruid, err := util.ParseUUID(rid)
		if err != nil {
			continue
		}
		idByKey[util.UUIDToString(ruid)] = ruid
	}
	if len(idByKey) == 0 {
		respondEmpty()
		return
	}
	ids := make([]pgtype.UUID, 0, len(idByKey))
	for _, id := range idByKey {
		ids = append(ids, id)
	}

	// Resolve all requested runtimes in one query (instead of a point lookup
	// per runtime), then authorize each; skip (don't fail) unknown/unauthorized
	// ids so a single stale runtime can't sink the whole batch.
	//
	// This read goes through RuntimeLookup like every other agent_runtime read
	// by id (MUL-6884), so the claim path is attributed on
	// workpal_agent_runtime_lookup_total instead of being invisible on it. That
	// matters more here than on any other caller: both /tasks/claim and /claim
	// route to this handler and the WebSocket claim RPC replays through it, so
	// an unattributed read here would make the busiest reader in the system
	// look idle next to once-per-shutdown deregisters.
	foundByID, err := h.getAgentRuntimes(r.Context(), obsmetrics.RuntimeLookupSourceDaemonAPI, ids)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "failed to load runtimes")
		return
	}
	// Iterate ids rather than ranging the returned map: authorized[] is passed
	// to ClaimTasksForRuntimes, where maxTasks can cut the set off partway, so
	// map iteration order would decide which runtimes get the remaining slots.
	// (ids is itself built from a map above, so this pins the order to one
	// source rather than making it fully deterministic — worth tightening, but
	// not in this change.)
	//
	// runtimeByID must end up holding ONLY authorized rows: the post-claim loop
	// below treats a miss in it as a stray cross-daemon claim and drops the
	// task. GetMany returns every row it found, so the authorized subset is
	// collected separately rather than reusing its map.
	runtimeByID := make(map[string]db.AgentRuntime, len(foundByID))
	authorized := make([]pgtype.UUID, 0, len(foundByID))
	for _, id := range ids {
		rt, ok := foundByID[uuidToString(id)]
		if !ok {
			continue
		}
		// Workspace access plus runtime ownership / daemon binding
		// (MUL-8154). For user credentials the body daemon_id is
		// caller-chosen, so the daemon_id check below is not an
		// authorization boundary on its own.
		if !h.verifyDaemonRuntimeAuthorized(r, rt) {
			continue
		}
		// Group-ownership check (mirrors the WS path, daemon_ws.go): a runtime
		// bound to a different daemon must not be claimed by this one. Runtimes
		// with a NULL daemon_id (e.g. cloud runtimes) are not machine-pinned, so
		// they stay claimable — same tolerance as the WS handler.
		if rt.DaemonID.Valid && rt.DaemonID.String != req.DaemonID {
			continue
		}
		runtimeByID[uuidToString(rt.ID)] = rt
		authorized = append(authorized, rt.ID)
	}
	if len(authorized) == 0 {
		respondEmpty()
		return
	}

	// Restrict the force-recheck set (#7452) to runtimes this daemon is
	// authorized for: an unknown or malformed id is skipped (matching this
	// endpoint's "unknown id skipped" semantics), and an id for another daemon's
	// runtime cannot force a cross-machine cache bypass.
	forceRecheck := make([]pgtype.UUID, 0, len(req.ForceRecheckRuntimeIDs))
	for _, rid := range req.ForceRecheckRuntimeIDs {
		ruid, err := util.ParseUUID(rid)
		if err != nil {
			continue
		}
		if _, ok := runtimeByID[util.UUIDToString(ruid)]; !ok {
			continue
		}
		forceRecheck = append(forceRecheck, ruid)
	}

	claimed, forceRechecked, err := h.TaskService.ClaimTasksForRuntimes(r.Context(), authorized, maxTasks, forceRecheck...)
	if err != nil {
		slog.Warn("claim tasks failed", append(logger.RequestAttrs(r), "error", err)...)
		writeError(w, http.StatusInternalServerError, "failed to claim tasks")
		return
	}

	out := make([]AgentTaskResponse, 0, len(claimed))
	for i := range claimed {
		if r.Context().Err() != nil {
			break
		}
		task := claimed[i]
		rt, ok := runtimeByID[uuidToString(task.RuntimeID)]
		if !ok {
			// Service guards claims to the authorized set; a miss here would be
			// a stray cross-daemon claim. Leave it for the owning daemon's
			// reclaim path rather than shipping it to the wrong machine.
			continue
		}
		rtWorkspaceID := uuidToString(rt.WorkspaceID)
		// Stale comment-plan repair must run for the batch path too: otherwise a
		// task whose trigger was deleted (only coalesced survive) would be
		// finalized+dispatched with no comment input, silently dropping the
		// surviving user comment. On repair (or hard failure) the task is
		// cancelled / left for reclaim and omitted from the batch.
		if handled, _ := h.repairStaleCommentPlanIfNeeded(r.Context(), &task, rtWorkspaceID); handled {
			continue
		}
		resp, deliveredCommentIDs, issueSnapshot, _, _, failure := h.buildClaimedTaskResponse(r, &task, rt, uuidToString(task.RuntimeID), rtWorkspaceID)
		if failure != nil {
			// Builder rejected this task (workspace isolation / chat-input);
			// it has already settled the task where the failure requires it.
			// Undelivered claims are recovered below with a separate budget.
			continue
		}
		if !rt.OwnerID.Valid {
			slog.Error("batch claim: runtime owner missing; cancelling task to avoid unscoped agent credentials",
				"task_id", uuidToString(task.ID), "runtime_id", uuidToString(task.RuntimeID))
			if _, cerr := h.TaskService.CancelTask(r.Context(), task.ID); cerr != nil {
				slog.Error("batch claim: cancel after missing runtime owner failed",
					"task_id", uuidToString(task.ID), "error", cerr)
			}
			continue
		}
		tokenStr, terr := auth.GenerateAgentTaskToken()
		if terr != nil {
			slog.Error("batch claim: generate task token failed; requeueing claim",
				"task_id", uuidToString(task.ID), "error", terr)
			continue
		}
		remoteMCPToken, daemonTokens, derr := remoteMCPDaemonTokenForClaim(resp, rt)
		if derr != nil {
			slog.Error("batch claim: generate Remote MCP daemon token failed; requeueing claim",
				"task_id", uuidToString(task.ID), "error", derr)
			continue
		}
		// Route through the SAME finalization as the per-runtime endpoint so the
		// token and the comment-delivery receipt (delivered_comment_ids for
		// comment/coalesced-comment tasks) are persisted atomically; on failure
		// the exact claim is requeued and omitted from this batch. The shared
		// final delivery gate re-verifies current runtime ownership inside the
		// same transaction; a rejected task is settled via FailTask and skipped
		// while valid tasks in the same batch continue.
		commentBackedTask := task.TriggerCommentID.Valid || len(task.CoalescedCommentIds) > 0
		receipt, deliveryFailure, ferr := h.finalizeClaimDelivery(r.Context(), &task, rt, uuidToString(task.RuntimeID), rtWorkspaceID, &resp, db.CreateTaskTokenParams{
			ID:          dbid.NewV7(),
			TokenHash:   auth.HashToken(tokenStr),
			TaskID:      task.ID,
			AgentID:     task.AgentID,
			WorkspaceID: parseUUID(resp.WorkspaceID),
			UserID:      rt.OwnerID,
			ExpiresAt:   pgtype.Timestamptz{Time: time.Now().Add(24 * time.Hour), Valid: true},
		}, deliveredCommentIDs, commentBackedTask, issueSnapshot, daemonTokens...)
		if ferr != nil {
			slog.Error("batch claim: finalize task claim failed; requeueing claim",
				"task_id", uuidToString(task.ID), "error", ferr)
			continue
		}
		if deliveryFailure != nil {
			if !deliveryFailure.settled {
				slog.Error("batch claim: delivery rejection settlement failed",
					"task_id", uuidToString(task.ID), "outcome", deliveryFailure.outcome,
					"error", deliveryFailure.message)
			}
			continue
		}
		resp.AuthToken = tokenStr
		resp.RemoteMCPDaemonToken = remoteMCPToken
		resp.DeliveredCommentIDs = uuidStringsOrEmpty(receipt)
		out = append(out, resp)
	}

	if len(out) > 0 {
		slog.Info("tasks claimed by runtime batch",
			"runtimes", len(authorized), "requested_max", maxTasks, "claimed", len(out),
			"total_ms", time.Since(start).Milliseconds())
	}
	response := map[string]any{"tasks": out}
	if wantAck {
		// An explicit empty list keeps outstanding hints pending. Absence
		// tells the client to fall back to legacy polling.
		if forceRechecked == nil {
			forceRechecked = []string{}
		}
		response["force_rechecked_runtime_ids"] = forceRechecked
	}
	// Only opted-in daemons understand this additive response metadata. Query
	// after the claim so a future fire_at can shorten the long healthy-WS safety
	// poll; a task that crossed fire_at during this request yields a bounded
	// follow-up hint and is promoted on the next claim. If the lookup fails,
	// omit the support bit so the daemon conservatively retains its ordinary
	// PollInterval. Omitted claims also retain that short poll in case recovery
	// failed or the task_available wakeup raced with this response.
	if len(out) == len(claimed) && len(out) < maxTasks && requestHasClientCapability(r, protocol.DaemonCapabilityClaimPollHintsV1) {
		nextDeferred, nextErr := h.Queries.NextDeferredTaskFireAtForRuntimes(r.Context(), db.NextDeferredTaskFireAtForRuntimesParams{
			RuntimeIds:       authorized,
			RuntimeStaleSecs: service.RuntimeClaimFreshnessSeconds,
		})
		if nextErr != nil {
			slog.Warn("batch claim: next deferred task lookup failed; retaining short client poll",
				"error", nextErr)
		} else {
			response["claim_poll_hint_supported"] = true
			if nextDeferred.Valid {
				response["next_deferred_task_after_ms"] = claimPollHintDelay(time.Now(), nextDeferred.Time).Milliseconds()
			}
		}
	}
	if len(out) != len(claimed) {
		// HTTP/1.1 cannot process another request until this handler returns.
		// Keep the next claim off this connection while recovery is running.
		w.Header().Set("Connection", "close")
	}
	writeMeasuredJSON(w, http.StatusOK, response)
	if len(out) != len(claimed) {
		// Deliver successful payloads before batch recovery side effects. Cache
		// invalidation, event listeners and cross-node wakeups can use their own
		// timeouts, so the recovery context alone cannot bound the response wait.
		// HTTP already advertises Content-Length; flushing sends the whole body.
		// WS keeps cleanup in the existing RPC worker after queuing its response.
		cleanup := func() {
			h.requeueUndeliveredBatchClaims(r.Context(), claimed, out, responseDeadline)
		}
		if !daemonws.AfterRPCResponse(r.Context(), cleanup) {
			_ = http.NewResponseController(w).Flush()
			cleanup()
		}
	}
}

func (h *Handler) ExtendTaskPrepareLease(w http.ResponseWriter, r *http.Request) {
	runtimeID := chi.URLParam(r, "runtimeId")
	taskID := chi.URLParam(r, "taskId")

	runtime, ok := h.requireDaemonRuntimeAccess(w, r, runtimeID)
	if !ok {
		return
	}
	task, taskWorkspaceID, ok := h.requireDaemonTaskAccessWithWorkspace(w, r, taskID)
	if !ok {
		return
	}
	if taskWorkspaceID != uuidToString(runtime.WorkspaceID) || uuidToString(task.RuntimeID) != runtimeID {
		writeError(w, http.StatusNotFound, "task not found")
		return
	}

	updated, err := h.TaskService.ExtendTaskPrepareLease(r.Context(), parseUUID(taskID), parseUUID(runtimeID))
	if err != nil {
		slog.Warn("extend task prepare lease failed", "task_id", taskID, "runtime_id", runtimeID, "error", err)
		writeError(w, http.StatusBadRequest, err.Error())
		return
	}

	writeJSON(w, http.StatusOK, taskToResponse(*updated, taskWorkspaceID))
}

func (c *Client) ExtendTaskPrepareLease(ctx context.Context, runtimeID, taskID string) error {
	return c.postJSON(ctx, fmt.Sprintf("/api/daemon/runtimes/%s/tasks/%s/prepare-lease", runtimeID, taskID), map[string]any{}, nil)
}

func (s *TaskService) ExtendTaskPrepareLease(ctx context.Context, taskID, runtimeID pgtype.UUID) (*db.AgentTaskQueue, error) {
	task, err := s.Queries.ExtendAgentTaskPrepareLease(ctx, db.ExtendAgentTaskPrepareLeaseParams{
		ID:        taskID,
		RuntimeID: runtimeID,
		LeaseSecs: prepareLeaseDuration.Seconds(),
	})
	if err != nil {
		return nil, fmt.Errorf("extend task prepare lease: %w", err)
	}
	if task.Status == "dispatched" {
		// Use the successful response time as a conservative application-clock
		// approximation of the DB lease start. Scheduling slightly late by query
		// latency is safer than an early failed check suppressing the hint until
		// the next backstop.
		s.extendTaskReclaimHint(task, time.Now().Add(prepareLeaseDuration))
	} else {
		s.forgetTaskReclaim(task)
	}
	return &task, nil
}

func (h *Handler) ResolveTaskSkillBundles(w http.ResponseWriter, r *http.Request) {
	runtimeID := chi.URLParam(r, "runtimeId")
	taskID := chi.URLParam(r, "taskId")

	runtime, ok := h.requireDaemonRuntimeAccess(w, r, runtimeID)
	if !ok {
		return
	}
	task, taskWorkspaceID, ok := h.requireDaemonTaskAccessWithWorkspace(w, r, taskID)
	if !ok {
		return
	}
	if taskWorkspaceID != uuidToString(runtime.WorkspaceID) || uuidToString(task.RuntimeID) != runtimeID {
		writeError(w, http.StatusNotFound, "task not found")
		return
	}
	if task.Status != "dispatched" && task.Status != "waiting_local_directory" {
		writeError(w, http.StatusConflict, "task is not preparing")
		return
	}

	var req resolveSkillBundlesRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid request body")
		return
	}
	if len(req.Skills) == 0 {
		writeJSON(w, http.StatusOK, map[string]any{"bundles": []service.AgentSkillData{}})
		return
	}

	// Validate before reading: a malformed ref is rejected the same way it
	// always was, now without paying for a load first.
	wanted := make([]service.AgentSkillBundleRef, 0, len(req.Skills))
	for _, ref := range req.Skills {
		if ref.ID == "" || ref.Source == "" || ref.Hash == "" {
			writeError(w, http.StatusBadRequest, "invalid skill ref")
			return
		}
		wanted = append(wanted, service.AgentSkillBundleRef{ID: ref.ID, Source: ref.Source})
	}

	// Load ONLY what was asked for. The daemon resolves one skill per request,
	// so serving these out of the agent's full bundle set meant reading and
	// hashing every skill the agent has, once per request, to return one of
	// them — quadratic in skill count across a cold dispatch.
	allowed, err := h.TaskService.LoadRequestedAgentSkillBundles(r.Context(), task.AgentID, wanted)
	if err != nil {
		// 5xx, not a partial answer: the daemon's resolve retry can recover a
		// transient read, and a bundle assembled from a failed read would pass
		// its client-side validation and be cached as if it were complete.
		slog.Error("resolve skill bundles: load agent skills failed",
			"task_id", uuidToString(task.ID), "agent_id", uuidToString(task.AgentID), "error", err)
		writeError(w, http.StatusInternalServerError, "failed to load skill bundles")
		return
	}

	resolved := make([]service.AgentSkillData, 0, len(req.Skills))
	for _, ref := range req.Skills {
		bundle, ok := allowed[service.AgentSkillBundleKey(ref.Source, ref.ID)]
		if !ok {
			writeError(w, http.StatusNotFound, "skill bundle not found")
			return
		}
		if ref.Source == skillbundle.SourcePlugin && bundle.Hash != ref.Hash {
			writeError(w, http.StatusConflict, "pinned plugin skill bundle hash mismatch")
			return
		}
		resolved = append(resolved, bundle)
	}

	writeJSON(w, http.StatusOK, map[string]any{"bundles": resolved})
}

func (h *Handler) ListPendingTasksByRuntime(w http.ResponseWriter, r *http.Request) {
	runtimeID := chi.URLParam(r, "runtimeId")

	// Verify the caller owns this runtime's workspace.
	runtime, ok := h.requireDaemonRuntimeAccess(w, r, runtimeID)
	if !ok {
		return
	}
	workspaceID := uuidToString(runtime.WorkspaceID)

	tasks, err := h.Queries.ListPendingTasksByRuntime(r.Context(), parseUUID(runtimeID))
	if err != nil {
		writeError(w, http.StatusInternalServerError, "failed to list pending tasks")
		return
	}

	resp := make([]AgentTaskResponse, len(tasks))
	for i, t := range tasks {
		resp[i] = taskToResponse(t, workspaceID)
	}
	writeJSON(w, http.StatusOK, resp)
}

func (h *Handler) ReportUpdateResult(w http.ResponseWriter, r *http.Request) {
	runtimeID := chi.URLParam(r, "runtimeId")

	// Verify the caller owns this runtime's workspace.
	if _, ok := h.requireDaemonRuntimeAccess(w, r, runtimeID); !ok {
		return
	}

	updateID := chi.URLParam(r, "updateId")

	existing, err := h.UpdateStore.Get(r.Context(), updateID)
	if err != nil {
		slog.Warn("load update failed", append(logger.RequestAttrs(r), "error", err)...)
		writeError(w, http.StatusInternalServerError, "failed to load update")
		return
	}
	if existing == nil || existing.RuntimeID != runtimeID {
		writeError(w, http.StatusNotFound, "update not found")
		return
	}
	if updateRequestTerminal(existing.Status) {
		slog.Debug("ignoring stale update report", "runtime_id", runtimeID, "update_id", updateID, "status", existing.Status)
		writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
		return
	}

	var req struct {
		Status string `json:"status"` // "running", "completed", or "failed"
		Output string `json:"output"`
		Error  string `json:"error"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid request body")
		return
	}

	switch req.Status {
	case "completed":
		if err := h.UpdateStore.Complete(r.Context(), updateID, req.Output); err != nil {
			slog.Error("UpdateStore Complete failed", "error", err, "update_id", updateID)
			writeError(w, http.StatusInternalServerError, "failed to persist completion")
			return
		}
	case "failed":
		if err := h.UpdateStore.Fail(r.Context(), updateID, req.Error); err != nil {
			slog.Error("UpdateStore Fail failed", "error", err, "update_id", updateID)
			writeError(w, http.StatusInternalServerError, "failed to persist failure")
			return
		}
	case "running":
		// No-op: status is already "running" from PopPending. This call is
		// just a progress signal from the daemon to confirm it received the
		// update command and is executing it.
	default:
		writeError(w, http.StatusBadRequest, "invalid status: "+req.Status)
		return
	}

	writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
}

func (c *Client) ReportUpdateResult(ctx context.Context, runtimeID, updateID string, result map[string]any) error {
	return c.postJSON(ctx, fmt.Sprintf("/api/daemon/runtimes/%s/update/%s/result", runtimeID, updateID), result, nil)
}

func (h *Handler) ReportModelListResult(w http.ResponseWriter, r *http.Request) {
	runtimeID := chi.URLParam(r, "runtimeId")

	if _, ok := h.requireDaemonRuntimeAccess(w, r, runtimeID); !ok {
		return
	}

	requestID := chi.URLParam(r, "requestId")

	// Fetch first so we can ignore stale reports for already-terminal
	// requests (e.g. the heartbeat response that triggered the daemon
	// run was a retry, and the original report already landed).
	existing, err := h.ModelListStore.Get(r.Context(), requestID)
	if err != nil {
		slog.Warn("load request failed", append(logger.RequestAttrs(r), "error", err)...)
		writeError(w, http.StatusInternalServerError, "failed to load request")
		return
	}
	if existing == nil || existing.RuntimeID != runtimeID {
		writeError(w, http.StatusNotFound, "request not found")
		return
	}
	if modelListRequestTerminal(existing.Status) {
		slog.Debug("ignoring stale model list report", "runtime_id", runtimeID, "request_id", requestID, "status", existing.Status)
		writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
		return
	}

	var body struct {
		Status string       `json:"status"` // "completed" or "failed"
		Models []ModelEntry `json:"models"`
		// UnavailableModels is what the runtime named but will not run. Older
		// daemons omit it; absent simply means no advisory rows to show.
		UnavailableModels []UnavailableModelEntry `json:"unavailable_models"`
		Supported         *bool                   `json:"supported"`
		Error             string                  `json:"error"`
		// Fallback marks a completed report whose models are a static
		// stand-in the provider substituted after discovery failed, not the
		// runtime's real catalog. Older daemons omit it; absent means "this
		// daemon cannot tell us", which stays the pre-MUL-5549 behaviour.
		Fallback bool `json:"fallback"`
	}
	if err := json.NewDecoder(r.Body).Decode(&body); err != nil {
		writeError(w, http.StatusBadRequest, "invalid request body")
		return
	}

	if body.Status == "completed" {
		// Older daemons may omit `supported`; default to true to keep
		// the UI usable while they haven't been redeployed yet.
		supported := true
		if body.Supported != nil {
			supported = *body.Supported
		}
		if err := h.ModelListStore.Complete(r.Context(), requestID, body.Models, body.UnavailableModels, supported); err != nil {
			// Surface the store failure as 5xx so the daemon can retry instead
			// of swallowing the report (leaves the request stuck in running
			// until the server-side timeout, which is exactly the "looks OK
			// but nothing happens" class of bug we're trying to avoid).
			slog.Error("ModelListStore Complete failed", "error", err, "request_id", requestID)
			writeError(w, http.StatusInternalServerError, "failed to persist completion")
			return
		}
		// Warm the catalog cache so the next picker open renders instantly
		// (MUL-5444). A cache write failure is not the daemon's problem — the
		// report itself succeeded — so it is logged, not surfaced.
		//
		// A completed-but-uncacheable result (empty catalog, or a runtime that
		// does not honour per-agent model selection) is the freshest truth we
		// have: drop any older snapshot instead of letting the fast path keep
		// serving a catalog the runtime no longer advertises. Failed reports
		// deliberately leave the cache alone — serving the last known good list
		// through a transient discovery failure is the point of the cache.
		//
		// A fallback report is a failed report wearing a completed label: the
		// models are a static stand-in, so they are neither fresh truth to
		// store nor grounds to discard a real catalog we already hold. Treat it
		// like a failure and leave the cache untouched (MUL-5549).
		if h.ModelCatalogCache != nil {
			switch modelCatalogCacheDecision(body.Models, supported, body.Fallback) {
			case modelCatalogCacheStore:
				if err := h.ModelCatalogCache.Put(r.Context(), runtimeID, body.Models, body.UnavailableModels, supported); err != nil {
					slog.Warn("model catalog cache write failed", "error", err, "runtime_id", runtimeID)
				}
			case modelCatalogCacheDrop:
				if err := h.ModelCatalogCache.Invalidate(r.Context(), runtimeID); err != nil {
					slog.Warn("model catalog cache invalidate failed", "error", err, "runtime_id", runtimeID)
				}
			case modelCatalogCacheKeep:
				slog.Debug("model discovery reported a fallback catalog; leaving cached catalog untouched",
					"runtime_id", runtimeID, "count", len(body.Models))
			}
		}
	} else {
		if err := h.ModelListStore.Fail(r.Context(), requestID, body.Error); err != nil {
			slog.Error("ModelListStore Fail failed", "error", err, "request_id", requestID)
			writeError(w, http.StatusInternalServerError, "failed to persist failure")
			return
		}
	}

	slog.Debug("model list report", "runtime_id", runtimeID, "request_id", requestID, "status", body.Status, "count", len(body.Models))
	writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
}

func (c *Client) ReportModelListResult(ctx context.Context, runtimeID, requestID string, result map[string]any) error {
	return c.postJSON(ctx, fmt.Sprintf("/api/daemon/runtimes/%s/models/%s/result", runtimeID, requestID), result, nil)
}

