func (h *Handler) GetTaskStatus(w http.ResponseWriter, r *http.Request) {
	taskID := chi.URLParam(r, "taskId")
	taskUUID, ok := parseUUIDOrBadRequest(w, taskID, "task_id")
	if !ok {
		return
	}

	// This endpoint is polled by every in-flight daemon task. Load only the
	// status and the owning agent's workspace instead of the full task plus its
	// optional issue / chat / autopilot source chain.
	task, err := h.Queries.GetAgentTaskStatus(r.Context(), taskUUID)
	if err != nil {
		// A missing row is the daemon's hard interruption signal. Keep transient
		// database failures distinct so a brief outage cannot kill healthy work.
		if isNotFound(err) {
			writeError(w, http.StatusNotFound, "task not found")
			return
		}
		slog.Warn("get agent task status failed", "task_id", taskID, "error", err)
		writeError(w, http.StatusInternalServerError, "failed to load task")
		return
	}

	// Runtime-level authorization (MUL-8154) from the same row: a bound task
	// is visible only to its runtime's daemon (owner / matching daemon token).
	// An unbound task — its runtime was deleted and the task kept as history —
	// exposes only its status, so workspace access stays sufficient there:
	// the daemon still needs a terminal answer to stop polling.
	if !h.requireDaemonWorkspaceAccess(w, r, uuidToString(task.WorkspaceID)) {
		return
	}
	if task.RuntimeID.Valid {
		if uuidToString(task.RuntimeWorkspaceID) != uuidToString(task.WorkspaceID) ||
			!daemonRuntimeBindingAllowed(r, task.RuntimeDaemonID, task.RuntimeOwnerID) {
			writeError(w, http.StatusNotFound, "task not found")
			return
		}
	}

	writeJSON(w, http.StatusOK, map[string]string{"status": task.Status})
}

func (c *Client) GetTaskStatus(ctx context.Context, taskID string) (string, error) {
	var resp struct {
		Status string `json:"status"`
	}
	if err := c.getJSON(ctx, fmt.Sprintf("/api/daemon/tasks/%s/status", taskID), &resp); err != nil {
		return "", err
	}
	return resp.Status, nil
}

func (h *Handler) StartTask(w http.ResponseWriter, r *http.Request) {
	taskID := chi.URLParam(r, "taskId")

	// Verify the caller owns this task's workspace.
	startTask, workspaceID, ok := h.requireDaemonTaskAccessWithWorkspace(w, r, taskID)
	if !ok {
		return
	}

	var req struct {
		Capabilities []string `json:"capabilities"`
		RuntimeID    string   `json:"runtime_id"`
		DispatchedAt string   `json:"dispatched_at"`
	}
	if r.ContentLength != 0 {
		if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
			writeError(w, http.StatusBadRequest, "invalid request body")
			return
		}
	}
	legacy := req.RuntimeID == "" && req.DispatchedAt == ""
	var claim db.LockAgentTaskStartClaimParams
	if !legacy {
		runtimeID, ok := parseUUIDOrBadRequest(w, req.RuntimeID, "runtime_id")
		if !ok {
			return
		}
		generation, parseErr := time.Parse(time.RFC3339Nano, req.DispatchedAt)
		if parseErr != nil || generation.Nanosecond()%1000 != 0 {
			writeError(w, http.StatusBadRequest, "dispatched_at must be a PostgreSQL claim timestamp")
			return
		}
		if startTask.RuntimeID != runtimeID || !startTask.DispatchedAt.Valid || !startTask.DispatchedAt.Time.Equal(generation) {
			writeError(w, http.StatusConflict, "task claim is stale")
			return
		}
		claim = db.LockAgentTaskStartClaimParams{
			ID: startTask.ID, RuntimeID: runtimeID,
			DispatchedAt: pgtype.Timestamptz{Time: generation, Valid: true},
		}
	}
	// Check the requested generation before a cleanup guard can mutate a claim.
	waiting, waitErr := h.Queries.TaskWaitingForProcessCleanup(r.Context(), startTask.ID)
	if waitErr != nil {
		writeError(w, http.StatusInternalServerError, "could not verify pending process cleanup")
		return
	}
	if waiting {
		if _, err := h.TaskService.RequeueTaskAfterClaimFailure(r.Context(), startTask); err != nil {
			writeError(w, http.StatusInternalServerError, "failed to defer task until process cleanup")
			return
		}
		writeError(w, http.StatusConflict, "previous run is still stopping; task was requeued")
		return
	}
	blocked, blockErr := h.Queries.TaskBlockedByProcessCleanup(r.Context(), startTask.ID)
	if blockErr != nil {
		writeError(w, http.StatusInternalServerError, "could not verify prior process cleanup")
		return
	}
	if blocked {
		if _, err := h.TaskService.FailTask(r.Context(), startTask.ID,
			"A previous run's process cleanup is unconfirmed. Check background processes, then manually rerun the task to resume this agent.",
			"", "", "", taskfailure.ReasonProcessCleanupBlocked.String(), false, "", ""); err != nil {
			writeError(w, http.StatusInternalServerError, "failed to record process cleanup block")
			return
		}
		writeError(w, http.StatusConflict, "task blocked by unconfirmed process cleanup; manual rerun required")
		return
	}
	offered := service.TaskStartCapabilities{
		Supplement:     slices.Contains(req.Capabilities, protocol.DaemonCapabilityTaskSupplementV1),
		ProcessCleanup: slices.Contains(req.Capabilities, protocol.DaemonCapabilityPiProcessCleanupV1) || slices.Contains(req.Capabilities, protocol.DaemonCapabilityMuseAppProcessCleanupV1),
	}
	var task *db.AgentTaskQueue
	var err error
	if legacy {
		// Older daemons send {} and retain their single-winner behavior.
		task, err = h.TaskService.StartTask(r.Context(), startTask.ID, offered)
	} else {
		task, err = h.TaskService.StartTaskForClaim(r.Context(), claim, offered)
	}
	if err != nil {
		slog.Warn("start task failed", "task_id", taskID, "error", err)
		if errors.Is(err, pgx.ErrNoRows) {
			status := http.StatusConflict
			if legacy {
				status = http.StatusBadRequest
			}
			writeError(w, status, "task claim is stale or task is no longer startable")
		} else {
			writeError(w, http.StatusInternalServerError, "failed to start task")
		}
		return
	}

	slog.Info("task started", "task_id", taskID, "agent_id", uuidToString(task.AgentID))
	resp := taskToResponse(*task, workspaceID)
	var result struct {
		ProcessCleanupCapability string `json:"process_cleanup_capability"`
	}
	if json.Unmarshal(task.Result, &result) == nil {
		resp.ProcessCleanupCapability = result.ProcessCleanupCapability
	}
	// Echo the capability the server actually committed for this exact run.
	// A daemon must use this response rather than its own offer: an old server
	// ignores the offer and omits the field, which keeps daemon-first rollouts
	// fail closed without requiring synchronized deployment.
	if task.IssueID.Valid || task.ChatSessionID.Valid {
		if capability, capabilityErr := h.Queries.GetTaskSupplementCapability(r.Context(), task.ID); capabilityErr == nil {
			resp.SupplementCapability = capability.Capability
		} else if !errors.Is(capabilityErr, pgx.ErrNoRows) {
			slog.Warn("start task: failed to load negotiated supplement capability", "task_id", taskID, "error", capabilityErr)
		}
	}
	writeJSON(w, http.StatusOK, resp)
}

func (c *Client) StartTask(ctx context.Context, task Task, capabilities ...string) (bool, error) {
	var negotiated bool
	var decodeResponse responseDecoder = func(r io.Reader) error {
		data, err := io.ReadAll(io.LimitReader(r, maxStartTaskResponseBytes+1))
		if err != nil {
			return err
		}
		if len(data) > maxStartTaskResponseBytes {
			return fmt.Errorf("%w: task start exceeds %d bytes", errInvalidResponseBody, maxStartTaskResponseBytes)
		}
		var response struct {
			SupplementCapability     string `json:"supplement_capability"`
			ProcessCleanupCapability string `json:"process_cleanup_capability"`
		}
		// Empty acknowledgements start the task without negotiating supplements.
		// Invalid JSON fails without retrying; transport read failures can retry.
		if len(data) != 0 {
			if err := json.Unmarshal(data, &response); err != nil {
				return fmt.Errorf("%w: task start: %w", errInvalidResponseBody, err)
			}
		}
		negotiated = response.SupplementCapability == protocol.DaemonCapabilityTaskSupplementV1
		if slices.Contains(capabilities, protocol.DaemonCapabilityMuseAppProcessCleanupV1) && response.ProcessCleanupCapability != protocol.DaemonCapabilityMuseAppProcessCleanupV1 {
			return fmt.Errorf("%w: Muse app requires server support for remote execution cleanup; upgrade the Workpal server before using this runtime", errInvalidResponseBody)
		}
		return nil
	}
	path := fmt.Sprintf("/api/daemon/tasks/%s/start", task.ID)
	if !task.StartClaimSupported {
		// Old servers have no safe replay contract. Preserve one attempt.
		err := c.postJSON(ctx, path, map[string]any{"capabilities": capabilities}, decodeResponse)
		return err == nil && negotiated, err
	}
	if task.RuntimeID == "" || task.DispatchedAt == "" {
		return false, fmt.Errorf("start task: claim is missing runtime_id or dispatched_at")
	}
	ctx, cancel := context.WithTimeout(ctx, startTaskTimeout)
	defer cancel()
	err := c.postJSONWithRetry(ctx, path, map[string]any{
		"runtime_id":    task.RuntimeID,
		"capabilities":  capabilities,
		"dispatched_at": task.DispatchedAt,
	}, decodeResponse, startTaskRetrySchedule)
	var reqErr *requestError
	if errors.As(err, &reqErr) && reqErr.StatusCode == http.StatusConflict {
		return false, fmt.Errorf("%w: %w", errStartClaimRejected, err)
	}
	return err == nil && negotiated, err
}

func (s *TaskService) StartTask(ctx context.Context, taskID pgtype.UUID, capabilities ...TaskStartCapabilities) (*db.AgentTaskQueue, error) {
	var offered TaskStartCapabilities
	if len(capabilities) > 0 {
		offered = capabilities[0]
	}
	var task db.AgentTaskQueue
	var change *qoderIssueChange
	err := s.runInTx(ctx, func(q *db.Queries) error {
		var err error
		task, err = q.StartAgentTaskWithSupplement(ctx, db.StartAgentTaskWithSupplementParams{TaskID: taskID, EnableTaskSupplement: offered.Supplement, EnableProcessCleanup: offered.ProcessCleanup})
		if err != nil {
			return err
		}
		change, err = syncQoderIssue(ctx, q, task, false)
		return err
	})
	if err != nil {
		return nil, fmt.Errorf("start task: %w", err)
	}
	s.publishQoderIssueChange(ctx, change)
	s.taskStarted(ctx, task)
	return &task, nil
}

func (h *Handler) ClaimTaskSupplement(w http.ResponseWriter, r *http.Request) {
	taskID := chi.URLParam(r, "taskId")
	task, ok := h.requireDaemonTaskAccess(w, r, taskID)
	if !ok {
		return
	}
	if task.ChatSessionID.Valid && !task.IssueID.Valid {
		row, err := h.Queries.ClaimNextChatTaskSupplement(r.Context(), task.ID)
		if errors.Is(err, pgx.ErrNoRows) {
			writeJSON(w, http.StatusOK, map[string]any{})
		} else if err != nil {
			writeError(w, http.StatusInternalServerError, "failed to claim chat guidance")
		} else {
			// Keep the daemon wire contract: this opaque id names a chat message.
			writeJSON(w, http.StatusOK, map[string]any{"comment_id": uuidToString(row.MessageID), "author_type": "member", "author_name": row.AuthorName, "content": row.Content})
		}
		return
	}
	var req struct {
		Capabilities []string `json:"capabilities"`
	}
	// Older daemons send {} and frame every message as a human's, so they are
	// never handed an agent's message (see ClaimNextTaskSupplement). A
	// malformed body only loses the capability.
	_ = json.NewDecoder(http.MaxBytesReader(w, r.Body, 64<<10)).Decode(&req)
	rendersAuthorType := slices.Contains(req.Capabilities, protocol.DaemonCapabilityTaskSupplementAuthorV1)
	row, err := h.Queries.ClaimNextTaskSupplement(r.Context(), db.ClaimNextTaskSupplementParams{
		TaskID: parseUUID(taskID), IncludeAgentAuthored: rendersAuthorType,
	})
	if errors.Is(err, pgx.ErrNoRows) {
		writeJSON(w, http.StatusOK, map[string]any{})
		return
	}
	if err != nil {
		writeError(w, http.StatusInternalServerError, "failed to claim additional message")
		return
	}
	writeJSON(w, http.StatusOK, map[string]any{
		"comment_id": uuidToString(row.CommentID), "author_type": row.AuthorType, "author_name": row.AuthorName,
		"content": row.Content,
	})
}

func (c *Client) ClaimTaskSupplement(ctx context.Context, taskID string) (*TaskSupplement, error) {
	var supplement TaskSupplement
	if err := c.postJSON(ctx, fmt.Sprintf("/api/daemon/tasks/%s/supplements/claim", taskID), map[string]any{
		"capabilities": []string{protocol.DaemonCapabilityTaskSupplementAuthorV1},
	}, &supplement); err != nil {
		return nil, err
	}
	if supplement.CommentID == "" {
		return nil, nil
	}
	return &supplement, nil
}

func (h *Handler) AckTaskSupplement(w http.ResponseWriter, r *http.Request) {
	taskID := chi.URLParam(r, "taskId")
	task, ok := h.requireDaemonTaskAccess(w, r, taskID)
	if !ok {
		return
	}
	commentID, ok := parseUUIDOrBadRequest(w, chi.URLParam(r, "commentId"), "comment id")
	if !ok {
		return
	}
	var req ackTaskSupplementRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid request body")
		return
	}
	if task.ChatSessionID.Valid && !task.IssueID.Valid {
		h.ackChatTaskSupplement(w, r, task, commentID, req.Delivered)
		return
	}
	var row db.TaskSupplement
	var err error
	if req.Delivered {
		row, err = h.Queries.AckTaskSupplementDelivered(r.Context(), db.AckTaskSupplementDeliveredParams{
			TaskID: parseUUID(taskID), CommentID: commentID,
		})
	} else {
		reason := stableTaskSupplementFailureReason(req.Error)
		row, err = h.Queries.AckTaskSupplementFailed(r.Context(), db.AckTaskSupplementFailedParams{
			TaskID: parseUUID(taskID), CommentID: commentID,
			FailureReason: pgtype.Text{String: reason, Valid: true},
		})
	}
	if errors.Is(err, pgx.ErrNoRows) {
		writeError(w, http.StatusConflict, "additional message is no longer deliverable")
		return
	}
	if err != nil {
		writeError(w, http.StatusInternalServerError, "failed to acknowledge additional message")
		return
	}
	h.publishTaskSupplementUpdate(r, row)
	writeJSON(w, http.StatusOK, supplementReceipt(row))
}

func (c *Client) AckTaskSupplement(ctx context.Context, taskID, commentID string, delivered bool, errText string) error {
	return c.postJSONWithRetry(ctx,
		fmt.Sprintf("/api/daemon/tasks/%s/supplements/%s/ack", taskID, commentID),
		map[string]any{"delivered": delivered, "error": errText}, nil,
		[]time.Duration{0, 100 * time.Millisecond, 300 * time.Millisecond})
}

