		h.TaskService.AutoUnresolveThreadOnReply(r.Context(), rootComment, uuidToString(caller.WorkspaceID), authorType, uuidToString(authorID), pgtype.UUID{})
	}

	writeJSON(w, http.StatusCreated, publicPluginComment(comment))
}

func (h *Handler) ListPluginTaskMessages(w http.ResponseWriter, r *http.Request) {
	caller, actor, ok := h.pluginCaller(w, r, plugincontract.ScopeTasksRead)
	if !ok {
		return
	}
	taskID := chi.URLParam(r, "task_id")
	parsed, err := util.ParseUUID(taskID)
	if err != nil {
		publicapiv1.WriteProblem(w, r, http.StatusNotFound, "not_found", "task not found")
		return
	}
	task, err := h.Queries.GetAgentTask(r.Context(), parsed)
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			publicapiv1.WriteProblem(w, r, http.StatusNotFound, "not_found", "task not found")
		} else {
			publicapiv1.WriteProblem(w, r, http.StatusInternalServerError, "internal_error", "failed to load task")
		}
		return
	}
	scope, err := h.TaskService.ResolveTaskScopeChecked(r.Context(), task)
	if err != nil {
		publicapiv1.WriteProblem(w, r, http.StatusInternalServerError, "internal_error", "failed to resolve task scope")
		return
	}
	if scope.WorkspaceID != uuidToString(caller.WorkspaceID) {
		publicapiv1.WriteProblem(w, r, http.StatusNotFound, "not_found", "task not found")
		return
	}
	// Private transcripts require the session creator, even for workspace
	// admins. Plugin actors have no member authorization for private chats.
	if task.ChatSessionID.Valid && (!actor.isMember() ||
		scope.ChatSessionOwnerID == "" ||
		scope.ChatSessionOwnerID != uuidToString(actor.Member.UserID)) {
		publicapiv1.WriteProblem(w, r, http.StatusNotFound, "not_found", "task not found")
		return
	}
	// An issue-scoped grant reaches only tasks belonging to that issue.
	if caller.IssueScope.Valid && (!task.IssueID.Valid ||
		uuidToString(task.IssueID) != uuidToString(caller.IssueScope)) {
		publicapiv1.WriteProblem(w, r, http.StatusNotFound, "not_found", "task not found")
		return
	}

	var messages []db.TaskMessage
	if sinceStr := r.URL.Query().Get("since"); sinceStr != "" {
		sinceSeq, parseErr := strconv.Atoi(sinceStr)
		if parseErr != nil || sinceSeq < 0 {
			publicapiv1.WriteProblem(w, r, http.StatusBadRequest, "invalid_request", "invalid since parameter")
			return
		}
		messages, err = h.Queries.ListTaskMessagesSince(r.Context(), db.ListTaskMessagesSinceParams{
			TaskID: parsed,
			Seq:    int32(sinceSeq),
		})
	} else {
		messages, err = h.Queries.ListTaskMessages(r.Context(), parsed)
	}
	if err != nil {
		publicapiv1.WriteProblem(w, r, http.StatusInternalServerError, "internal_error", "failed to list task messages")
		return
	}

	includeThinking := r.URL.Query().Get("include") != "thinking=false"
	issueID := ""
	if task.IssueID.Valid {
		issueID = uuidToString(task.IssueID)
	}
	resp := make([]protocol.TaskMessagePayload, 0, len(messages))
	for _, m := range messages {
		if !includeThinking && m.Type == "thinking" {
			continue
		}
		resp = append(resp, taskMessageToPayload(m, taskID, issueID))
	}
	writeJSON(w, http.StatusOK, map[string]any{"messages": resp})
}

