	}
	w.WriteHeader(http.StatusNoContent)
}

func (h *Handler) DeletePluginStorage(w http.ResponseWriter, r *http.Request) {
	caller, actor, ok := h.pluginCaller(w, r, "")
	if !ok {
		return
	}
	scopeType, scopeID, ok := h.pluginStorageScope(w, r, caller, actor)
	if !ok {
		return
	}
	if err := h.PluginService.DeleteStorageValue(r.Context(), caller.Installation.ID, scopeType, scopeID, chi.URLParam(r, "key")); err != nil {
		writePluginActionError(w, r, err, "failed to delete storage")
		return
	}
	w.WriteHeader(http.StatusNoContent)
}

func (h *Handler) InvokePluginHook(w http.ResponseWriter, r *http.Request) {
	// No scope of its own: a hook is the plugin's own capability, and what it
	// may do on the way back is bounded by the installation's scopes when the
	// callback token is redeemed.
	caller, actor, ok := h.pluginCaller(w, r, "")
	if !ok {
		return
	}
	// A hook invoked from the UI is invoked BY somebody. A plugin's own server
	// calling this would be asking us to call it back, which is a loop with no
	// person in it and no reason to exist.
	if !actor.requireMember(w, r) {
		return
	}

	var req invokePluginHookRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid request body")
		return
	}
	switch req.Trigger {
	case plugincontract.TriggerUI, plugincontract.TriggerManual:
	default:
		// event is dispatched by the host, never asked for; agent arrives over
		// MCP. Accepting either here would let a browser drive a call site that
		// is supposed to have a different identity attached.
		writeError(w, http.StatusBadRequest, "trigger must be ui or manual")
		return
	}

	hook, err := service.FindHook(caller.Installation, chi.URLParam(r, "key"))
	if err != nil {
		writePluginError(w, err, "failed to load the hook")
		return
	}

	invocation := service.HookInvocation{
		Installation: caller.Installation,
		Hook:         hook,
		Trigger:      req.Trigger,
		// The person who pressed it. Writes the handler makes with the callback
		// token land as theirs, marked with via_plugin_id.
		Actor: service.HookActor{Type: "member", ID: actor.Member.UserID},
		Input: rawOrNil(req.Input),
	}
	if req.IssueID != "" {
		issue, ok := h.pluginIssueForUser(w, r, caller, req.IssueID)
		if !ok {
			return
		}
		invocation.IssueID = issue.ID
	}

	result, err := h.PluginService.InvokeHook(r.Context(), invocation, 1)
	if err != nil {
		// The status matters to the person watching: "the admin did not grant
		// this" and "the plugin author's server is down" are different problems
		// with different owners, and a generic 500 hides which one it is.
		writePluginError(w, err, "the hook call failed")
		return
	}
	writeJSON(w, http.StatusOK, result)
}

func (h *Handler) ListStoreThemes(w http.ResponseWriter, r *http.Request) {
	store := h.themeStore(w)
	if store == nil {
		return
	}
	themes, err := store.Themes(r.Context())
	if err != nil {
		writeThemeStoreError(w, r, err)
		return
	}
	downloads := h.themeStoreDownloads(r)
	out := make([]ThemeStoreTheme, 0, len(themes))
	for _, t := range themes {
		shots := []string{}
		revisions := map[string]string{}
		for _, mode := range themestore.Modes {
			if file, ok := t.Screenshots[mode]; ok {
				shots = append(shots, mode)
				sum := sha256.Sum256([]byte(file))
				revisions[mode] = hex.EncodeToString(sum[:6])
			}
		}
		out = append(out, ThemeStoreTheme{
			ID:                  t.ID,
			Name:                t.Name,
			Author:              t.Author,
			Repo:                t.Repo,
			Description:         t.Description,
			Modes:               t.Modes,
			Version:             t.Version,
			Size:                t.Package.Size,
			Screenshots:         shots,
			ScreenshotRevisions: revisions,
			UpdatedAt:           t.UpdatedAt,
			Downloads:           downloads[t.ID],
		})
	}
	writeJSON(w, http.StatusOK, map[string]any{"themes": out})
}

func (h *Handler) GetStoreThemePackage(w http.ResponseWriter, r *http.Request) {
	store := h.themeStore(w)
	if store == nil {
		return
	}
	theme, data, err := store.Package(r.Context(), chi.URLParam(r, "themeId"))
	if err != nil {
		writeThemeStoreError(w, r, err)
		return
	}
	w.Header().Set("Content-Type", "application/zip")
	w.Header().Set("Content-Length", strconv.Itoa(len(data)))
	w.Header().Set("X-Theme-Version", theme.Version)
	w.Header().Set("Cache-Control", "private, no-cache")
	w.Header().Set("X-Content-Type-Options", "nosniff")
	if _, err := w.Write(data); err != nil {
		return
	}
	if h.Queries != nil {
		if err := h.Queries.AddThemeStoreDownload(r.Context(), theme.ID); err != nil {
			slog.WarnContext(r.Context(), "theme store: count download", "theme", theme.ID, "error", err)
		}
	}
}

func (h *Handler) GetStoreThemeScreenshot(w http.ResponseWriter, r *http.Request) {
