	initiatorUUID, ok := parseUUIDOrBadRequest(w, userID, "user id")
	if !ok {
		return
	}
	var body RegisterWecomBYORequest
	r.Body = http.MaxBytesReader(w, r.Body, wecomBodyLimit)
	if err := json.NewDecoder(r.Body).Decode(&body); err != nil {
		writeError(w, http.StatusBadRequest, "invalid request body")
		return
	}
	inst, err := svc.Upsert(r.Context(), wecom.InstallationParams{
		WorkspaceID:     wsUUID,
		AgentID:         agentUUID,
		InstallerUserID: initiatorUUID,
		BotID:           strings.TrimSpace(body.BotID),
		Secret:          strings.TrimSpace(body.Secret),
		BotDisplayName:  strings.TrimSpace(body.BotName),
	})
	if err != nil {
		writeWecomInstallError(w, err, wsUUID, agentUUID)
		return
	}
	h.publish(protocol.EventWecomInstallationCreated, uuidToString(inst.WorkspaceID), "user", userID, map[string]any{
		"id": uuidToString(inst.ID),
	})
	writeJSON(w, http.StatusOK, wecomInstallationToResponse(inst))
}

func (h *Handler) BeginWecomInstall(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Cache-Control", "no-store")
	if h.WecomInstall == nil || !h.WecomInstall.Configured() {
		writeWecomScanBeginError(w, wecom.ErrInstallNotConfigured)
		return
	}
	userID, ok := requireUserID(w, r)
	if !ok {
		return
	}
	wsUUID, ok := parseUUIDOrBadRequest(w, chi.URLParam(r, "id"), "workspace id")
	if !ok {
		return
	}
	agentIDStr := strings.TrimSpace(r.URL.Query().Get("agent_id"))
	if agentIDStr == "" {
		writeError(w, http.StatusBadRequest, "agent_id is required")
		return
	}
	agentUUID, ok := parseUUIDOrBadRequest(w, agentIDStr, "agent_id")
	if !ok {
		return
	}
	key := strings.TrimSpace(r.Header.Get("Idempotency-Key"))
	if key == "" {
		writeError(w, http.StatusBadRequest, "Idempotency-Key header is required")
		return
	}

	// The route admits workspace owners and admins only; the agent still has
	// to be one of this workspace's.
	if _, err := h.Queries.GetAgentInWorkspace(r.Context(), db.GetAgentInWorkspaceParams{
		ID:          agentUUID,
		WorkspaceID: wsUUID,
	}); err != nil {
		writeError(w, http.StatusNotFound, "agent not found in this workspace")
		return
	}
	initiatorUUID, ok := parseUUIDOrBadRequest(w, userID, "user id")
	if !ok {
		return
	}

	res, err := h.WecomInstall.BeginInstall(r.Context(), wecom.BeginInstallParams{
		WorkspaceID:    wsUUID,
		AgentID:        agentUUID,
		InitiatorID:    initiatorUUID,
		IdempotencyKey: key,
	})
	if err != nil {
		writeWecomScanBeginError(w, err)
		return
	}
	writeJSON(w, http.StatusAccepted, beginWecomInstallResponse{
		SessionID:           res.SessionID,
		Status:              res.Status,
		PollIntervalSeconds: pollIntervalForWecomStatus(res.Status),
	})
}

func (h *Handler) GetWecomInstallStatus(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Cache-Control", "no-store")
	if h.WecomInstall == nil {
		writeError(w, http.StatusServiceUnavailable, "wecom scan install not enabled")
		return
	}
	if _, ok := requireUserID(w, r); !ok {
		return
	}
	wsUUID, ok := parseUUIDOrBadRequest(w, chi.URLParam(r, "id"), "workspace id")
	if !ok {
		return
	}
	sessionUUID, ok := parseUUIDOrBadRequest(w, strings.TrimSpace(chi.URLParam(r, "sessionId")), "session id")
	if !ok {
		return
	}

	// The route admits workspace owners and admins only, and GetSession reads
	// within this workspace, so a session from another one is not found.
	snap, err := h.WecomInstall.GetSession(r.Context(), wsUUID, sessionUUID, true)
	if err != nil {
		h.writeWecomSessionError(w, err)
		return
	}

	resp := wecomInstallStatusResponse{
		Status:              snap.Status,
		PollIntervalSeconds: pollIntervalForWecomStatus(snap.Status),
		ErrorReason:         snap.ErrorReason,
	}
	if snap.Status == wecom.InstallStatusPending {
		resp.QRCodeURL = snap.QRCodeURL
		if !snap.ExpiresAt.IsZero() {
			if remaining := int(time.Until(snap.ExpiresAt) / time.Second); remaining > 0 {
				resp.ExpiresInSeconds = remaining
			}
		}
	}
	if snap.InstallationID.Valid {
		resp.InstallationID = uuidToString(snap.InstallationID)
	}
	writeJSON(w, http.StatusOK, resp)
}

func (h *Handler) ListDingTalkInstallations(w http.ResponseWriter, r *http.Request) {
	if h.DingTalkInstall == nil {
		writeJSON(w, http.StatusOK, map[string]any{
			"installations":     []DingTalkInstallationResponse{},
			"configured":        false,
			"install_supported": false,
		})
		return
	}
	wsUUID, ok := parseUUIDOrBadRequest(w, chi.URLParam(r, "id"), "workspace id")
	if !ok {
		return
	}
	userID, ok := requireUserID(w, r)
	if !ok {
		return
	}
	member, ok := h.workspaceMember(w, r, uuidToString(wsUUID))
	if !ok {
		return
	}
	availableAgentIDs, visibleAgentIDs, loaded := h.dingtalkAgentVisibility(
		r.Context(), wsUUID, userID, member,
	)
	if !loaded {
		writeError(w, http.StatusInternalServerError, "failed to resolve dingtalk installation visibility")
		return
	}
	rows, err := h.DingTalkInstall.ListByWorkspace(r.Context(), wsUUID)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "failed to list dingtalk installations")
		return
	}
	bindingsByInstallation := map[pgtype.UUID][]string{}
	canViewAll := roleAllowed(member.Role, "owner", "admin")
	canViewAccountBindings := canViewAll
	if canViewAccountBindings {
		userUUID, ok := parseUUIDOrBadRequest(w, userID, "user id")
		if !ok {
			return
		}
		bindings, err := h.Queries.ListDingTalkUserBindingsForMember(r.Context(), db.ListDingTalkUserBindingsForMemberParams{
			WorkspaceID:   wsUUID,
			WorkpalUserID: userUUID,
		})
		if err != nil {
			writeError(w, http.StatusInternalServerError, "failed to list dingtalk user bindings")
			return
		}
		for _, binding := range bindings {
			bindingsByInstallation[binding.InstallationID] = append(
				bindingsByInstallation[binding.InstallationID],
				binding.ChannelUserID,
			)
		}
	}
	out := make([]DingTalkInstallationResponse, 0, len(rows))
	for _, row := range rows {
		agentID := uuidToString(row.AgentID)
		if !canViewAll {
			if _, canView := visibleAgentIDs[agentID]; !canView {
				continue
			}
		}
		response := dingtalkInstallationToResponse(row)
		_, response.AgentAvailable = availableAgentIDs[agentID]
		response.BoundDingTalkUserIDs = bindingsByInstallation[row.ID]
		out = append(out, response)
	}
	writeJSON(w, http.StatusOK, map[string]any{
		"installations":     out,
		"configured":        true,
		"install_supported": true,
	})
}

