func (h *Handler) GetAssigneeFrequency(w http.ResponseWriter, r *http.Request) {
	userID, ok := requireUserID(w, r)
	if !ok {
		return
	}
	workspaceID := h.resolveWorkspaceID(r)

	// Aggregate frequency from both data sources.
	freq := map[string]int64{} // key: "type:id"

	// Source 1: assignee_changed activities by this user.
	activityCounts, err := h.Queries.CountAssigneeChangesByActor(r.Context(), db.CountAssigneeChangesByActorParams{
		WorkspaceID: parseUUID(workspaceID),
		ActorID:     parseUUID(userID),
	})
	if err != nil {
		writeError(w, http.StatusInternalServerError, "failed to get assignee frequency")
		return
	}
	for _, row := range activityCounts {
		aType, _ := row.AssigneeType.(string)
		aID, _ := row.AssigneeID.(string)
		if aType != "" && aID != "" {
			freq[aType+":"+aID] += row.Frequency
		}
	}

	// Source 2: issues created by this user with an assignee.
	issueCounts, err := h.Queries.CountCreatedIssueAssignees(r.Context(), db.CountCreatedIssueAssigneesParams{
		WorkspaceID: parseUUID(workspaceID),
		CreatorID:   parseUUID(userID),
	})
	if err != nil {
		writeError(w, http.StatusInternalServerError, "failed to get assignee frequency")
		return
	}
	for _, row := range issueCounts {
		if !row.AssigneeType.Valid || !row.AssigneeID.Valid {
			continue
		}
		key := row.AssigneeType.String + ":" + uuidToString(row.AssigneeID)
		freq[key] += row.Frequency
	}

	// Build sorted response.
	result := make([]AssigneeFrequencyEntry, 0, len(freq))
	for key, count := range freq {
		// Split "type:id" — type is always "member" or "agent" (no colons).
		var aType, aID string
		for i := 0; i < len(key); i++ {
			if key[i] == ':' {
				aType = key[:i]
				aID = key[i+1:]
				break
			}
		}
		result = append(result, AssigneeFrequencyEntry{
			AssigneeType: aType,
			AssigneeID:   aID,
			Frequency:    count,
		})
	}
	sort.Slice(result, func(i, j int) bool {
		return result[i].Frequency > result[j].Frequency
	})

	writeJSON(w, http.StatusOK, result)
}

func (h *Handler) GetSearchIndexManifest(w http.ResponseWriter, r *http.Request) {
	wsUUID, ok := parseUUIDOrBadRequest(w, h.resolveWorkspaceID(r), "workspace_id")
	if !ok {
		return
	}
	hidden, ok := h.requestHiddenProjects(w, r, uuidToString(wsUUID))
	if !ok {
		return
	}
	release, ok := acquireSearchIndexBootstrapSlot(r.Context())
	if !ok {
		if writeRequestCancellation(w, r, r.Context().Err()) {
			return
		}
		writeSearchIndexBusy(w)
		return
	}
	defer release()
	var row db.GetSearchIndexManifestRow
	err := h.runSearchIndexRead(r.Context(), func(q *db.Queries) error {
		var err error
		row, err = q.GetSearchIndexManifest(r.Context(), db.GetSearchIndexManifestParams{
			WorkspaceID:      wsUUID,
			HiddenProjectIds: hidden.Param(),
		})
		return err
	})
	if err != nil {
		h.writeSearchIndexError(w, r, "manifest", err)
		return
	}
	if writeQueryCancellation(w, r, r.Context().Err()) {
		return
	}
	writeJSON(w, http.StatusOK, SearchIndexManifestResponse{
		Cursor:       encodeSearchIndexCursor(searchIndexCursor{Since: row.Snapshot}),
		IssueCount:   row.IssueCount,
		CommentCount: row.CommentCount,
		ProjectCount: row.ProjectCount,
		TextBytes:    row.IssueBytes + row.CommentBytes + row.ProjectBytes,
	})
}

func (h *Handler) GetSearchIndexSnapshot(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	wsUUID, ok := parseUUIDOrBadRequest(w, h.resolveWorkspaceID(r), "workspace_id")
	if !ok {
		return
	}
	afterNumber := int64(0)
	if raw := r.URL.Query().Get("after_number"); raw != "" {
		v, err := strconv.ParseInt(raw, 10, 32)
		if err != nil || v < 0 {
			writeError(w, http.StatusBadRequest, "invalid after_number")
			return
		}
		afterNumber = v
	}
	limit := searchIndexSnapshotDefaultLimit
	if raw := r.URL.Query().Get("limit"); raw != "" {
		v, err := strconv.Atoi(raw)
		if err != nil || v <= 0 {
			writeError(w, http.StatusBadRequest, "invalid limit")
			return
		}
		limit = min(v, searchIndexSnapshotMaxLimit)
	}
	release, ok := acquireSearchIndexBootstrapSlot(ctx)
	if !ok {
		if writeRequestCancellation(w, r, r.Context().Err()) {
			return
		}
		writeSearchIndexBusy(w)
		return
	}
	defer release()

	var (
		issues   []db.Issue
		comments []db.ListSearchIndexCommentsByIssuesRow
		projects []db.Project
	)
	err := h.runSearchIndexRead(ctx, func(q *db.Queries) error {
		var err error
		issues, err = q.ListSearchIndexIssuesPage(ctx, db.ListSearchIndexIssuesPageParams{
			WorkspaceID: wsUUID,
			AfterNumber: int32(afterNumber),
			PageLimit:   int32(limit),
		})
		if err != nil {
			return err
		}
		if len(issues) > 0 {
			ids := make([]pgtype.UUID, len(issues))
			for i, is := range issues {
				ids[i] = is.ID
			}
			comments, err = q.ListSearchIndexCommentsByIssues(ctx, db.ListSearchIndexCommentsByIssuesParams{
				WorkspaceID: wsUUID,
				IssueIds:    ids,
			})
			if err != nil {
				return err
			}
		}
		if afterNumber == 0 {
			projects, err = q.ListSearchIndexProjects(ctx, wsUUID)
		}
		return err
	})
	if err != nil {
		h.writeSearchIndexError(w, r, "snapshot", err)
		return
	}
	hidden, ok := h.requestHiddenProjects(w, r, uuidToString(wsUUID))
	if !ok {
		return
	}
	// Paging advances over the unfiltered page so a hidden issue cannot end
	// the snapshot early or stall it.
	pageLen := len(issues)
	nextAfterNumber := int32(afterNumber)
	if pageLen > 0 {
		nextAfterNumber = issues[pageLen-1].Number
	}
	visibleIssues := filterVisibleIssues(hidden, issues)
	visibleIssueIDs := make(map[pgtype.UUID]bool, len(visibleIssues))
	for _, is := range visibleIssues {
		visibleIssueIDs[is.ID] = true
	}

	resp := SearchIndexSnapshotResponse{
		Issues:          h.searchIndexIssues(ctx, wsUUID, hidden, visibleIssues),
		Comments:        make([]SearchIndexComment, 0, len(comments)),
		Projects:        searchIndexProjects(visibleProjects(hidden, projects)),
		NextAfterNumber: nextAfterNumber,
		Done:            pageLen < limit,
	}
	for _, c := range comments {
		if !visibleIssueIDs[c.IssueID] {
			continue
		}
		resp.Comments = append(resp.Comments, searchIndexComment(c.ID, c.IssueID, c.Content, c.CreatedAt))
	}
	if writeQueryCancellation(w, r, r.Context().Err()) {
		return
	}
	writeJSON(w, http.StatusOK, resp)
}

func (h *Handler) ListSearchIndexChanges(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	wsUUID, ok := parseUUIDOrBadRequest(w, h.resolveWorkspaceID(r), "workspace_id")
	if !ok {
		return
	}
	var req struct {
		Cursor string `json:"cursor"`
		Limit  int    `json:"limit"`
	}
	if err := json.NewDecoder(io.LimitReader(r.Body, searchIndexCursorMaxBytes+1024)).Decode(&req); err != nil {
		if writeRequestCancellation(w, r, err) {
			return
		}
		writeError(w, http.StatusBadRequest, "invalid request body")
		return
	}
	cur, err := decodeSearchIndexCursor(req.Cursor)
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid cursor")
		return
	}
	limit := searchIndexChangesDefaultLimit
	if req.Limit > 0 {
		limit = min(req.Limit, searchIndexChangesMaxLimit)
	}

	var (
		pruned   bool
		target   = cur.Target
		changes  []db.ListSearchIndexChangesRow
		issues   []db.Issue
		comments []db.ListSearchIndexCommentsByIDsRow
		projects []db.Project
	)
	err = h.runSearchIndexRead(ctx, func(q *db.Queries) error {
		var err error
		if pruned, err = q.SearchIndexSinceIsPruned(ctx, cur.Since); err != nil || pruned {
			return err
		}
		if target == "" {
			if target, err = q.GetSearchIndexCurrentSnapshot(ctx); err != nil {
				return err
			}
		}
		params := db.ListSearchIndexChangesParams{
			WorkspaceID:    wsUUID,
			SinceSnapshot:  cur.Since,
			TargetSnapshot: target,
			AfterXid:       "0",
			AfterType:      "",
			AfterID:        pgtype.UUID{Valid: true},
			PageLimit:      int32(limit + 1),
		}
		if cur.Target != "" {
			params.AfterXid = cur.AfterXid
			params.AfterType = cur.AfterType
			params.AfterID, _ = parseUUIDStrict(cur.AfterID)
		}
		if changes, err = q.ListSearchIndexChanges(ctx, params); err != nil {
			return err
		}
		if len(changes) > limit {
			changes = changes[:limit]
		}
		var issueIDs, commentIDs, projectIDs []pgtype.UUID
		for _, c := range changes {
			switch c.EntityType {
			case "issue":
				issueIDs = append(issueIDs, c.EntityID)
			case "comment":
				commentIDs = append(commentIDs, c.EntityID)
			case "project":
				projectIDs = append(projectIDs, c.EntityID)
			}
		}
		if len(issueIDs) > 0 {
			if issues, err = q.ListSearchIndexIssuesByIDs(ctx, db.ListSearchIndexIssuesByIDsParams{WorkspaceID: wsUUID, Ids: issueIDs}); err != nil {
				return err
			}
		}
		if len(commentIDs) > 0 {
			if comments, err = q.ListSearchIndexCommentsByIDs(ctx, db.ListSearchIndexCommentsByIDsParams{WorkspaceID: wsUUID, Ids: commentIDs}); err != nil {
				return err
			}
		}
		if len(projectIDs) > 0 {
			if projects, err = q.ListSearchIndexProjectsByIDs(ctx, db.ListSearchIndexProjectsByIDsParams{WorkspaceID: wsUUID, Ids: projectIDs}); err != nil {
				return err
			}
		}
		return nil
	})
	if err != nil {
		var pgErr *pgconn.PgError
		if errors.As(err, &pgErr) && pgErr.Code == "22P02" {
			// A syntactically valid snapshot the server still rejects, e.g.
			// xmin greater than xmax.
			writeError(w, http.StatusBadRequest, "invalid cursor")
			return
		}
		h.writeSearchIndexError(w, r, "changes", err)
		return
	}
	if pruned {
		writeError(w, http.StatusGone, "search index cursor expired; rebuild the local index")
		return
	}
	// Entities in a project the caller cannot see are reported as deleted, so
	// a client that synced them before losing access drops its copy.
	hidden, ok := h.requestHiddenProjects(w, r, uuidToString(wsUUID))
	if !ok {
		return
	}
	if cur.AccessRules != searchIndexAccessRules && !hidden.Empty() {
		// The copy was built under other access rules and may hold a project
		// this caller cannot see any more; only a rebuild drops it. A caller
		// who sees every project has nothing to drop and just gets a current
		// cursor back.
		writeError(w, http.StatusGone, "search index access rules changed; rebuild the local index")
		return
	}
	if !hidden.Empty() {
		issues = filterVisibleIssues(hidden, issues)
		projects = visibleProjects(hidden, projects)
		visibleComments := comments[:0:0]
		issueProjects := map[pgtype.UUID]pgtype.UUID{}
		for _, c := range comments {
			projectID, seen := issueProjects[c.IssueID]
			if !seen {
				projectID, err = h.Queries.GetIssueProjectID(ctx, c.IssueID)
				if err != nil && !errors.Is(err, pgx.ErrNoRows) {
					h.writeSearchIndexError(w, r, "changes", err)
					return
				}
				issueProjects[c.IssueID] = projectID
			}
			if hidden.CanSeeProject(projectID) {
				visibleComments = append(visibleComments, c)
			}
		}
		comments = visibleComments
	}

	resp := SearchIndexChangesResponse{
		Issues:   h.searchIndexIssues(ctx, wsUUID, hidden, issues),
		Comments: []SearchIndexComment{},
		Projects: searchIndexProjects(projects),
		Deleted: SearchIndexDeleted{
			Issues:   []string{},
			Comments: []string{},
			Projects: []string{},
		},
	}
	liveIssues := make(map[pgtype.UUID]bool, len(issues))
	for _, is := range issues {
		liveIssues[is.ID] = true
	}
	liveProjects := make(map[pgtype.UUID]bool, len(projects))
	for _, p := range projects {
		liveProjects[p.ID] = true
	}
	liveComments := make(map[pgtype.UUID]bool, len(comments))
	for _, c := range comments {
		if c.DeletedAt.Valid {
			continue
		}
		liveComments[c.ID] = true
		resp.Comments = append(resp.Comments, searchIndexComment(c.ID, c.IssueID, c.Content, c.CreatedAt))
	}
	for _, c := range changes {
		switch c.EntityType {
		case "issue":
			if !liveIssues[c.EntityID] {
				resp.Deleted.Issues = append(resp.Deleted.Issues, uuidToString(c.EntityID))
			}
		case "comment":
			if !liveComments[c.EntityID] {
				resp.Deleted.Comments = append(resp.Deleted.Comments, uuidToString(c.EntityID))
			}
		case "project":
			if !liveProjects[c.EntityID] {
				resp.Deleted.Projects = append(resp.Deleted.Projects, uuidToString(c.EntityID))
			}
		}
	}

	if n := len(changes); n == limit {
		// A full page may have more behind it. Keep the target snapshot fixed
		// until the keyset runs dry, then promote it to the next Since.
		last := changes[n-1]
		resp.HasMore = true
		resp.Cursor = encodeSearchIndexCursor(searchIndexCursor{
			Since:     cur.Since,
			Target:    target,
			AfterXid:  last.ChangeXid,
			AfterType: last.EntityType,
			AfterID:   uuidToString(last.EntityID),
		})
	} else {
		resp.Cursor = encodeSearchIndexCursor(searchIndexCursor{Since: target})
	}
	if writeQueryCancellation(w, r, r.Context().Err()) {
		return
	}
	writeJSON(w, http.StatusOK, resp)
}

func (h *Handler) ListIssueTableGroups(w http.ResponseWriter, r *http.Request) {
	if h.DB == nil {
		writeError(w, http.StatusInternalServerError, "database is unavailable")
		return
	}
	var request issueTableGroupsRequest
	if !decodeIssueTableJSON(w, r, &request) {
		return
	}
	r, cancel := withIssueTableQueryTimeout(r)
	defer cancel()
	snapshot, tx, err := h.beginIssueTableSnapshot(r.Context())
	if err != nil {
		slog.Warn("ListIssueTableGroups snapshot failed", append(logger.RequestAttrs(r), "error", err)...)
		writeIssueTableQueryFailure(w, r, "failed to start table query")
		return
	}
	committed := false
	defer func() {
		if !committed {
			_ = tx.Rollback(context.Background())
		}
	}()
	h = snapshot
	limit, cursor, ok := normalizeIssueTablePage(w, request.Page)
	if !ok {
		return
	}
	compiled, ok := h.compileIssueTableQuery(w, r, request.Query)
	if !ok {
		return
	}
	group, ok := h.resolveIssueTableGroup(w, r, compiled.workspaceID, request.Group, false)
	if !ok {
		return
	}
	groupIdentity := issueTableGroupIdentity(request.Group)
	if !issueTableCursorMatches(w, cursor, compiled.fingerprint, &groupIdentity, nil) {
		return
	}

	args := append([]any(nil), compiled.args...)
	addArg := func(value any) string {
		args = append(args, value)
		return "$" + strconv.Itoa(len(args))
	}
	groupExpr := group.expression(addArg)
	groupSortExpr := group.sortExpression(compiled.parentVisible())
	orderExpr := group.orderExpression(addArg)
	contextExpr := group.contextExpression(addArg, h.getIssuePrefix(r.Context(), compiled.workspaceID), compiled.parentVisible())
	cursorPredicate := "TRUE"
	if cursor != nil {
		if cursor.GroupOrder == nil || cursor.GroupSortKey == nil || cursor.GroupCursorKey == nil {
			writeError(w, http.StatusBadRequest, "invalid cursor")
			return
		}
		orderRef := addArg(*cursor.GroupOrder)
		sortRef := addArg(*cursor.GroupSortKey)
		keyRef := addArg(*cursor.GroupCursorKey)
		cursorPredicate = fmt.Sprintf(`(group_order > %[1]s::int OR (
  group_order = %[1]s::int AND (
    group_sort > %[2]s::text OR (group_sort = %[2]s::text AND group_value > %[3]s::text)
  )
))`, orderRef, sortRef, keyRef)
	}
	limitRef := addArg(limit + 1)
	groupedCTE := fmt.Sprintf(`grouped AS (
  SELECT %s AS group_value, COUNT(*)::bigint AS issue_count,
         COUNT(*)::bigint AS visible_count, '{}'::jsonb AS secondary_counts
  FROM issue i
  WHERE %s
  GROUP BY 1
)`, groupExpr, compiled.where)
	if request.Group.IncludeEmpty && group.kind == "property" {
		expectedValues := []string{"unset:"}
		if group.propertyType == "select" {
			expectedValues = append(append([]string(nil), group.activeOptionOrder...), "unset:")
		} else {
			expectedValues = []string{"value:false", "value:true", "unset:"}
		}
		expectedRef := addArg(expectedValues)
		groupedCTE = fmt.Sprintf(`actual AS (
  SELECT %s AS group_value, COUNT(*)::bigint AS issue_count
  FROM issue i
  WHERE %s
  GROUP BY 1
), expected AS (
  SELECT unnest(%s::text[]) AS group_value
), grouped AS (
  SELECT e.group_value, COALESCE(a.issue_count, 0)::bigint AS issue_count,
         COALESCE(a.issue_count, 0)::bigint AS visible_count,
         '{}'::jsonb AS secondary_counts
  FROM expected e
  LEFT JOIN actual a USING (group_value)
  UNION ALL
  SELECT a.group_value, a.issue_count, a.issue_count AS visible_count,
         '{}'::jsonb AS secondary_counts
  FROM actual a
  WHERE NOT (a.group_value = ANY(%s::text[]))
)`, groupExpr, compiled.where, expectedRef, expectedRef)
	}
	if group.kind == "compound" {
		// The secondary axis is either the status key itself or the CATEGORY it
		// behaves as. In the category case a custom status counts into the cell
		// of the column it renders in, never a cell of its own. (MUL-6243)
		secondaryExpr := "i.status"
		if group.secondaryCategory {
			secondaryExpr = group.categoryExpression(addArg)
		}
		groupedCTE = fmt.Sprintf(`cells AS (
  SELECT %s AS group_value, %s AS secondary_value, COUNT(*)::bigint AS cell_count
  FROM issue i
  WHERE %s
  GROUP BY 1, 2
), grouped AS (
  SELECT group_value,
         SUM(cell_count)::bigint AS issue_count,
         SUM(cell_count)::bigint AS visible_count,
         jsonb_object_agg(secondary_value, cell_count)::jsonb AS secondary_counts
  FROM cells
  GROUP BY group_value
)`, groupExpr, secondaryExpr, compiled.where)
		if group.secondaryFiltered {
			visibleRef := addArg(group.secondaryValues)
			// promoted_parents matches raw `child.status`, so a category axis has
			// to expand back to concrete keys there; the cell filters compare
			// against secondary_value, which is already a category.
			visibleKeysRef := visibleRef
			if group.secondaryCategory && group.primary != nil && group.primary.kind == "parent" {
				expanded := make([]string, 0, len(group.secondaryValues))
				for _, category := range group.secondaryValues {
					expanded = append(expanded, group.categoryKeysFor(category)...)
				}
				visibleKeysRef = addArg(expanded)
			}
			headerPredicate := "TRUE"
			promotedParentsCTE := ""
			if group.primary != nil && group.primary.kind == "parent" {
				headerPredicate = `NOT (
    i.parent_issue_id IS NULL AND
    EXISTS (SELECT 1 FROM promoted_parents p WHERE p.id = i.id)
  )`
				promotedParentsCTE = fmt.Sprintf(`, promoted_parents AS (
  SELECT DISTINCT child.parent_issue_id AS id
  FROM membership child
  WHERE child.parent_issue_id IS NOT NULL
    AND child.status = ANY(%s::text[])
)`, visibleKeysRef)
			}
			groupedCTE = fmt.Sprintf(`membership AS NOT MATERIALIZED (
  SELECT i.*
  FROM issue i
  WHERE %s
)%s, cells AS (
  SELECT %s AS group_value, %s AS secondary_value,
         COUNT(*) FILTER (WHERE %s)::bigint AS cell_count
  FROM membership i
  GROUP BY 1, 2
), grouped AS (
  SELECT group_value,
         SUM(cell_count)::bigint AS issue_count,
         COALESCE(
           SUM(cell_count) FILTER (WHERE secondary_value = ANY(%s::text[])),
           0
         )::bigint AS visible_count,
         jsonb_object_agg(secondary_value, cell_count)::jsonb AS secondary_counts
  FROM cells
  GROUP BY group_value
  HAVING COALESCE(
    SUM(cell_count) FILTER (WHERE secondary_value = ANY(%s::text[])),
    0
  ) > 0
)`, compiled.where, promotedParentsCTE, groupExpr, secondaryExpr, headerPredicate, visibleRef, visibleRef)
		}
	}
	query := fmt.Sprintf(`WITH %s, sorted AS (
	  SELECT group_value, issue_count, visible_count, secondary_counts, (%s)::text AS group_sort,
	         (%s)::jsonb AS group_context
	  FROM grouped
	), ranked AS (
	  SELECT group_value, issue_count, visible_count, secondary_counts, group_sort, group_context, (%s)::int AS group_order,
	         SUM(visible_count) OVER ()::bigint AS total
	  FROM sorted
	)
	SELECT group_value, issue_count, secondary_counts, group_sort, group_context, group_order, total
	FROM ranked
	WHERE %s
	ORDER BY group_order ASC, group_sort ASC, group_value ASC
	LIMIT %s`, groupedCTE, groupSortExpr, contextExpr, orderExpr, cursorPredicate, limitRef)

	rows, err := h.DB.Query(r.Context(), query, args...)
	if err != nil {
		slog.Warn("ListIssueTableGroups query failed", append(logger.RequestAttrs(r), "error", err)...)
		writeIssueTableQueryFailure(w, r, "failed to list table groups")
		return
	}
	defer rows.Close()

	groups := make([]issueTableGroupDescriptorResponse, 0, limit+1)
	orders := make([]int, 0, limit+1)
	sortValues := make([]string, 0, limit+1)
	values := make([]string, 0, limit+1)
	var total int64
	for rows.Next() {
		var raw string
		var count int64
		var secondaryJSON []byte
		var sortValue string
		var contextJSON []byte
		var order int
		if err := rows.Scan(&raw, &count, &secondaryJSON, &sortValue, &contextJSON, &order, &total); err != nil {
			writeIssueTableQueryFailure(w, r, "failed to list table groups")
			return
		}
		var context issueTableGroupContext
		if len(contextJSON) > 0 {
			if err := json.Unmarshal(contextJSON, &context); err != nil {
				writeIssueTableQueryFailure(w, r, "failed to resolve table group")
				return
			}
		}
		secondaryCounts := map[string]int64{}
		if len(secondaryJSON) > 0 {
			if err := json.Unmarshal(secondaryJSON, &secondaryCounts); err != nil {
				writeIssueTableQueryFailure(w, r, "failed to resolve table group")
				return
			}
		}
		descriptor, err := group.descriptor(raw, count, context, secondaryCounts)
		if err != nil {
			slog.Warn("ListIssueTableGroups descriptor failed", append(logger.RequestAttrs(r), "error", err)...)
			writeError(w, http.StatusInternalServerError, "failed to resolve table group")
			return
		}
		groups = append(groups, descriptor)
		orders = append(orders, order)
		sortValues = append(sortValues, sortValue)
		values = append(values, raw)
	}
	if err := rows.Err(); err != nil {
		writeIssueTableQueryFailure(w, r, "failed to list table groups")
		return
	}
	rows.Close()

	var nextCursor *string
	if len(groups) > limit {
		groups = groups[:limit]
		lastOrder := orders[limit-1]
		lastSort := sortValues[limit-1]
		lastKey := values[limit-1]
		nextCursor = encodeIssueTableCursor(issueTableCursor{
			Version:          1,
			QueryFingerprint: compiled.fingerprint,
			GroupKey:         &groupIdentity,
			GroupOrder:       &lastOrder,
			GroupSortKey:     &lastSort,
			GroupCursorKey:   &lastKey,
		})
	}
	response := issueTableGroupsResponse{
		QueryFingerprint: compiled.fingerprint,
		Total:            total,
		Groups:           groups,
		NextCursor:       nextCursor,
	}
	if err := tx.Commit(r.Context()); err != nil {
		slog.Warn("ListIssueTableGroups snapshot commit failed", append(logger.RequestAttrs(r), "error", err)...)
		writeIssueTableQueryFailure(w, r, "failed to finish table query")
		return
	}
	committed = true
	writeJSON(w, http.StatusOK, response)
}

