func (h *Handler) CancelTask(w http.ResponseWriter, r *http.Request) {
	issueID := chi.URLParam(r, "id")
	issue, ok := h.loadIssueForUser(w, r, issueID)
	if !ok {
		return
	}

	taskID := chi.URLParam(r, "taskId")
	existing, err := h.Queries.GetAgentTask(r.Context(), parseUUID(taskID))
	if err != nil || uuidToString(existing.IssueID) != uuidToString(issue.ID) {
		writeError(w, http.StatusNotFound, "task not found")
		return
	}

	workspaceID := uuidToString(issue.WorkspaceID)
	actorType, actorID := h.resolveActor(r, requestUserID(r), workspaceID)
	task, err := h.TaskService.CancelTaskByUser(
		r.Context(),
		existing.ID,
		h.taskCancellationActor(r.Context(), actorType, actorID),
	)
	if err != nil {
		slog.Warn("cancel task failed", "task_id", taskID, "error", err)
		writeError(w, http.StatusBadRequest, err.Error())
		return
	}

	slog.Info("task cancelled by user", "task_id", taskID, "issue_id", uuidToString(task.IssueID))
	resp := taskToResponse(*task, workspaceID)
	// Keep this issue-scoped surface consistent with the list endpoints so a
	// cancelled row keeps its resolved "on behalf of" name in the UI.
	h.hydrateTaskAttributions(r.Context(), []*TaskAttribution{resp.Attribution})
	writeJSON(w, http.StatusOK, resp)
}

func (s *TaskService) CancelTask(ctx context.Context, taskID pgtype.UUID) (*db.AgentTaskQueue, error) {
	// Callers of this wrapper are automatic non-chat repair/daemon paths, so
	// finalizeCancelledChatMessage returns before the gate is even read.
	// Should a chat task ever reach here, there is no client waiting on a
	// synchronous restore anyway, and the durable path is the only one that can
	// hand the prompt back at all.
	result, err := s.CancelTaskWithResult(ctx, taskID, CancelTaskOptions{ClientSupportsDraftRestore: true})
	if err != nil {
		return nil, err
	}
	return &result.Task, nil
}

func (h *Handler) CreateTaskSupplement(w http.ResponseWriter, r *http.Request) {
	issue, task, authorID, ok := h.loadTaskSupplementTarget(w, r)
	if !ok {
		return
	}
	var req createTaskSupplementRequest
	if err := json.NewDecoder(http.MaxBytesReader(w, r.Body, 8*maxCommentContentBytes)).Decode(&req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid request body")
		return
	}
	req.Content = sanitizeNullBytes(req.Content)
	if len(req.Content) > maxCommentContentBytes {
		writeError(w, http.StatusBadRequest, "content is too long")
		return
	}
	if strings.TrimSpace(req.Content) == "" {
		writeError(w, http.StatusBadRequest, "content is required")
		return
	}
	requestID, ok := parseUUIDOrBadRequest(w, req.ClientRequestID, "client_request_id")
	if !ok {
		return
	}
	lookup := db.GetTaskSupplementByRequestParams{
		TaskID: task.ID, WorkspaceID: issue.WorkspaceID, AuthorID: authorID, ClientRequestID: requestID,
	}
	if existing, err := h.Queries.GetTaskSupplementByRequest(r.Context(), lookup); err == nil {
		h.notifyTaskSupplementAvailable(task)
		h.writeExistingTaskSupplement(w, r, existing)
		return
	} else if !errors.Is(err, pgx.ErrNoRows) {
		writeError(w, http.StatusInternalServerError, "failed to check additional message")
		return
	}
	if task.Status != "running" {
		writeErrorCode(w, http.StatusConflict, "task_supplement_turn_ended", "this run has ended")
		return
	}
	capability, err := h.Queries.GetTaskSupplementCapability(r.Context(), task.ID)
	if errors.Is(err, pgx.ErrNoRows) || capability.Capability != protocol.DaemonCapabilityTaskSupplementV1 {
		writeErrorCode(w, http.StatusPreconditionFailed, "task_supplement_unsupported", "this run does not support additional messages")
		return
	}
	if err != nil {
		writeError(w, http.StatusInternalServerError, "failed to check additional-message support")
		return
	}

	created, err := h.Queries.CreateTaskSupplement(r.Context(), db.CreateTaskSupplementParams{
		TaskID: task.ID, IssueID: issue.ID, WorkspaceID: issue.WorkspaceID,
		AuthorID: authorID, Content: req.Content, ClientRequestID: requestID,
	})
	if isUniqueViolation(err) {
		if existing, loadErr := h.Queries.GetTaskSupplementByRequest(r.Context(), lookup); loadErr == nil {
			h.notifyTaskSupplementAvailable(task)
			h.writeExistingTaskSupplement(w, r, existing)
			return
		} else if !errors.Is(loadErr, pgx.ErrNoRows) {
			writeError(w, http.StatusInternalServerError, "failed to check additional message")
			return
		}
		writeError(w, http.StatusConflict, "client_request_id is already in use")
		return
	}
	if errors.Is(err, pgx.ErrNoRows) {
		writeErrorCode(w, http.StatusConflict, "task_supplement_turn_ended", "this run has ended")
		return
	}
	if err != nil {
		writeError(w, http.StatusInternalServerError, "failed to create additional message")
		return
	}
	comment := db.Comment{
		ID: created.ID, IssueID: created.IssueID, AuthorType: created.AuthorType,
		AuthorID: created.AuthorID, Content: created.Content, Type: created.Type,
		CreatedAt: created.CreatedAt, UpdatedAt: created.UpdatedAt, ParentID: created.ParentID,
		WorkspaceID: created.WorkspaceID, ResolvedAt: created.ResolvedAt,
		ResolvedByType: created.ResolvedByType, ResolvedByID: created.ResolvedByID,
		SourceTaskID: created.SourceTaskID, QuickActionID: created.QuickActionID,
		ViaPluginID: created.ViaPluginID, Revision: created.Revision,
		RecoverySettledAt: created.RecoverySettledAt, DeletedAt: created.DeletedAt,
	}
	resp := commentToResponse(comment, nil, nil)
	resp.IssueRevision = created.IssueRevision
	applyCommentSupplements(&resp, []CommentSupplementResponse{{
		TaskID:        uuidToString(created.SupplementTaskID),
		AgentID:       uuidToString(task.AgentID),
		Status:        created.SupplementStatus,
		FailureReason: textToPtr(created.SupplementFailureReason),
		DeliveredAt:   timestampToPtr(created.SupplementDeliveredAt),
	}})
	h.publish(protocol.EventCommentCreated, uuidToString(issue.WorkspaceID), "member", uuidToString(authorID), map[string]any{
		"comment": resp, "issue_title": issue.Title, "issue_revision": created.IssueRevision,
	})
	h.notifyTaskSupplementAvailable(task)
	writeJSON(w, http.StatusCreated, resp)
}

func (h *Handler) RetryTaskSupplement(w http.ResponseWriter, r *http.Request) {
	issue, task, _, ok := h.loadTaskSupplementTarget(w, r)
	if !ok {
		return
	}
	commentID, ok := parseUUIDOrBadRequest(w, chi.URLParam(r, "commentId"), "comment id")
	if !ok {
		return
	}
	row, err := h.Queries.RetryTaskSupplement(r.Context(), db.RetryTaskSupplementParams{
		CommentID: commentID, WorkspaceID: issue.WorkspaceID, TaskID: task.ID, IssueID: issue.ID,
	})
	if errors.Is(err, pgx.ErrNoRows) {
		existing, loadErr := h.Queries.GetTaskSupplementForRun(r.Context(), db.GetTaskSupplementForRunParams{
			CommentID: commentID, TaskID: task.ID, WorkspaceID: issue.WorkspaceID,
		})
		if loadErr == nil && existing.Status == "pending" {
			row = existing // duplicate retry is an idempotent success
			err = nil
		}
	}
	if errors.Is(err, pgx.ErrNoRows) {
		writeErrorCode(w, http.StatusConflict, "task_supplement_not_retryable", "this message cannot be retried")
		return
	}
	if err != nil {
		writeError(w, http.StatusInternalServerError, "failed to retry additional message")
		return
	}
	h.publishTaskSupplementUpdate(r, row)
	h.notifyTaskSupplementAvailable(task)
	writeJSON(w, http.StatusOK, supplementReceipt(row))
}

func (h *Handler) RerunIssue(w http.ResponseWriter, r *http.Request) {
	id := chi.URLParam(r, "id")
	issue, ok := h.loadIssueForUser(w, r, id)
	if !ok {
		return
	}

	// Body is optional. A zero-length body or `{}` keeps the legacy
	// assignee-driven rerun behaviour the CLI relies on.
	var req RerunIssueRequest
	if r.ContentLength != 0 {
		if err := json.NewDecoder(r.Body).Decode(&req); err != nil && err != io.EOF {
			writeError(w, http.StatusBadRequest, "invalid request body")
			return
		}
	}

	var sourceTaskID pgtype.UUID
	if req.TaskID != "" {
		parsed, ok := parseUUIDOrBadRequest(w, req.TaskID, "task_id")
		if !ok {
			return
		}
		sourceTaskID = parsed
	}
	h.rerunIssue(w, r, issue, sourceTaskID, false)
}

func (s *TaskService) RerunIssue(ctx context.Context, issueID pgtype.UUID, sourceTaskID pgtype.UUID, triggerCommentID pgtype.UUID, actorUserID pgtype.UUID, fresh bool, canInvoke func(agent db.Agent) bool) (*db.AgentTaskQueue, error) {
	issue, err := s.Queries.GetIssue(ctx, issueID)
	if err != nil {
		return nil, fmt.Errorf("load issue: %w", err)
	}
	// In Triage a rerun follows its source, and the decision is made here —
	// before anything is cancelled. The queue door would refuse a derived rerun
	// anyway, but this path cancels the prior run on its way there, so a late
	// refusal would leave the issue with one fewer run and no new one.
	//
	// Naming no source means "run the assignee again", which is the derived
	// executor Triage does not have. Naming a discussion run is repeating a
	// conversation the member started, so it is allowed; naming the triage run
	// itself is refused further down, with its own reason.
	rerunOrigin := OriginDerived
	if sourceTaskID.Valid {
		rerunOrigin = OriginNamed
	} else if issue.TriageState.Valid {
		return nil, ErrIssueInTriage
	}

	// Determine the target agent for the rerun.
	var (
		agentID             pgtype.UUID
		isLeader            bool
		squadID             pgtype.UUID
		coalescedCommentIDs []pgtype.UUID
	)
	if sourceTaskID.Valid {
		sourceTask, err := s.Queries.GetAgentTask(ctx, sourceTaskID)
		if err != nil {
			return nil, fmt.Errorf("load source task: %w", err)
		}
		if !sourceTask.IssueID.Valid || util.UUIDToString(sourceTask.IssueID) != util.UUIDToString(issueID) {
			return nil, fmt.Errorf("source task does not belong to this issue")
		}
		// A triage run is not an execution run to repeat (MUL-7189 §5.6). This
		// is the only path that names a source task directly, and it would
		// otherwise outlive Triage: after accept the issue is runnable again, so
		// nothing above stops a rerun pointed at the triage task — which resumes
		// its session through rerun_of_task_id (the claim handler reads the
		// named source, not GetLastTaskSession) and targets the triager rather
		// than the issue's assignee. Redoing triage is re-triage, a different
		// action on a different status.
		if IsTriageTask(sourceTask) {
			return nil, ErrRerunSourceIsTriage
		}
		agentID = sourceTask.AgentID
		isLeader = sourceTask.IsLeaderTask
		// Carry the source task's squad provenance so a rerun of a leader
		// task still injects the squad briefing at claim time (see migration
		// 127 / daemon claim handler).
		squadID = sourceTask.SquadID
		// Inherit trigger provenance so a per-row rerun of a comment- or
		// mention-triggered task stays a comment-triggered task. Without
		// this the daemon's buildCommentPrompt path is skipped (it keys on
		// TriggerCommentID) and the rerun degrades into a generic issue
		// run that has lost the original comment context. Only override
		// when the caller didn't pass one explicitly.
		if !triggerCommentID.Valid {
			coalescedCommentIDs = append([]pgtype.UUID{}, sourceTask.CoalescedCommentIds...)
			sourceTriggerLive := sourceTask.TriggerCommentID.Valid
			if sourceTriggerLive {
				// A trigger deleted while it had replies keeps its row as a
				// tombstone instead of clearing trigger_comment_id; repair the
				// plan exactly as for a removed trigger.
				trigger, err := s.Queries.GetComment(ctx, sourceTask.TriggerCommentID)
				if err != nil && !errors.Is(err, pgx.ErrNoRows) {
					return nil, fmt.Errorf("load source trigger comment: %w", err)
				}
				sourceTriggerLive = err == nil && !trigger.DeletedAt.Valid
			}
			if sourceTriggerLive {
				triggerCommentID = sourceTask.TriggerCommentID
			} else if len(coalescedCommentIDs) > 0 {
				triggerCommentID, coalescedCommentIDs, err = s.promoteNewestSurvivingComment(ctx, coalescedCommentIDs)
				if err != nil {
					return nil, fmt.Errorf("repair source comment plan: %w", err)
				}
			}
		}
	} else {
		switch {
		case issue.AssigneeType.String == "agent" && issue.AssigneeID.Valid:
			agentID = issue.AssigneeID
		case issue.AssigneeType.String == "squad" && issue.AssigneeID.Valid:
			squad, err := s.Queries.GetSquad(ctx, issue.AssigneeID)
			if err != nil {
				return nil, fmt.Errorf("issue is assigned to a squad but squad not found")
			}
			agentID = squad.LeaderID
			isLeader = true
			squadID = issue.AssigneeID
		default:
			return nil, fmt.Errorf("issue is not assigned to an agent or squad")
		}
	}

	// Re-validate invoke permission on the RESOLVED target before mutating
	// anything (MUL-4525). For a task_id rerun this gates the historical agent,
	// so a since-reassigned issue can't be used to re-fire a private agent the
	// operator may only view. A block fails closed: no prior task is cancelled,
	// no new task is created.
	if canInvoke != nil {
		targetAgent, err := s.Queries.GetAgent(ctx, agentID)
		if err != nil {
			return nil, fmt.Errorf("load target agent: %w", err)
		}
		if !canInvoke(targetAgent) {
			return nil, ErrRerunInvokeNotAllowed
		}
	}

	// Clear only the tasks that have not begun executing. Those are the rows the
	// fresh enqueue would collide with under
	// idx_one_pending_task_per_issue_agent_v2, and replacing them costs no work
	// while keeping the new run attributed to the rerunning member (MUL-4302 §5)
	// rather than inheriting whoever created the pending row.
	//
	// A running / waiting_local_directory task is deliberately left alone: an
	// agent is executing in it. Neither status appears in that unique index, so
	// the enqueue below inserts a queued row BEHIND the active one, and
	// ClaimAgentTask's per-(issue, agent) serialization holds it there until the
	// active run reaches a terminal state. Rerun used to cancel these too, so
	// asking an agent for another pass silently killed the pass it was still
	// working on; interrupting an in-flight run is what CancelTask /
	// `workpal issue cancel-task` is for.
	clearPendingSlot := func() int {
		var cancelled []db.AgentTaskQueue
		// Atomic with the cancel: a pending coordinator task can already hold a
		// recovery receipt, and nothing downstream could repair a settlement
		// that failed after this committed.
		cerr := s.runInTx(ctx, func(qtx *db.Queries) error {
			var err error
			cancelled, err = qtx.CancelPendingTasksByIssueAndAgentInThread(ctx, db.CancelPendingTasksByIssueAndAgentInThreadParams{
				ThreadCommentID: triggerCommentID,
				IssueID:         issueID,
				AgentID:         agentID,
			})
			if err != nil {
				return err
			}
			return SettleTerminalTaskState(ctx, qtx, cancelled...)
		})
		if cerr != nil {
			slog.Warn("rerun: cancel pending tasks failed",
				"issue_id", util.UUIDToString(issueID),
				"agent_id", util.UUIDToString(agentID),
				"error", cerr,
			)
		}
		for _, t := range cancelled {
			s.captureTaskCancelled(ctx, t)
			s.ReconcileAgentStatus(ctx, t.AgentID)
			s.broadcastTaskEvent(ctx, protocol.EventTaskCancelled, t)
		}
		return len(cancelled)
	}
	cancelledCount := clearPendingSlot()

	// A manual rerun is a NEW direct_human trigger attributed to the rerunning
	// member, not the original run's human (MUL-4302 §5); actorUserID carries them.
	// sourceTaskID is the rerun lineage: it rides the CreateAgentTask insert
	// (rerun_of_task_id) so the queued event / daemon claim never sees a NULL
	// lineage, and it stays distinct from system-retry's retry_of_task_id (§5).
	task, err := s.enqueueRerunTask(ctx, issue, agentID, triggerCommentID, coalescedCommentIDs, isLeader, squadID, actorUserID, sourceTaskID, rerunOrigin, fresh)
	if pendingSlotTakenErr(err) {
		// The clear above and this enqueue are separate commits, so a system
		// retry created by a concurrent FailTask can take the pending slot in
		// between. CreateRetryTask yields the slot when it is already occupied,
		// but it cannot yield to a row that does not exist yet, so a retry
		// committing inside this window gets there first. Clear once more and
		// retry: the deliberate human action is the one that should hold the
		// slot. Bounded to a single extra attempt — a second collision would mean
		// something is enqueueing in a loop, which is worth surfacing rather than
		// spinning on.
		slog.Info("issue rerun: pending slot taken concurrently, reclaiming",
			"issue_id", util.UUIDToString(issueID),
			"agent_id", util.UUIDToString(agentID),
		)
		cancelledCount += clearPendingSlot()
		task, err = s.enqueueRerunTask(ctx, issue, agentID, triggerCommentID, coalescedCommentIDs, isLeader, squadID, actorUserID, sourceTaskID, rerunOrigin, fresh)
	}
	if err != nil {
		return nil, err
	}
	slog.Info("issue rerun enqueued",
		"task_id", util.UUIDToString(task.ID),
		"issue_id", util.UUIDToString(issueID),
		"agent_id", util.UUIDToString(agentID),
		"source_task_id", util.UUIDToString(sourceTaskID),
		"is_leader", isLeader,
		"cancelled_pending", cancelledCount,
	)
	return &task, nil
}

func (h *Handler) RunQuickAction(w http.ResponseWriter, r *http.Request) {
	issue, ok := h.loadIssueForUser(w, r, chi.URLParam(r, "id"))
	if !ok {
		return
	}
	userID, ok := requireUserID(w, r)
	if !ok {
		return
	}
	workspaceID := uuidToString(issue.WorkspaceID)
	idUUID, ok := parseUUIDOrBadRequest(w, chi.URLParam(r, "quickActionId"), "quick action id")
	if !ok {
		return
	}
	qa, ok := h.loadReachableQuickAction(w, r, idUUID, issue.WorkspaceID, userID)
	if !ok {
		return
	}
	if qa.Status != "active" {
		writeError(w, http.StatusBadRequest, "quick action is archived")
		return
	}
	// A quick action carries its OWN configured target, so under the "derived vs
	// named" rule it could be let through. It is refused in the first phase for a
	// product reason rather than a rule one: it is an instruction to go and DO
	// the action, not an invitation to talk, and Triage is where nobody has
	// agreed the work should be done yet. Opening it later is deleting this if.
	//
	// Before the comment is written, not after: a targeted action is a comment
	// AND a run (MUL-7189 §2.3). Targetless actions are ordinary messages, so
	// they can be posted in triage without dispatching work.
	if qa.AssigneeType != "" && issue.TriageState.Valid {
		h.writeDispatchBlocked(w, http.StatusForbidden, ReasonIssueInTriage)
		return
	}

	target := h.resolveQuickActionTarget(r.Context(), qa)
	if !target.Found {
		h.writeDispatchBlocked(w, http.StatusConflict, ReasonTargetUnavailable)
		return
	}

	actorType, actorID := h.resolveActor(r, userID, workspaceID)
	originatorUserID := h.invokeOriginatorFromRequest(r, actorType, actorID)
	// The single permission gate. Issue visibility never implies the right to
	// trigger someone's private agent.
	if qa.AssigneeType != "" && !h.canInvokeAgent(r.Context(), target.Agent, actorType, actorID, originatorUserID, workspaceID) {
		h.writeDispatchBlocked(w, http.StatusForbidden, ReasonInvocationNotAllowed)
		return
	}

	body := sanitizeNullBytes(buildQuickActionBody(qa, target))

	created, err := h.Queries.CreateComment(r.Context(), db.CreateCommentParams{
		ID:          dbid.NewV7(),
		IssueID:     issue.ID,
		WorkspaceID: issue.WorkspaceID,
		AuthorType:  actorType,
		AuthorID:    parseUUID(actorID),
		Content:     body,
		// Deliberately an ordinary comment. The collapsed card is driven by
		// quick_action_id, which no client can set — `type` is client-supplied
		// on the generic comment endpoint, so a dedicated type value would be
		// forgeable and would also have cost a CHECK rebuild on a hot table.
		Type:          "comment",
		QuickActionID: qa.ID,
	})
	if err != nil {
		slog.Warn("quick action comment create failed", append(logger.RequestAttrs(r), "error", err, "quick_action_id", uuidToString(qa.ID))...)
		writeError(w, http.StatusInternalServerError, "failed to run quick action")
		return
	}
	comment := created.Comment()

	resp := commentToResponse(comment, nil, nil)
	resp.IssueRevision = created.IssueRevision
	h.publish(protocol.EventCommentCreated, workspaceID, actorType, actorID, map[string]any{
		"comment":             resp,
		"issue_title":         issue.Title,
		"issue_assignee_type": textToPtr(issue.AssigneeType),
		"issue_assignee_id":   uuidToPtr(issue.AssigneeID),
		"issue_status":        issue.Status,
		"issue_revision":      created.IssueRevision,
	})

	resp.TriggerOutcomes = h.triggerTasksForComment(r.Context(), issue, comment, nil, actorType, actorID, originatorUserID, nil, commentSteerRequest{})

	// Usage telemetry is best-effort and deliberately outside the run's
	// success path: a failed counter must never cost the user the run.
	if err := h.Queries.TouchQuickActionUsage(r.Context(), db.TouchQuickActionUsageParams{ID: qa.ID, WorkspaceID: issue.WorkspaceID}); err != nil {
		slog.Debug("quick action usage touch failed", "quick_action_id", uuidToString(qa.ID), "error", err)
	}

	slog.Info("quick action run", append(logger.RequestAttrs(r),
		"quick_action_id", uuidToString(qa.ID),
		"issue_id", uuidToString(issue.ID),
		"comment_id", uuidToString(comment.ID),
	)...)
	writeJSON(w, http.StatusCreated, resp)
}

func (h *Handler) RenderQuickAction(w http.ResponseWriter, r *http.Request) {
	issue, ok := h.loadIssueForUser(w, r, chi.URLParam(r, "id"))
	if !ok {
		return
	}
	userID, ok := requireUserID(w, r)
	if !ok {
		return
	}
	workspaceID := uuidToString(issue.WorkspaceID)
	idUUID, ok := parseUUIDOrBadRequest(w, chi.URLParam(r, "quickActionId"), "quick action id")
	if !ok {
		return
	}
	qa, ok := h.loadReachableQuickAction(w, r, idUUID, issue.WorkspaceID, userID)
	if !ok {
		return
	}

	target := h.resolveQuickActionTarget(r.Context(), qa)
	if !target.Found {
		h.writeDispatchBlocked(w, http.StatusConflict, ReasonTargetUnavailable)
		return
	}
	actorType, actorID := h.resolveActor(r, userID, workspaceID)
	// Same gate as the run path: the preview would otherwise hand a user the
	// exact text needed to trigger an agent they may not invoke.
	if qa.AssigneeType != "" && !h.canInvokeAgent(r.Context(), target.Agent, actorType, actorID, h.invokeOriginatorFromRequest(r, actorType, actorID), workspaceID) {
		h.writeDispatchBlocked(w, http.StatusForbidden, ReasonInvocationNotAllowed)
		return
	}

	writeJSON(w, http.StatusOK, map[string]string{
		"content": buildQuickActionBody(qa, target),
	})
}

func (h *Handler) ListTasksByIssue(w http.ResponseWriter, r *http.Request) {
	issueID := chi.URLParam(r, "id")
	issue, ok := h.loadIssueForUser(w, r, issueID)
	if !ok {
		return
	}

	view := r.URL.Query().Get("view")
	if view != "" && view != "timeline" {
		writeError(w, http.StatusBadRequest, "view must be 'timeline' when specified")
		return
	}

	scope := r.URL.Query().Get("scope")
	if scope != "" && scope != "issue" && scope != "family" && scope != "subtree" {
		writeError(w, http.StatusBadRequest, "scope must be 'issue', 'family', or 'subtree'")
		return
	}
	// Parse rather than compare. `active=tru` answering with the full history
	// under a 200 is the same silent-downgrade failure the unknown-scope check
	// above rejects: the caller asked who is here NOW and would be handed every
	// run that ever finished, which reads as "nobody is here" only after it has
	// paid for the whole log. Same shape as the comment-list boolean params.
	activeOnly := false
	if activeStr := r.URL.Query().Get("active"); activeStr != "" {
		switch activeStr {
		case "true":
			activeOnly = true
		case "false":
		default:
			writeError(w, http.StatusBadRequest, "invalid active parameter; expected boolean")
			return
		}
	}

	workspaceID := uuidToString(issue.WorkspaceID)

	if scope == "family" {
		// Root the family at the parent when there is one, so a child sees its
		// siblings; at the issue itself otherwise, so a parent sees its children
		// and a standalone issue degenerates to its own active runs. One rule,
		// both directions.
		root := issue.ID
		if issue.ParentIssueID.Valid {
			root = issue.ParentIssueID
		}
		// One row beyond the cap, so a full page can be told apart from a
		// truncated one without a second count query.
		rows, err := h.Queries.ListActiveTasksByIssueFamily(r.Context(), db.ListActiveTasksByIssueFamilyParams{
			WorkspaceID: issue.WorkspaceID,
			RootIssueID: root,
			RowLimit:    familyActiveRunCap + 1,
		})
		if err != nil {
			writeError(w, http.StatusInternalServerError, "failed to list tasks")
			return
		}
		if len(rows) > familyActiveRunCap {
			rows = rows[:familyActiveRunCap]
			w.Header().Set(HeaderActiveRunsTruncated, "true")
		}
		summaries := make([]ActiveRunSummary, len(rows))
		for i, row := range rows {
			summaries[i] = ActiveRunSummary{
				TaskID:  uuidToString(row.TaskID),
				IssueID: uuidToString(row.IssueID),
				// Rows span several issues here, so each one has to carry the
				// issue it belongs to — a caller cannot label it from the task.
				IssueIdentifier: service.IssueIdentifier(row.IssuePrefix, row.IssueNumber),
				IssueTitle:      row.IssueTitle,
				AgentID:         uuidToString(row.AgentID),
				Status:          row.Status,
				CreatedAt:       timestampToString(row.CreatedAt),
				StartedAt:       timestampToPtr(row.StartedAt),
			}
		}
		// No attribution hydration either: it was the single largest field on
		// the old payload and needed its own query, and "on behalf of whom" is
		// an execution-log question, not a coordination one.
		writeJSON(w, http.StatusOK, summaries)
		return
	}

	var tasks []db.AgentTaskQueue
	var err error
	type issueLabel struct{ identifier, title string }
	labels := make(map[string]issueLabel)
	if scope == "subtree" {
		rows, queryErr := h.Queries.ListTasksByIssueSubtree(r.Context(), db.ListTasksByIssueSubtreeParams{
			RootIssueID: issue.ID, WorkspaceID: issue.WorkspaceID, ActiveOnly: activeOnly,
		})
		err = queryErr
		for _, row := range rows {
			tasks = append(tasks, row.AgentTaskQueue)
			labels[uuidToString(row.AgentTaskQueue.IssueID)] = issueLabel{
				identifier: service.IssueIdentifier(row.IssuePrefix, row.IssueNumber), title: row.IssueTitle,
			}
		}
	} else if activeOnly {
		tasks, err = h.Queries.ListActiveTasksByIssue(r.Context(), issue.ID)
	} else {
		tasks, err = h.Queries.ListTasksByIssue(r.Context(), issue.ID)
	}
	if err != nil {
		writeError(w, http.StatusInternalServerError, "failed to list tasks")
		return
	}

	tasks = visibleTaskHistory(tasks)
	resp := make([]AgentTaskResponse, len(tasks))
	for i, t := range tasks {
		resp[i] = taskToResponse(t, workspaceID)
		if label, ok := labels[resp[i].IssueID]; ok {
			resp[i].IssueIdentifier = label.identifier
			resp[i].IssueTitle = label.title
		}
	}
	h.hydrateTaskSupplementMetadata(r.Context(), r, issue.WorkspaceID, tasks, resp)
	// Execution-log rows render the "on behalf of <member>" badge, so this
	// issue-facing surface must resolve initiator/originator names (departed-safe,
	// one batch) — otherwise the badge falls back to "someone" on issue detail.
	h.hydrateTaskAttributions(r.Context(), attributionsOf(resp))
	// Usage belongs to the execution log, not to a coordination read.
	// ListIssueTaskUsage returns a row per (task, provider, model) for EVERY
	// task the issue ever ran, so hydrating it on the active path would keep
	// paying the full-history cost this filter exists to remove — and pay it
	// for a column that is near-empty on runs that have not finished.
	if !activeOnly {
		if scope == "subtree" {
			h.hydrateSubtreeTaskUsage(r.Context(), tasks, resp)
		} else {
			h.hydrateTaskUsage(r.Context(), issue.ID, resp)
		}
	}

	if scope == "subtree" {
		if err := h.redactHiddenProjectTasks(r, workspaceID, tasks, resp); err != nil {
			writeError(w, http.StatusInternalServerError, "failed to check project access")
			return
		}
	}
	if view == "timeline" {
		for i := range resp {
			resp[i] = issueTimelineTaskResponse(resp[i])
		}
	}

	writeJSON(w, http.StatusOK, resp)
}

func (h *Handler) GetIssueUsage(w http.ResponseWriter, r *http.Request) {
	issueID := chi.URLParam(r, "id")
	issue, ok := h.loadIssueForUser(w, r, issueID)
	if !ok {
		return
	}

	row, err := h.Queries.GetIssueUsageSummary(r.Context(), issue.ID)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "failed to get issue usage")
		return
	}

	writeJSON(w, http.StatusOK, map[string]any{
		"total_input_tokens":       row.TotalInputTokens,
		"total_output_tokens":      row.TotalOutputTokens,
		"total_cache_read_tokens":  row.TotalCacheReadTokens,
		"total_cache_write_tokens": row.TotalCacheWriteTokens,
		// Cost split — see the note on DashboardUsageDailyResponse.
		"cost_usd_ticks":              row.TotalCostUsdTicks,
		"uncosted_input_tokens":       row.UncostedInputTokens,
		"uncosted_output_tokens":      row.UncostedOutputTokens,
		"uncosted_cache_read_tokens":  row.UncostedCacheReadTokens,
		"uncosted_cache_write_tokens": row.UncostedCacheWriteTokens,
		// task_count is the legacy count of tasks with usage. Keep it stable for
		// installed clients while the explicit coverage fields distinguish runs
		// from metered runs.
		"task_count":            row.TaskCount,
		"terminal_task_count":   row.TerminalTaskCount,
		"metered_task_count":    row.MeteredTaskCount,
		"unreported_task_count": row.UnreportedTaskCount,
	})
}

func (h *Handler) AddIssueReaction(w http.ResponseWriter, r *http.Request) {
	r = h.withWakeupActor(r)
	issueID := chi.URLParam(r, "id")
	issue, ok := h.loadIssueForUser(w, r, issueID)
	if !ok {
		return
	}

	userID, ok := requireUserID(w, r)
	if !ok {
		return
	}

	var req struct {
		Emoji string `json:"emoji"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid request body")
		return
	}
	if req.Emoji == "" {
		writeError(w, http.StatusBadRequest, "emoji is required")
		return
	}

	workspaceID := uuidToString(issue.WorkspaceID)
	actorType, actorID := h.resolveActor(r, userID, workspaceID)

	reaction, err := wakeupWrite(h, r, func(q *db.Queries) (db.AddIssueReactionRow, error) {
		return q.AddIssueReaction(r.Context(), db.AddIssueReactionParams{
			IssueID:     issue.ID,
			WorkspaceID: issue.WorkspaceID,
			ActorType:   actorType,
			ActorID:     parseUUID(actorID),
			Emoji:       req.Emoji,
		})
	})
	if err != nil {
		slog.Warn("add issue reaction failed", append(logger.RequestAttrs(r), "error", err, "issue_id", issueID)...)
		writeError(w, http.StatusInternalServerError, "failed to add reaction")
		return
	}

	resp := addedIssueReactionToResponse(reaction)
	if reaction.IssueRevision > 0 {
		h.publish(protocol.EventIssueReactionAdded, workspaceID, actorType, actorID, map[string]any{
			"reaction":       resp,
			"issue_id":       uuidToString(issue.ID),
			"issue_title":    issue.Title,
			"issue_status":   issue.Status,
			"creator_type":   issue.CreatorType,
			"creator_id":     uuidToString(issue.CreatorID),
			"issue_revision": reaction.IssueRevision,
		})
	}
	writeJSON(w, http.StatusCreated, resp)
}

