func (h *Handler) RecordSquadLeaderEvaluation(w http.ResponseWriter, r *http.Request) {
	issue, ok := h.loadIssueForUser(w, r, chi.URLParam(r, "id"))
	if !ok {
		return
	}

	var req struct {
		Outcome string `json:"outcome"` // action | no_action | failed
		Reason  string `json:"reason"`  // short explanation from leader
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid request body")
		return
	}

	if req.Outcome != "action" && req.Outcome != "no_action" && req.Outcome != "failed" {
		writeError(w, http.StatusBadRequest, "outcome must be 'action', 'no_action', or 'failed'")
		return
	}

	// Authority for "is this run a squad leader turn" is the TASK ROW, not the
	// target issue's assignee (MUL-6622 / GH #7487). is_leader_task + squad_id
	// are stamped at enqueue time and are exactly what the claim path keys the
	// squad briefing and the mandatory-`squad activity` instruction off
	// (handler/daemon.go, daemon/prompt.go taskIsSquadLeader). Gating this
	// endpoint on issue.assignee_type == "squad" instead made the recording
	// call unsatisfiable on the paths where a leader legitimately runs on a
	// non-squad-assigned issue — a `@squad` mention on an issue owned by a
	// plain agent, or a leader task bound to a child issue — and because the
	// no_action instruction forbids substituting a comment, the decision left
	// no trace at all.
	//
	// Check ORDER is load-bearing. Every rejection below the ownership gate may
	// quote task-derived ids; every rejection above it must not. `GetAgentTask`
	// is a global lookup by id, so tenant scoping (GetAgentTaskInWorkspace,
	// which joins the owning agent's workspace) and the "caller owns this task"
	// gate both come first — otherwise an unrelated task id, probed through an
	// issue the caller can legitimately read, would echo back a foreign
	// workspace's issue id.
	taskID := r.Header.Get("X-Task-ID")
	taskUUID, ok := parseUUIDOrBadRequest(w, taskID, "task id")
	if !ok {
		return
	}
	task, err := h.Queries.GetAgentTaskInWorkspace(r.Context(), db.GetAgentTaskInWorkspaceParams{
		ID:          taskUUID,
		WorkspaceID: issue.WorkspaceID,
	})
	if err != nil || !task.IssueID.Valid {
		writeError(w, http.StatusBadRequest, "task does not belong to issue")
		return
	}

	// Security gate 1: the caller must be the agent this task was enqueued for.
	workspaceID := uuidToString(issue.WorkspaceID)
	userID := requestUserID(r)
	actorType, actorID := h.resolveActor(r, userID, workspaceID)
	if actorType != "agent" || !task.AgentID.Valid || actorID != uuidToString(task.AgentID) {
		writeError(w, http.StatusForbidden, "only the squad leader agent can record evaluations")
		return
	}

	// Past the ownership gate, naming the task's own issue is safe — and useful:
	// a leader woken by a stage barrier / child-done callback runs on the PARENT
	// issue, so recording against the child it just read is the common mistake.
	if uuidToString(task.IssueID) != uuidToString(issue.ID) {
		writeError(w, http.StatusBadRequest,
			"task does not belong to issue; record the evaluation on issue "+uuidToString(task.IssueID)+" (the issue this task is running on)")
		return
	}
	// Narrowing vs. the old behavior: a leader agent running a NON-leader task
	// on a squad-assigned issue (for example a same-squad worker task) used to
	// be accepted here. It is rejected now — it is not running as the leader,
	// and the runtime only mandates this call when taskIsSquadLeader(task).
	if !task.IsLeaderTask {
		writeError(w, http.StatusBadRequest, "task is not a squad leader task")
		return
	}
	if !task.SquadID.Valid {
		// Pre-MUL-3730 rows can be leader tasks without a stamped squad. Log it
		// rather than failing silently from the operator's point of view.
		slog.Warn("squad leader evaluation: leader task has no squad_id",
			append(logger.RequestAttrs(r),
				"task_id", uuidToString(task.ID),
				"issue_id", uuidToString(issue.ID),
			)...)
		writeError(w, http.StatusBadRequest, "leader task has no squad_id")
		return
	}

	squad, err := h.Queries.GetSquadInWorkspace(r.Context(), db.GetSquadInWorkspaceParams{
		ID:          task.SquadID,
		WorkspaceID: issue.WorkspaceID,
	})
	if err != nil {
		writeError(w, http.StatusNotFound, "squad not found")
		return
	}

	// Security gate 2: the caller must still be this squad's leader.
	//
	// `is_leader_task` on the row records the enqueue-time INTENT, which is not
	// always the role the claim actually delivered: when the leader was swapped
	// between enqueue and claim, the claim path clears resp.IsLeaderTask and the
	// run proceeds as an ordinary agent turn, while the row keeps
	// is_leader_task = true (handler/daemon.go, "claim delivered as a non-leader
	// task"). Trusting the row alone would let such a downgraded run write a
	// leader verdict — and, on no_action, suppress its own comment. Until the
	// delivered role is persisted, the live leader check is the only thing that
	// distinguishes the two, so it stays.
	//
	// Cost of the conservative choice: a leader rotated away MID-run is refused
	// here. That no longer means silence — the injected rules now tell a leader
	// whose recording call failed to leave a short comment instead.
	if actorID != uuidToString(squad.LeaderID) {
		writeError(w, http.StatusForbidden, "only the squad leader agent can record evaluations")
		return
	}

	details, _ := json.Marshal(map[string]string{
		"squad_id": uuidToString(squad.ID),
		"task_id":  util.UUIDToString(taskUUID),
		"outcome":  req.Outcome,
		"reason":   req.Reason,
	})

	activity, err := h.Queries.CreateActivity(r.Context(), db.CreateActivityParams{
		ID:          dbid.NewV7(),
		WorkspaceID: issue.WorkspaceID,
		IssueID:     issue.ID,
		ActorType:   pgtype.Text{String: "agent", Valid: true},
		// task.AgentID, not squad.LeaderID: the no_action comment suppression
		// lookup matches actor_id against task.agent_id
		// (service.HasSquadLeaderNoActionEvaluationForTask), so this column has
		// to carry the task's agent for suppression to find the row at all.
		ActorID: task.AgentID,
		Action:  "squad_leader_evaluated",
		Details: details,
	})
	if err != nil {
		writeError(w, http.StatusInternalServerError, "failed to record evaluation")
		return
	}

	h.publish(protocol.EventActivityCreated, uuidToString(issue.WorkspaceID), "agent", actorID, map[string]any{
		"issue_id": uuidToString(issue.ID),
		"entry": map[string]any{
			"type":       "activity",
			"id":         uuidToString(activity.ID),
			"actor_type": "agent",
			"actor_id":   actorID,
			"action":     activity.Action,
			"details":    json.RawMessage(details),
			"created_at": timestampToString(activity.CreatedAt),
		},
	})

	writeJSON(w, http.StatusCreated, map[string]string{
		"id":         uuidToString(activity.ID),
		"action":     activity.Action,
		"created_at": timestampToString(activity.CreatedAt),
	})
}

func (h *Handler) ListAutopilots(w http.ResponseWriter, r *http.Request) {
	workspaceID := h.resolveWorkspaceID(r)

	var statusFilter pgtype.Text
	if s := r.URL.Query().Get("status"); s != "" {
		statusFilter = pgtype.Text{String: s, Valid: true}
	}

	autopilots, err := h.Queries.ListAutopilots(r.Context(), db.ListAutopilotsParams{
		WorkspaceID: parseUUID(workspaceID),
		Status:      statusFilter,
	})
	if err != nil {
		writeError(w, http.StatusInternalServerError, "failed to list autopilots")
		return
	}
	// Autopilots on private projects the caller cannot see are left out
	// (MUL-8472), as loadAutopilotInWorkspace answers them like missing ones.
	hidden, ok := h.requestHiddenProjects(w, r, workspaceID)
	if !ok {
		return
	}
	if !hidden.Empty() {
		visible := autopilots[:0:0]
		for _, row := range autopilots {
			if hidden.CanSeeProject(row.Autopilot.ProjectID) {
				visible = append(visible, row)
			}
		}
		autopilots = visible
	}

	// Resolve the acting caller's write access for per-row can_write. The
	// collaborator grants are fetched once as a set (keyed by autopilot id) so the
	// flag costs no per-row query. A missing member — an agent run with no
	// originator, or (behind the workspace-member middleware, shouldn't happen) a
	// non-member — just yields can_write=false everywhere.
	caller, callerErr := h.getWorkspaceMember(r.Context(), h.autopilotActingUserID(r, workspaceID), workspaceID)
	collabSet := map[string]struct{}{}
	if callerErr == nil {
		if ids, err := h.Queries.ListAutopilotIDsForCollaborator(r.Context(), caller.UserID); err == nil {
			for _, id := range ids {
				collabSet[uuidToString(id)] = struct{}{}
			}
		}
	}

	// Subscribers are fetched for the whole page in one batched query. An
	// earlier version passed nil here to dodge an N+1, but the response type
	// serializes a nil slice as [] rather than omitting it, so every listed
	// autopilot claimed to have no subscribers while the detail endpoint
	// reported the real ones — a silently wrong value is worse than a missing
	// one (MUL-6680). The batch keys off the primary key's leading column, so
	// this costs one indexed query per page, not one per row.
	subsByAutopilot := map[string][]db.AutopilotSubscriber{}
	autopilotIDs := make([]pgtype.UUID, 0, len(autopilots))
	for _, row := range autopilots {
		autopilotIDs = append(autopilotIDs, row.Autopilot.ID)
	}
	if len(autopilotIDs) > 0 {
		subs, err := h.Queries.ListAutopilotSubscribersForAutopilots(r.Context(), autopilotIDs)
		if err != nil {
			// Fail closed. Degrading to an empty set here would reintroduce
			// exactly the bug this endpoint was fixed for: subscribers is a
			// non-omitempty field documented as authoritative, so an empty
			// value on a failed read is indistinguishable from "none
			// configured" — and a caller acting on it can overwrite a real
			// subscriber list. An error the caller can see and retry is the
			// only honest answer.
			writeError(w, http.StatusInternalServerError, "failed to list autopilot subscribers")
			return
		}
		for _, s := range subs {
			id := uuidToString(s.AutopilotID)
			subsByAutopilot[id] = append(subsByAutopilot[id], s)
		}
	}

	resp := make([]AutopilotResponse, len(autopilots))
	for i, row := range autopilots {
		r := autopilotToResponse(row.Autopilot, subsByAutopilot[uuidToString(row.Autopilot.ID)])
		r.TriggerKinds = row.TriggerKinds
		if row.NextRunAt.Valid {
			r.NextRunAt = timestampToPtr(row.NextRunAt)
		}
		if row.LastRunStatus != "" {
			s := row.LastRunStatus
			r.LastRunStatus = &s
		}
		if callerErr == nil {
			_, isCollaborator := collabSet[uuidToString(row.Autopilot.ID)]
			cw := autopilotWriteByOwnership(row.Autopilot, caller) || isCollaborator
			r.CanWrite = &cw
		}
		resp[i] = r
	}
	writeJSON(w, http.StatusOK, map[string]any{"autopilots": resp, "total": len(resp)})
}

func (h *Handler) CreateAutopilot(w http.ResponseWriter, r *http.Request) {
	var req CreateAutopilotRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid request body")
		return
	}
	if req.Title == "" {
		writeError(w, http.StatusBadRequest, "title is required")
		return
	}
	if req.AssigneeID == "" {
		writeError(w, http.StatusBadRequest, "assignee_id is required")
		return
	}
	if req.ExecutionMode == "" {
		writeError(w, http.StatusBadRequest, "execution_mode is required")
		return
	}
	if req.ExecutionMode != "create_issue" && req.ExecutionMode != "run_only" {
		writeError(w, http.StatusBadRequest, "execution_mode must be create_issue or run_only")
		return
	}
	if req.IssueTitleTemplate != nil {
		if err := service.ValidateIssueTitleTemplate(*req.IssueTitleTemplate); err != nil {
			writeError(w, http.StatusBadRequest, err.Error())
			return
		}
	}

	workspaceID := h.resolveWorkspaceID(r)
	// Everything this handler stamps — created_by, the v1 rule version, the
	// realtime event, the analytics actor — is the human the create acts for,
	// never the runtime owner whose token authenticated it. created_by is the
	// autopilot's own write grant, so stamping the wrong human here would hand
	// that grant to a machine's owner and lock the requesting member out of the
	// autopilot they just asked for (MUL-7108).
	actor, ok := h.requireAutopilotActingMember(w, r, workspaceID, autopilotCreateRefusal)
	if !ok {
		return
	}
	userID := uuidToString(actor.UserID)

	assigneeUUID, ok := parseUUIDOrBadRequest(w, req.AssigneeID, "assignee_id")
	if !ok {
		return
	}
	wsUUID, ok := parseUUIDOrBadRequest(w, workspaceID, "workspace id")
	if !ok {
		return
	}

	assigneeType := "agent"
	if req.AssigneeType != nil && *req.AssigneeType != "" {
		assigneeType = *req.AssigneeType
	}
	if !isValidAutopilotAssigneeType(assigneeType) {
		writeError(w, http.StatusBadRequest, "assignee_type must be agent or squad")
		return
	}
	projectID, ok := h.parseAutopilotProjectID(w, r, req.ProjectID, wsUUID)
	if !ok {
		return
	}
	if h.projectIsArchived(r.Context(), h.Queries, projectID, wsUUID) {
		writeProjectArchived(w)
		return
	}

	// Parse before insert so a malformed payload doesn't open a transaction.
	subscribers, ok := parseAutopilotSubscribers(w, req.Subscribers)
	if !ok {
		return
	}

	tx, err := h.TxStarter.Begin(r.Context())
	if err != nil {
		writeError(w, http.StatusInternalServerError, "failed to create autopilot")
		return
	}
	defer tx.Rollback(r.Context())
	qtx := h.Queries.WithTx(tx)

	// This must be the first lock family in the transaction. Member revocation
	// takes the same per-(workspace, user) locks before pruning templates and
	// deleting member rows. Re-checking membership after those locks means
	// either this save commits first and revocation prunes it, or revocation
	// commits first and this save rejects the departed subscriber.
	if !h.lockAndValidateAutopilotSubscribers(w, r, qtx, subscribers, wsUUID) {
		return
	}

	// Keep save-time readiness validation in the same transaction as the
	// insert. The assignment lock serializes this path with Runtime teardown,
	// so an active Autopilot cannot slip in after teardown's pause sweep.
	if !h.validateAutopilotAssigneeForSave(w, r, qtx, assigneeType, assigneeUUID, wsUUID, true) {
		return
	}

	autopilot, err := qtx.CreateAutopilot(r.Context(), db.CreateAutopilotParams{
		WorkspaceID:        wsUUID,
		Title:              req.Title,
		AssigneeType:       assigneeType,
		AssigneeID:         assigneeUUID,
		Status:             "active",
		ExecutionMode:      req.ExecutionMode,
		CreatedByType:      "member",
		CreatedByID:        actor.UserID,
		Description:        ptrToText(req.Description),
		IssueTitleTemplate: ptrToText(req.IssueTitleTemplate),
		ProjectID:          projectID,
	})
	if err != nil {
		writeError(w, http.StatusInternalServerError, "failed to create autopilot")
		return
	}

	// Creating an autopilot IS a substantive publish: append rule-version v1 with
	// the creating member as publisher, so every autopilot has an accountable
	// human at dispatch time (MUL-4302 §3.4).
	if err := h.recordAutopilotRuleVersion(r.Context(), qtx, autopilot, "member", actor.UserID); err != nil {
		writeError(w, http.StatusInternalServerError, "failed to create autopilot")
		return
	}

	for _, subscriber := range subscribers {
		if err := qtx.AddAutopilotSubscriber(r.Context(), db.AddAutopilotSubscriberParams{
			AutopilotID: autopilot.ID,
			UserType:    "member",
			UserID:      subscriber.UserID,
		}); err != nil {
			writeError(w, http.StatusInternalServerError, "failed to add autopilot subscriber")
			return
		}
	}
	if err := tx.Commit(r.Context()); err != nil {
		writeError(w, http.StatusInternalServerError, "failed to create autopilot")
		return
	}
	subs, err := h.Queries.ListAutopilotSubscribers(r.Context(), autopilot.ID)
	if err != nil {
		subs = nil
	}

	resp := autopilotToResponse(autopilot, subs)
	h.publish(protocol.EventAutopilotCreated, workspaceID, "member", userID, map[string]any{"autopilot": resp})
	obsmetrics.RecordEvent(h.Analytics, h.Metrics, analytics.AutopilotCreated(
		userID,
		workspaceID,
		uuidToString(autopilot.ID),
		"manual",
		"manual",
	))
	writeJSON(w, http.StatusCreated, resp)
}

func (h *Handler) CronPreview(w http.ResponseWriter, r *http.Request) {
	expr := r.URL.Query().Get("expr")
	if expr == "" {
		writeCronPreviewError(w, cronPreviewInvalidCron, "expr is required")
		return
	}
	tz := r.URL.Query().Get("tz")
	if tz == "" {
		tz = "UTC"
	}
	if err := service.ValidateTimezone(tz); err != nil {
		writeCronPreviewError(w, cronPreviewInvalidTimezone, err.Error())
		return
	}

	const previewCount = 3
	// A syntactically valid expression that never fires comes back as a short (or
	// empty) slice, not an error: the editor tells "never runs" from "your cron is
	// wrong" by the status code.
	occurrences, err := service.NextOccurrencesAfterUTC(expr, tz, time.Now().UTC(), previewCount)
	if err != nil {
		writeCronPreviewError(w, cronPreviewInvalidCron, err.Error())
		return
	}
	nextRuns := make([]string, 0, len(occurrences))
	for _, at := range occurrences {
		nextRuns = append(nextRuns, at.Format(time.RFC3339))
	}
	writeJSON(w, http.StatusOK, map[string]any{"next_runs": nextRuns})
}

func (h *Handler) GetAutopilotQuotaUsage(w http.ResponseWriter, r *http.Request) {
	workspaceID, err := util.ParseUUID(h.resolveWorkspaceID(r))
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid workspace")
		return
	}
	usage, err := h.AutopilotService.AutopilotQuotaUsage(r.Context(), workspaceID)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "failed to load autopilot quota usage")
		return
	}
	resp := AutopilotQuotaUsageResponse{Action: "off"}
	if usage.Enabled {
		resp.Action = usage.Action
		resp.Used, resp.Reserved, resp.Total = usage.Used, usage.Reserved, usage.Total
		resp.Limit, resp.Reached = usage.Limit, usage.Reached
		resp.BlockedCounts = usage.BlockedCounts
		if usage.PeriodStart != nil {
			v := usage.PeriodStart.UTC().Format(time.RFC3339)
			resp.PeriodStart = &v
		}
		if usage.PeriodEnd != nil {
			v := usage.PeriodEnd.UTC().Format(time.RFC3339)
			resp.PeriodEnd = &v
		}
		if usage.ResetAt != nil {
			v := usage.ResetAt.UTC().Format(time.RFC3339)
			resp.ResetAt = &v
		}
	}
	writeJSON(w, http.StatusOK, resp)
}

func (h *Handler) GetAutopilot(w http.ResponseWriter, r *http.Request) {
	id := chi.URLParam(r, "id")
	workspaceID := h.resolveWorkspaceID(r)

	autopilot, ok := h.loadAutopilotInWorkspace(w, r, id, workspaceID)
	if !ok {
		return
	}

	subs, err := h.Queries.ListAutopilotSubscribers(r.Context(), autopilot.ID)
	if err != nil {
		// Fail closed for the same reason the list endpoint does: an empty
		// subscribers array is a claim, not an absence, and this response is
		// what clients round-trip back into a full-replace PATCH.
		writeError(w, http.StatusInternalServerError, "failed to list autopilot subscribers")
		return
	}
	resp := autopilotToResponse(autopilot, subs)

	// Resolve the acting caller's write access once: it both stamps can_write and
	// gates webhook-secret exposure. Webhook tokens are trigger-granting
	// secrets (anyone who reads the token can fire the autopilot from outside
	// the permission system), so only writers — the creator, a workspace
	// owner/admin, or a granted collaborator — get the live token/URL; every
	// other member sees the trigger metadata with the secret fields stripped
	// (MUL-3807).
	//
	// "Acting" is what makes the write gates worth having: judging the
	// authenticated user would hand an agent its runtime owner's tokens, and a
	// token read here is a trigger the write gates never see (MUL-7108).
	canWrite := false
	canManageAccess := false
	if member, err := h.getWorkspaceMember(r.Context(), h.autopilotActingUserID(r, workspaceID), workspaceID); err == nil {
		canWrite = h.memberCanWriteAutopilot(r.Context(), autopilot, member)
		// Managing the access list is narrower than write: collaborators can
		// write but cannot re-grant (MUL-3807).
		canManageAccess = autopilotWriteByOwnership(autopilot, member)
	}
	resp.CanWrite = &canWrite
	resp.CanManageAccess = &canManageAccess

	// Include triggers.
	triggers, err := h.Queries.ListAutopilotTriggers(r.Context(), autopilot.ID)
	if err != nil {
		triggers = nil
	}
	triggerResp := make([]AutopilotTriggerResponse, len(triggers))
	for i, t := range triggers {
		tr := h.triggerToResponse(t)
		if !canWrite {
			redactWebhookSecrets(&tr)
		}
		triggerResp[i] = tr
	}

	// Include the explicit collaborator grants so the "manage access" UI can
	// render the current list without a second round-trip.
	collaborators, err := h.Queries.ListAutopilotCollaborators(r.Context(), autopilot.ID)
	if err != nil {
		collaborators = nil
	}
	collabResp := make([]AutopilotCollaboratorEntry, len(collaborators))
	for i, c := range collaborators {
		collabResp[i] = collaboratorToEntry(c)
	}

	writeJSON(w, http.StatusOK, map[string]any{
		"autopilot":     resp,
		"triggers":      triggerResp,
		"collaborators": collabResp,
	})
}

func (fakeAudienceQuerier) GetAutopilot(_ context.Context, id pgtype.UUID) (db.Autopilot, error) {
	if util.UUIDToString(id) == ppAutopilot {
		return db.Autopilot{ID: id, ProjectID: ppUUID(ppPrivate)}, nil
	}
	return db.Autopilot{}, pgx.ErrNoRows
