func (h *Handler) ListIssueViewIssues(w http.ResponseWriter, r *http.Request) {
	if h.DB == nil {
		writeError(w, http.StatusInternalServerError, "database is unavailable")
		return
	}
	userID, ok := requireUserID(w, r)
	if !ok {
		return
	}
	view, _, ok := h.loadIssueViewForUser(w, r, userID)
	if !ok {
		return
	}

	params := r.URL.Query()
	today := time.Now().UTC().Format(time.DateOnly)
	if raw := params.Get("today"); raw != "" {
		if _, ok := parseIssueTableToday(raw); !ok {
			writeError(w, http.StatusBadRequest, "today must be a YYYY-MM-DD date")
			return
		}
		today = raw
	}
	limit := issueTableDefaultPageSize
	if raw := params.Get("limit"); raw != "" {
		parsed, err := strconv.Atoi(raw)
		if err != nil || parsed < 1 || parsed > issueTableMaxPageSize {
			writeError(w, http.StatusBadRequest, fmt.Sprintf("limit must be between 1 and %d", issueTableMaxPageSize))
			return
		}
		limit = parsed
	}
	page := issueTablePageRequest{Limit: limit}
	if raw := params.Get("cursor"); raw != "" {
		page.Cursor = &raw
	}

	activeProperties, ok := h.activeIssueViewProperties(w, r, view)
	if !ok {
		return
	}
	spec, err := issueViewTableQuery(view, today, activeProperties)
	if err != nil {
		writeError(w, http.StatusBadRequest, err.Error())
		return
	}
	rows, ok := h.queryIssueTableRows(w, r, issueTableRowsRequest{
		Query: spec,
		Group: issueTableGroupSpec{Kind: "none"},
		Page:  page,
	})
	if !ok {
		return
	}

	response := issueViewIssuesResponse{
		Issues:     make([]IssueResponse, len(rows.Rows)),
		NextCursor: rows.NextCursor,
		HasMore:    rows.NextCursor != nil,
	}
	for i, row := range rows.Rows {
		response.Issues[i] = row.Issue
	}
	if page.Cursor == nil {
		total := rows.Total
		response.Total = &total
	}
	writeJSON(w, http.StatusOK, response)
}

func (h *Handler) UpdateIssueView(w http.ResponseWriter, r *http.Request) {
	userID, ok := requireUserID(w, r)
	if !ok {
		return
	}
	view, wsUUID, ok := h.loadIssueViewForUser(w, r, userID)
	if !ok {
		return
	}
	if !h.canManageIssueView(r, view, userID) {
		writeError(w, http.StatusForbidden, "insufficient permissions")
		return
	}

	var req UpdateIssueViewRequest
	r.Body = http.MaxBytesReader(w, r.Body, issueViewBodyMaxBytes)
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid request body")
		return
	}
	if req.ExpectedRevision <= 0 {
		writeError(w, http.StatusBadRequest, "expected_revision is required")
		return
	}
	if req.DefinitionVersion != nil && *req.DefinitionVersion != view.DefinitionVersion {
		writeError(w, http.StatusBadRequest, fmt.Sprintf(
			"view is stored as definition_version %d; this client writes definition_version %d",
			view.DefinitionVersion, *req.DefinitionVersion))
		return
	}

	name := view.Name
	if req.Name != nil {
		if l := len([]rune(*req.Name)); l < 1 || l > issueViewNameMaxLen {
			writeError(w, http.StatusBadRequest, "name must be between 1 and 80 characters")
			return
		}
		name = *req.Name
	}
	visibility := view.Visibility
	if req.Visibility != nil {
		if !contains(validIssueViewVisibilities, *req.Visibility) {
			writeError(w, http.StatusBadRequest, "invalid visibility")
			return
		}
		if view.ScopeType == "my" && *req.Visibility != "private" {
			writeError(w, http.StatusBadRequest, "my views are always private")
			return
		}
		visibility = *req.Visibility
	}
	query := json.RawMessage(view.Query)
	if len(req.Query) > 0 {
		if !isJSONObject(req.Query) {
			writeError(w, http.StatusBadRequest, "query must be a JSON object")
			return
		}
		query = req.Query
	}
	display := json.RawMessage(view.Display)
	if len(req.Display) > 0 {
		if !isJSONObject(req.Display) {
			writeError(w, http.StatusBadRequest, "display must be a JSON object")
			return
		}
		display = req.Display
	}
	// scope_type itself is immutable; the variant within it may switch.
	scopeVariant := view.ScopeVariant
	if req.ScopeVariant != nil {
		next, variantOK := validateIssueViewVariant(view.ScopeType, req.ScopeVariant)
		if !variantOK {
			writeError(w, http.StatusBadRequest, "invalid scope_variant for this scope_type")
			return
		}
		scopeVariant = next
	}

	updated, err := h.Queries.UpdateIssueView(r.Context(), db.UpdateIssueViewParams{
		ID:           view.ID,
		WorkspaceID:  wsUUID,
		Name:         name,
		Visibility:   visibility,
		ScopeVariant: scopeVariant,
		Query:        query,
		Display:      display,
		Revision:     req.ExpectedRevision,
	})
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			// The row exists (we just loaded it) — zero rows means the
			// revision moved underneath the caller.
			writeError(w, http.StatusConflict, "view was modified by someone else")
			return
		}
		writeError(w, http.StatusInternalServerError, "failed to update view")
		return
	}
	h.publishIssueViewChanged(updated, view.Visibility == "workspace", userID, "updated")
	writeJSON(w, http.StatusOK, issueViewToResponse(updated))
}

func (h *Handler) DeleteIssueView(w http.ResponseWriter, r *http.Request) {
	userID, ok := requireUserID(w, r)
	if !ok {
		return
	}
	view, wsUUID, ok := h.loadIssueViewForUser(w, r, userID)
	if !ok {
		return
	}
	if !h.canManageIssueView(r, view, userID) {
		writeError(w, http.StatusForbidden, "insufficient permissions")
		return
	}
	if _, err := h.Queries.DeleteIssueView(r.Context(), db.DeleteIssueViewParams{
		ID: view.ID, WorkspaceID: wsUUID,
	}); err != nil {
		writeError(w, http.StatusInternalServerError, "failed to delete view")
		return
	}
	h.publishIssueViewChanged(view, false, userID, "deleted")
	w.WriteHeader(http.StatusNoContent)
}

func (h *Handler) GetAttachmentByID(w http.ResponseWriter, r *http.Request) {
	att, ok := h.loadAttachmentForRequest(w, r)
	if !ok {
		return
	}
	h.writeSignedAttachmentMetadata(w, r, att)
}

func (h *Handler) GetAttachmentContent(w http.ResponseWriter, r *http.Request) {
	att, ok := h.loadAttachmentForRequest(w, r)
	if !ok {
		return
	}
	attachmentID := uuidToString(att.ID)

	if !isTextPreviewable(att.ContentType, att.Filename) {
		writeError(w, http.StatusUnsupportedMediaType, "preview not supported for this file type")
		return
	}

	if h.Storage == nil {
		writeFeatureDisabled(w, "storage_not_configured", "storage not configured")
		return
	}
	limit := h.maxPreviewSizeBytes()
	if att.SizeBytes > limit {
		writeError(w, http.StatusRequestEntityTooLarge, "file too large for inline preview")
		return
	}
	key := h.Storage.KeyFromURL(att.Url)
	reader, err := h.Storage.GetReader(r.Context(), key)
	if err != nil {
		slog.Error("failed to open attachment for preview", "id", attachmentID, "key", key, "error", err)
		writeError(w, http.StatusNotFound, "attachment object not found")
		return
	}
	defer reader.Close()

	// Check actual bytes as well as metadata. The hard maximum keeps limit+1
	// safe, while the extra byte distinguishes the exact boundary from overflow.
	body, err := io.ReadAll(io.LimitReader(reader, limit+1))
	if err != nil {
		slog.Error("failed to read attachment body for preview", "id", attachmentID, "error", err)
		writeError(w, http.StatusBadGateway, "failed to read attachment body")
		return
	}
	if int64(len(body)) > limit {
		writeError(w, http.StatusRequestEntityTooLarge, "file too large for inline preview")
		return
	}

	// Always reply as text/plain so a hostile HTML payload can't be
	// re-interpreted as a document by the browser. The original MIME is
	// surfaced via X-Original-Content-Type for the client-side dispatcher.
	w.Header().Set("Content-Type", "text/plain; charset=utf-8")
	w.Header().Set("X-Original-Content-Type", att.ContentType)
	// No-store: workspace membership / attachment ACL can change between
	// requests (member removed, attachment deleted). A cached body would
	// stay readable past the revocation window. The redundant request is
	// fine here — bodies are bounded by the preview limit and the endpoint is only hit
	// when a user explicitly opens a preview.
	w.Header().Set("Cache-Control", "no-store")
	w.Header().Set("X-Content-Type-Options", "nosniff")
	h.setAttachmentPreviewSecurityHeaders(w)
	w.Header().Set("Content-Length", fmt.Sprintf("%d", len(body)))
	if _, err := w.Write(body); err != nil {
		slog.Error("failed to write attachment preview body", "id", attachmentID, "error", err)
	}
}

func (h *Handler) DeleteAttachment(w http.ResponseWriter, r *http.Request) {
	r = h.withWakeupActor(r)
	attachmentID := chi.URLParam(r, "id")
	workspaceID := h.resolveWorkspaceID(r)
	if workspaceID == "" {
		writeError(w, http.StatusBadRequest, "workspace_id is required")
		return
	}

	userID, ok := requireUserID(w, r)
	if !ok {
		return
	}

	attUUID, ok := parseUUIDOrBadRequest(w, attachmentID, "attachment id")
	if !ok {
		return
	}
	wsUUID, ok := parseUUIDOrBadRequest(w, workspaceID, "workspace id")
	if !ok {
		return
	}

	att, err := h.Queries.GetAttachment(r.Context(), db.GetAttachmentParams{
		ID:          attUUID,
		WorkspaceID: wsUUID,
	})
	if err != nil {
		writeError(w, http.StatusNotFound, "attachment not found")
		return
	}
	if !h.requireAttachmentVisible(w, r, workspaceID, att) {
		return
	}
	// Captured-context attachments are immutable historical copies. They are
	// deleted only with their target issue, workspace, or abandoned context.
	if att.SourceContextID.Valid {
		writeError(w, http.StatusNotFound, "attachment not found")
		return
	}

	// Only the uploader (or workspace admin) can delete
	uploaderID := uuidToString(att.UploaderID)
	isUploader := att.UploaderType == "member" && uploaderID == userID
	member, hasMember := ctxMember(r.Context())
	isAdmin := hasMember && (member.Role == "admin" || member.Role == "owner")

	if !isUploader && !isAdmin {
		writeError(w, http.StatusForbidden, "not authorized to delete this attachment")
		return
	}

	var deleted db.DeleteAttachmentRow
	deleteParams := db.DeleteAttachmentParams{ID: att.ID, WorkspaceID: att.WorkspaceID}
	err = h.withAttachmentOwnerLock(r.Context(), att, func(qtx *db.Queries) error {
		var deleteErr error
		deleted, deleteErr = qtx.DeleteAttachment(r.Context(), deleteParams)
		return deleteErr
	})
	if errors.Is(err, pgx.ErrNoRows) {
		// The attachment is gone — with its comment, with its issue, or on its
		// own — while this waited for the owner lock.
		writeError(w, http.StatusNotFound, "attachment not found")
		return
	}
	if err != nil {
		slog.Error("failed to delete attachment", "error", err)
		writeError(w, http.StatusInternalServerError, "failed to delete attachment")
		return
	}
	if deleted.Changed && att.IssueID.Valid {
		h.publish(protocol.EventIssueAttachmentsChanged, workspaceID, "member", userID, map[string]any{
			"issue_id":       uuidToString(att.IssueID),
			"issue_revision": deleted.IssueRevision,
		})
	}
	if deleted.Changed && att.CommentID.Valid {
		if comment, loadErr := h.Queries.GetCommentInWorkspace(r.Context(), db.GetCommentInWorkspaceParams{
			ID:          att.CommentID,
			WorkspaceID: att.WorkspaceID,
		}); loadErr == nil {
			commentID := uuidToString(comment.ID)
			reactions := h.groupReactions(r, []pgtype.UUID{comment.ID})
			attachments := h.groupAttachments(r, []pgtype.UUID{comment.ID})
			h.publish(protocol.EventCommentUpdated, workspaceID, "member", userID, map[string]any{
				"comment": commentToResponse(comment, reactions[commentID], attachments[commentID]),
			})
		}
	}

	h.deleteS3Object(r.Context(), att.Url)
	w.WriteHeader(http.StatusNoContent)
}

func (h *Handler) PreviewCommentSubIssue(w http.ResponseWriter, r *http.Request) {
	workspaceID := h.resolveWorkspaceID(r)
	wsUUID, ok := parseUUIDOrBadRequest(w, workspaceID, "workspace_id")
	if !ok {
		return
	}
	if _, ok := h.workspaceMember(w, r, workspaceID); !ok {
		return
	}
	anchorCommentID, ok := parseUUIDOrBadRequest(w, chi.URLParam(r, "commentId"), "comment_id")
	if !ok {
		return
	}
	// MUL-8472: a comment in a private project the caller cannot see reads as
	// a missing one, here as on every other comment route.
	if hiddenComment, err := h.commentInHiddenProject(r, workspaceID, anchorCommentID); err != nil || hiddenComment {
		if err == nil {
			err = service.ErrAnchorCommentDeleted
		}
		h.writeSourceContextError(w, err, service.SourceContextLimitUsage{})
		return
	}
	build, err := service.BuildSourceContext(r.Context(), h.Queries, wsUUID, anchorCommentID)
	if err != nil {
		h.writeSourceContextError(w, err, build.Limits)
		return
	}
	writeJSON(w, http.StatusOK, sourceContextPreviewResponse{
		SourceIssue: build.Snapshot.SourceIssue, CommentThread: build.Snapshot.CommentThread,
		AnchorCommentID: build.Snapshot.AnchorCommentID, CaptureToken: build.Token, Limits: build.Limits,
	})
}

func (h *Handler) CreateCommentSubIssue(w http.ResponseWriter, r *http.Request) {
	var req createCommentSubIssueRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid request body")
		return
	}
	workspaceID := h.resolveWorkspaceID(r)
	wsUUID, ok := parseUUIDOrBadRequest(w, workspaceID, "workspace_id")
	if !ok {
		return
	}
	if _, ok := h.workspaceMember(w, r, workspaceID); !ok {
		return
	}
	userID, ok := requireUserID(w, r)
	if !ok {
		return
	}
	userUUID, ok := parseUUIDOrBadRequest(w, userID, "user_id")
	if !ok {
		return
	}
	anchorCommentID, ok := parseUUIDOrBadRequest(w, chi.URLParam(r, "commentId"), "comment_id")
	if !ok {
		return
	}
	// MUL-8472: a comment in a private project the caller cannot see reads as
	// a missing one, here as on every other comment route.
	if hiddenComment, err := h.commentInHiddenProject(r, workspaceID, anchorCommentID); err != nil || hiddenComment {
		if err == nil {
			err = service.ErrAnchorCommentDeleted
		}
		h.writeSourceContextError(w, err, service.SourceContextLimitUsage{})
		return
	}
	wantDigest, tokenIssueID, validToken := service.ParseSourceContextToken(strings.TrimSpace(req.CaptureToken))
	if !validToken {
		writeJSON(w, http.StatusConflict, map[string]any{"code": "source_context_changed", "error": "source context preview is invalid; refresh and try again"})
		return
	}
	build, err := service.BuildSourceContext(r.Context(), h.Queries, wsUUID, anchorCommentID)
	if errors.Is(err, service.ErrAnchorCommentDeleted) {
		// The token's issue id comes from the client; one in a project the
		// caller cannot see answers like a deleted one.
		tokenIssue, issueErr := h.Queries.GetIssueInWorkspace(r.Context(), db.GetIssueInWorkspaceParams{ID: tokenIssueID, WorkspaceID: wsUUID})
		if errors.Is(issueErr, pgx.ErrNoRows) {
			err = service.ErrSourceIssueDeleted
		} else if issueErr == nil {
			hidden, hiddenErr := h.hiddenProjects(r, workspaceID)
			if hiddenErr != nil {
				err = hiddenErr
			} else if !hidden.CanSeeProject(tokenIssue.ProjectID) {
				err = service.ErrSourceIssueDeleted
			}
		}
	}
	if err != nil {
		h.writeSourceContextError(w, err, build.Limits)
		return
	}
	if build.Snapshot.SourceIssue.ID != util.UUIDToString(tokenIssueID) || build.Digest != wantDigest {
		h.writeSourceContextError(w, service.ErrSourceContextChanged, build.Limits)
		return
	}
	var preparedAgent *preparedAgentCommentSubIssue
	switch req.Mode {
	case "manual":
		if req.Issue == nil {
			writeError(w, http.StatusBadRequest, "issue is required for manual mode")
			return
		}
		if strings.TrimSpace(req.Issue.Title) == "" {
			writeJSON(w, http.StatusBadRequest, map[string]any{"code": "invalid_request", "error": "title is required"})
			return
		}
	case "agent":
		if req.QuickCreate == nil {
			writeError(w, http.StatusBadRequest, "quick_create is required for agent mode")
			return
		}
		if err := service.ValidateSourceContextAgentInput(build, userUUID, strings.TrimSpace(req.QuickCreate.Prompt)); err != nil {
			h.writeSourceContextError(w, err, build.Limits)
			return
		}
		preparedAgent, err = h.prepareAgentCommentSubIssue(w, r, wsUUID, *req.QuickCreate)
		if err != nil {
			if !errors.Is(err, errSourceContextResponseWritten) {
				h.writeSourceContextError(w, err, service.SourceContextLimitUsage{})
			}
			return
		}
	default:
		writeError(w, http.StatusBadRequest, "mode must be manual or agent")
		return
	}
	contextID := dbid.NewV7()
	capture, objectKeys, err := h.cloneSourceContext(r.Context(), wsUUID, userUUID, contextID, build)
	if err != nil {
		slog.Warn("source context capture failed", append(sourceContextAuditAttrs(r, contextID, build.Snapshot.SourceIssue.ID, build.Snapshot.AnchorCommentID, userUUID, req.Mode, build.Limits, "failed"), "error", err)...)
		writeJSON(w, http.StatusBadGateway, map[string]any{"code": "source_context_attachment_copy_failed", "error": "failed to copy source attachments"})
		return
	}
	cleanup := func() {
		for _, key := range objectKeys {
			h.Storage.Delete(context.Background(), key)
		}
	}
	cleanupIfUnpersisted := func() {
		_, lookupErr := h.Queries.GetIssueSourceContextByID(r.Context(), db.GetIssueSourceContextByIDParams{
			WorkspaceID: wsUUID, ID: capture.ID,
		})
		switch {
		case errors.Is(lookupErr, pgx.ErrNoRows):
			cleanup()
		case lookupErr != nil:
			// A commit error can be ambiguous. Never delete an object while DB
			// ownership is also uncertain; the durable intent reconciler performs
			// the same reference check before deleting it.
			slog.Warn("source context compensation deferred after ownership lookup failed", append(sourceContextAuditAttrs(r, capture.ID, capture.Snapshot.SourceIssue.ID, capture.Snapshot.AnchorCommentID, userUUID, req.Mode, build.Limits, "deferred_cleanup"), "error", lookupErr)...)
		}
	}

	switch req.Mode {
	case "manual":
		if err := h.createManualCommentSubIssue(w, r, wsUUID, userUUID, *req.Issue, capture, build.Limits); err != nil {
			cleanupIfUnpersisted()
			slog.Warn("source context capture failed", append(sourceContextAuditAttrs(r, capture.ID, capture.Snapshot.SourceIssue.ID, capture.Snapshot.AnchorCommentID, userUUID, req.Mode, build.Limits, "failed"), "error", err)...)
			if !errors.Is(err, errSourceContextResponseWritten) {
				h.writeSourceContextError(w, err, service.SourceContextLimitUsage{})
			}
		}
	case "agent":
		if err := h.createAgentCommentSubIssue(w, r, wsUUID, userUUID, *preparedAgent, capture, build.Limits); err != nil {
			cleanupIfUnpersisted()
			slog.Warn("source context capture failed", append(sourceContextAuditAttrs(r, capture.ID, capture.Snapshot.SourceIssue.ID, capture.Snapshot.AnchorCommentID, userUUID, req.Mode, build.Limits, "failed"), "error", err)...)
			if !errors.Is(err, errSourceContextResponseWritten) {
				h.writeSourceContextError(w, err, service.SourceContextLimitUsage{})
			}
		}
	}
}

func (h *Handler) UpdateComment(w http.ResponseWriter, r *http.Request) {
	r = h.withWakeupActor(r)
	commentId := chi.URLParam(r, "commentId")

	userID, ok := requireUserID(w, r)
	if !ok {
		return
	}
	commentUUID, ok := parseUUIDOrBadRequest(w, commentId, "comment id")
	if !ok {
		return
	}

	// Load comment scoped to current workspace.
	workspaceID := h.resolveWorkspaceID(r)
	wsUUID, ok := parseUUIDOrBadRequest(w, workspaceID, "workspace id")
	if !ok {
		return
	}
	existing, err := h.Queries.GetCommentInWorkspace(r.Context(), db.GetCommentInWorkspaceParams{
		ID:          commentUUID,
		WorkspaceID: wsUUID,
	})
	// A deleted comment's tombstone has nothing left to edit.
	if err != nil || existing.DeletedAt.Valid {
		writeError(w, http.StatusNotFound, "comment not found")
		return
	}
	if !h.requireIssueIDVisible(w, r, workspaceID, existing.IssueID, http.StatusNotFound, "comment not found") {
		return
	}
	if bound, err := h.Queries.CommentHasTaskSupplement(r.Context(), db.CommentHasTaskSupplementParams{
		CommentID: existing.ID, WorkspaceID: wsUUID,
	}); err != nil {
		writeError(w, http.StatusInternalServerError, "failed to verify additional message")
		return
	} else if bound {
		writeError(w, http.StatusConflict, "additional messages cannot be edited")
		return
	}

	member, ok := h.workspaceMember(w, r, workspaceID)
	if !ok {
		return
	}

	actorType, actorID := h.resolveActor(r, userID, workspaceID)
	isAuthor := existing.AuthorType == actorType && uuidToString(existing.AuthorID) == actorID
	isAdmin := roleAllowed(member.Role, "owner", "admin")
	if !isAuthor && !isAdmin {
		writeError(w, http.StatusForbidden, "only comment author or admin can edit")
		return
	}

	var req struct {
		Content          string    `json:"content"`
		ContentBase      *string   `json:"content_base,omitempty"`
		AttachmentIDs    *[]string `json:"attachment_ids"`
		SuppressAgentIDs []string  `json:"suppress_agent_ids"`
		ExpectedRevision *int64    `json:"expected_revision,omitempty"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid request body")
		return
	}
	// See CreateComment: strip NUL / invalid-UTF-8 bytes PostgreSQL's TEXT column
	// rejects before the empty check, so an edit that introduces such a byte
	// can't 500 (GH #5388).
	req.Content = sanitizeNullBytes(req.Content)
	if req.ContentBase != nil {
		sanitized := sanitizeNullBytes(*req.ContentBase)
		req.ContentBase = &sanitized
	}
	if req.Content == "" {
		writeError(w, http.StatusBadRequest, "content is required")
		return
	}
	if req.ExpectedRevision != nil {
		if *req.ExpectedRevision < 1 {
			writeError(w, http.StatusBadRequest, "expected_revision must be a positive integer")
			return
		}
		if existing.Revision != *req.ExpectedRevision {
			writeRevisionConflict(w, "comment", existing.ID, *req.ExpectedRevision, existing.Revision)
			return
		}
	}
	strictContentEdit := req.ContentBase != nil || req.ExpectedRevision != nil

	var attachmentIDs []pgtype.UUID
	replaceAttachments := req.AttachmentIDs != nil
	if replaceAttachments {
		var ok bool
		attachmentIDs, ok = parseUUIDSliceOrBadRequest(w, *req.AttachmentIDs, "attachment_ids")
		if !ok {
			return
		}
	}
	suppressAgentIDs, ok := parseUUIDSliceOrBadRequest(w, req.SuppressAgentIDs, "suppress_agent_ids")
	if !ok {
		return
	}

	// NOTE: See CreateComment — Markdown is sanitized at render/edit time, not here.

	oldContent := existing.Content
	// Preserve the existing authority lineage by default — this path is taken only
	// for an UNCHANGED edit (no re-trigger). When the content changes below, the
	// lineage is re-derived from the EDIT action itself (MUL-4857), never carried
	// over from the comment's original authoring run.
	sourceTaskID := existing.SourceTaskID
	var triggerIssue *db.Issue
	var cancelled []db.AgentTaskQueue
	if oldContent != req.Content {
		issue, err := h.Queries.GetIssue(r.Context(), existing.IssueID)
		if err != nil {
			slog.Warn("load issue for edit post-processing failed", "issue_id", uuidToString(existing.IssueID), "error", err)
			writeError(w, http.StatusInternalServerError, "failed to load issue")
			return
		}
		triggerIssue = &issue
		// A content edit is a NEW action, so its delegation lineage must key on THIS
		// edit. Only the AGENT author re-editing its OWN comment carries the lineage
		// forward (commentSourceTaskID re-stamps the current editing task) — so
		// preview, save, and the deferred completion-reconcile all resolve the
		// authority from this one action. Any OTHER editor — a workspace owner/admin
		// editing an AGENT's comment, or a member editing their own — CLEARS the
		// lineage so the deferred reconcile fails closed instead of resurrecting the
		// original autopilot run's creator authority. An admin holds manage rights
		// over the comment, not invoke rights over the author's private agents (Elon
		// must-fix, round 3).
		if actorType == "agent" && isAuthor {
			sourceTaskID = h.commentSourceTaskID(r)
		} else {
			sourceTaskID = pgtype.UUID{}
		}
		// Legacy clients keep the existing cancel-before-update behavior. Strict
		// revision writes defer cancellation until the conditional UPDATE wins,
		// so a race that returns 409 cannot mutate the task queue.
		if !strictContentEdit {
			cancelled, err = h.TaskService.CancelTasksByTriggerComment(r.Context(), existing.ID)
			if err != nil {
				slog.Warn("cancel tasks for edited comment failed", "comment_id", uuidToString(existing.ID), "error", err)
				writeError(w, http.StatusInternalServerError, "failed to prepare comment edit")
				return
			}
		}
	}

	updateParams := db.UpdateCommentParams{
		ID:           commentUUID,
		Content:      req.Content,
		SourceTaskID: sourceTaskID,
		// New text replaces the "don't start" choices completion replay keeps.
		SuppressedAgentIds: suppressAgentIDs,
	}
	if req.ContentBase != nil {
		updateParams.ContentBase = pgtype.Text{String: *req.ContentBase, Valid: true}
	}
	if req.ExpectedRevision != nil {
		updateParams.ExpectedRevision = pgtype.Int8{Int64: *req.ExpectedRevision, Valid: true}
	}
	var comment db.Comment
	var issueRevision int64
	transactionalEdit := replaceAttachments || (oldContent != req.Content && strictContentEdit)
	if transactionalEdit {
		// Strict body edits, attachment-set edits, and cancellation of tasks built
		// from the old body are one database outcome. UpdateComment takes the row
		// lock before the attachment replacement, so two modern editors cannot
		// interleave their CAS check and attachment selection. A body + attachment
		// edit is one visible mutation and therefore bumps revision exactly once.
		tx, beginErr := h.beginWakeupWrite(r.Context())
		if beginErr != nil {
			writeError(w, http.StatusInternalServerError, "failed to prepare comment edit")
			return
		}
		defer tx.Rollback(r.Context())
		qtx := h.Queries.WithTx(tx)
		var updated db.UpdateCommentRow
		updated, err = qtx.UpdateComment(r.Context(), updateParams)
		if err == nil {
			comment = updated.Comment()
			issueRevision = updated.IssueRevision
		}
		if err == nil && oldContent != req.Content && strictContentEdit {
			cancelled, err = qtx.CancelAgentTasksByTriggerComment(r.Context(), existing.ID)
			if err == nil {
				err = service.SettleTerminalTaskState(r.Context(), qtx, cancelled...)
			}
		}
		if err == nil && replaceAttachments {
			var changed int64
			changed, err = qtx.ReplaceCommentAttachments(r.Context(), db.ReplaceCommentAttachmentsParams{
				CommentID:     comment.ID,
				IssueID:       existing.IssueID,
				AttachmentIds: attachmentIDs,
			})
			if err == nil && changed > 0 && oldContent == req.Content {
				comment, err = qtx.BumpCommentRevision(r.Context(), db.BumpCommentRevisionParams{
					ID:          comment.ID,
					WorkspaceID: existing.WorkspaceID,
				})
			}
		}
		if err == nil {
			err = tx.Commit(r.Context())
		}
		if err == nil {
			h.TaskService.BroadcastCancelledTasks(r.Context(), uuidToString(existing.WorkspaceID), cancelled)
		}
	} else {
		var updated db.UpdateCommentRow
		updated, err = wakeupWrite(h, r, func(q *db.Queries) (db.UpdateCommentRow, error) {
			return q.UpdateComment(r.Context(), updateParams)
		})
		if err == nil {
			comment = updated.Comment()
			issueRevision = updated.IssueRevision
		}
	}
	if err != nil {
		slog.Warn("update comment failed", append(logger.RequestAttrs(r), "error", err, "comment_id", commentId)...)
		if triggerIssue != nil && !strictContentEdit {
			// Cancellation committed but the edit did not. Restore the complete
			// original batch, including the still-valid unchanged comment.
			h.retriggerCancelledTaskSurvivors(r.Context(), *triggerIssue, cancelled, pgtype.UUID{})
		}
		if errors.Is(err, pgx.ErrNoRows) {
			current, reloadErr := h.Queries.GetCommentInWorkspace(r.Context(), db.GetCommentInWorkspaceParams{ID: commentUUID, WorkspaceID: wsUUID})
			if errors.Is(reloadErr, pgx.ErrNoRows) || (reloadErr == nil && current.DeletedAt.Valid) {
				// Deleted while the edit waited for it.
				writeError(w, http.StatusNotFound, "comment not found")
				return
			}
			if reloadErr == nil && strictContentEdit {
				if req.ExpectedRevision != nil {
					writeRevisionConflict(w, "comment", current.ID, *req.ExpectedRevision, current.Revision)
				} else {
					writeEditConflict(w, "comment", current.ID)
				}
				return
			}
		}
		writeError(w, http.StatusInternalServerError, "failed to update comment")
		return
	}
	retriggerEditedComment := func() []CommentTriggerOutcome {
		if oldContent == comment.Content {
			return nil
		}
		issue := *triggerIssue
		var parentComment *db.Comment
		if existing.ParentID.Valid {
			parent, err := h.Queries.GetComment(r.Context(), existing.ParentID)
			if err == nil {
				parentComment = &parent
			}
		}

		h.retriggerCancelledTaskSurvivors(r.Context(), issue, cancelled, existing.ID)
		return h.triggerTasksForComment(r.Context(), issue, comment, parentComment, actorType, actorID, h.invokeOriginatorFromRequest(r, actorType, actorID), suppressAgentIDs, commentSteerRequest{})
	}

	// Fetch reactions and attachments for the updated comment.
	grouped := h.groupReactions(r, []pgtype.UUID{comment.ID})
	groupedAtt := h.groupAttachments(r, []pgtype.UUID{comment.ID})
	cid := uuidToString(comment.ID)
	resp := commentToResponse(comment, grouped[cid], groupedAtt[cid])
	resp.IssueRevision = issueRevision
	slog.Info("comment updated", append(logger.RequestAttrs(r), "comment_id", commentId)...)
	eventPayload := map[string]any{"comment": resp}
	if issueRevision > 0 {
		eventPayload["issue_revision"] = issueRevision
	}
	h.publish(protocol.EventCommentUpdated, workspaceID, actorType, actorID, eventPayload)

	// The broadcast above intentionally omits trigger_outcomes — it is the
	// editor's private feedback, not shared timeline state (MUL-4525 §2).
	resp.TriggerOutcomes = retriggerEditedComment()

	writeJSON(w, http.StatusOK, resp)
}

func (h *Handler) DeleteComment(w http.ResponseWriter, r *http.Request) {
	r = h.withWakeupActor(r)
	commentId := chi.URLParam(r, "commentId")

	userID, ok := requireUserID(w, r)
	if !ok {
		return
	}

	commentUUID, ok := parseUUIDOrBadRequest(w, commentId, "comment id")
	if !ok {
		return
	}

	// Load comment scoped to current workspace.
	workspaceID := h.resolveWorkspaceID(r)
	wsUUID, ok := parseUUIDOrBadRequest(w, workspaceID, "workspace id")
	if !ok {
		return
	}
	comment, err := h.Queries.GetCommentInWorkspace(r.Context(), db.GetCommentInWorkspaceParams{
		ID:          commentUUID,
		WorkspaceID: wsUUID,
	})
	if err != nil {
		writeError(w, http.StatusNotFound, "comment not found")
		return
	}
	if !h.requireIssueIDVisible(w, r, workspaceID, comment.IssueID, http.StatusNotFound, "comment not found") {
		return
	}

	member, ok := h.workspaceMember(w, r, workspaceID)
	if !ok {
		return
	}

	actorType, actorID := h.resolveActor(r, userID, workspaceID)
	isAuthor := comment.AuthorType == actorType && uuidToString(comment.AuthorID) == actorID
	isAdmin := roleAllowed(member.Role, "owner", "admin")
	if !isAuthor && !isAdmin {
		writeError(w, http.StatusForbidden, "only comment author or admin can delete")
		return
	}
	issue, err := h.Queries.GetIssue(r.Context(), comment.IssueID)
	hasIssue := err == nil
	if err != nil && !errors.Is(err, pgx.ErrNoRows) {
		slog.Warn("load issue for delete post-processing failed", "issue_id", uuidToString(comment.IssueID), "error", err)
		writeError(w, http.StatusInternalServerError, "failed to load issue")
		return
	}
	if errors.Is(err, pgx.ErrNoRows) {
		// The issue delete may have won the race after GetCommentInWorkspace.
		// Continue so DeleteComment can report whether the comment itself still
		// existed; touching issue activity is intentionally best effort.
		slog.Info("comment parent issue no longer exists", "issue_id", uuidToString(comment.IssueID), "comment_id", commentId)
	}

	if comment.DeletedAt.Valid {
		writeError(w, http.StatusNotFound, "comment not found")
		return
	}

	// Cancel any active task whose planned batch contains this comment so the
	// agent does not run with the now-deleted content already embedded. Must
	// run before the delete: a removed row would nullify trigger_comment_id
	// through ON DELETE SET NULL and orphan those tasks in queued.
	cancelled, cancelErr := h.TaskService.CancelTasksByTriggerComment(r.Context(), comment.ID)
	if cancelErr != nil {
		slog.Warn("cancel tasks for deleted trigger comment failed", append(logger.RequestAttrs(r), "error", cancelErr, "comment_id", commentId)...)
	}

	deleted, err := h.deleteComment(r.Context(), comment.ID, comment.WorkspaceID)
	if err != nil {
		slog.Warn("delete comment failed", append(logger.RequestAttrs(r), "error", err, "comment_id", commentId)...)
		// Cancellation already committed but deletion did not. If the parent
		// issue still exists, rebuild the complete cancelled batch (including
		// this trigger) before reporting the storage error or concurrent no-op.
		if hasIssue {
			h.retriggerCancelledTaskSurvivors(r.Context(), issue, cancelled, pgtype.UUID{})
		}
		if errors.Is(err, errTaskSupplementInFlight) {
			writeError(w, http.StatusConflict, "additional message is still being delivered")
		} else if errors.Is(err, pgx.ErrNoRows) {
			writeError(w, http.StatusNotFound, "comment not found")
		} else {
			writeError(w, http.StatusInternalServerError, "failed to delete comment")
		}
		return
	}

	h.deleteS3Objects(r.Context(), deleted.AttachmentURLs)
	slog.Info("comment deleted", append(logger.RequestAttrs(r),
		"comment_id", commentId,
		"issue_id", uuidToString(comment.IssueID),
		"tombstoned", deleted.Tombstone != nil,
		"removed_count", len(deleted.RemovedIDs),
	)...)
	// A tombstone is still part of the thread, so clients replace it in place
	// through the ordinary update event; removed rows get one delete event each.
	if deleted.Tombstone != nil {
		resp := commentToResponse(*deleted.Tombstone, nil, nil)
		resp.IssueRevision = deleted.IssueRevision
		eventPayload := map[string]any{"comment": resp}
		if deleted.IssueRevision > 0 {
			eventPayload["issue_revision"] = deleted.IssueRevision
		}
		h.publish(protocol.EventCommentUpdated, workspaceID, actorType, actorID, eventPayload)
	}
	for _, removedID := range deleted.RemovedIDs {
		eventPayload := map[string]any{
			"comment_id": uuidToString(removedID),
			"issue_id":   uuidToString(comment.IssueID),
		}
		if deleted.IssueRevision > 0 {
			eventPayload["issue_revision"] = deleted.IssueRevision
		}
		h.publish(protocol.EventCommentDeleted, workspaceID, actorType, actorID, eventPayload)
	}
	if hasIssue {
		h.retriggerCancelledTaskSurvivors(r.Context(), issue, cancelled, comment.ID)
	}
	w.WriteHeader(http.StatusNoContent)
}

