func (h *Handler) UpdateWorkspaceSystemWakeup(w http.ResponseWriter, r *http.Request) {
	workspaceID := h.resolveWorkspaceID(r)
	if chi.URLParam(r, "rule") != service.SystemRuleChildDone {
		writeError(w, 404, "system wakeup not found")
		return
	}
	var in service.SystemWakeupInput
	dec := json.NewDecoder(http.MaxBytesReader(w, r.Body, 16384))
	dec.DisallowUnknownFields()
	if err := dec.Decode(&in); err != nil {
		writeError(w, 400, "invalid system wakeup body")
		return
	}
	member, ok := h.systemWakeupHuman(w, r, workspaceID)
	if !ok {
		return
	}
	if !roleAllowed(member.Role, "owner", "admin") {
		writeError(w, 403, "only owners and admins can change workspace defaults")
		return
	}
	if _, err := (&service.IssueWakeupService{Tasks: h.TaskService}).SetChildDoneDefault(r.Context(), parseUUID(workspaceID), in.Enabled, in.Instruction); err != nil {
		if errors.Is(err, service.ErrWakeupInput) {
			writeError(w, 400, err.Error())
			return
		}
		slog.Warn("update workspace system wakeup failed", "error", err, "workspace_id", workspaceID)
		writeError(w, 500, "could not save system wakeup")
		return
	}
	rules, err := h.workspaceSystemWakeups(r, parseUUID(workspaceID))
	if err != nil {
		writeError(w, 500, "could not load system wakeups")
		return
	}
	writeJSON(w, 200, rules)
}

func (h *Handler) ListWorkspaceWorkingAgents(w http.ResponseWriter, r *http.Request) {
	workspaceID := h.resolveWorkspaceID(r)
	member, ok := h.workspaceMember(w, r, workspaceID)
	if !ok {
		return
	}

	workType := strings.TrimSpace(r.URL.Query().Get("type"))
	switch workType {
	case "", "issue", "autopilot", "chat":
	default:
		writeError(w, http.StatusBadRequest, "invalid type: must be issue, autopilot, or chat")
		return
	}

	scope := strings.TrimSpace(r.URL.Query().Get("scope"))
	mineRelation := strings.TrimSpace(r.URL.Query().Get("relation"))
	var memberID pgtype.UUID
	switch scope {
	case "":
		if mineRelation != "" {
			writeError(w, http.StatusBadRequest, "relation requires scope=mine")
			return
		}
	case "mine":
		if workType != "issue" {
			writeError(w, http.StatusBadRequest, "scope=mine requires type=issue")
			return
		}
		if mineRelation == "" {
			mineRelation = "any"
		}
		switch mineRelation {
		case "assigned", "created", "involved", "any":
		default:
			writeError(w, http.StatusBadRequest, "invalid relation: must be assigned, created, involved, or any")
			return
		}
		userID, ok := requireUserID(w, r)
		if !ok {
			return
		}
		var err error
		memberID, err = util.ParseUUID(userID)
		if err != nil {
			writeError(w, http.StatusUnauthorized, "user not authenticated")
			return
		}
	default:
		writeError(w, http.StatusBadRequest, "invalid scope: must be mine")
		return
	}

	// Narrows the projection to one issue's direct children, so an issue
	// detail's sub-issue header reads this endpoint instead of deriving a
	// count client-side. Left zero when absent, which the query treats as
	// NULL and therefore as "no narrowing" — an older client that never
	// sends it keeps the exact workspace-wide behaviour.
	var parentIssueID pgtype.UUID
	if raw := strings.TrimSpace(r.URL.Query().Get("parent")); raw != "" {
		if workType != "issue" {
			writeError(w, http.StatusBadRequest, "parent requires type=issue")
			return
		}
		if scope != "" {
			writeError(w, http.StatusBadRequest, "parent cannot be combined with scope")
			return
		}
		var ok bool
		parentIssueID, ok = parseUUIDOrBadRequest(w, raw, "parent")
		if !ok {
			return
		}
	}

	rows, err := h.Queries.ListWorkspaceWorkingAgents(
		r.Context(),
		db.ListWorkspaceWorkingAgentsParams{
			WorkspaceID:   parseUUID(workspaceID),
			WorkType:      workType,
			MineRelation:  mineRelation,
			MemberID:      memberID,
			ParentIssueID: parentIssueID,
		},
	)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "failed to list workspace working agents")
		return
	}

	actorType, actorID := h.resolveActor(r, requestUserID(r), workspaceID)
	allowed, ok := h.accessibleAgentIDs(r.Context(), workspaceID, actorType, actorID, member.Role)
	if !ok {
		writeError(w, http.StatusInternalServerError, "failed to resolve agent access")
		return
	}

	// Issues in private projects the caller cannot see (MUL-8472) are left
	// out of issue_ids; the agent and its running count stay, as on the
	// redacted run list.
	hidden, ok := h.requestHiddenProjects(w, r, workspaceID)
	if !ok {
		return
	}
	var issueIDs []pgtype.UUID
	for _, row := range rows {
		issueIDs = append(issueIDs, row.IssueIds...)
	}
	hiddenIssues, err := h.hiddenIssueIDs(r, hidden, issueIDs)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "failed to resolve project access")
		return
	}

	resp := make([]WorkspaceWorkingAgent, 0, len(rows))
	for _, row := range rows {
		agentID := uuidToString(row.ID)
		if _, ok := allowed[agentID]; !ok {
			continue
		}
		visibleIssues := row.IssueIds
		if len(hiddenIssues) > 0 {
			visibleIssues = make([]pgtype.UUID, 0, len(row.IssueIds))
			for _, id := range row.IssueIds {
				if _, hide := hiddenIssues[id]; !hide {
					visibleIssues = append(visibleIssues, id)
				}
			}
		}
		resp = append(resp, WorkspaceWorkingAgent{
			ID:               agentID,
			Name:             row.Name,
			AvatarURL:        h.resolveAvatarURLPtr(textToPtr(row.AvatarUrl)),
			RunningTaskCount: row.RunningTaskCount,
			IssueIDs:         uuidStringsOrEmpty(visibleIssues),
		})
	}

	writeJSON(w, http.StatusOK, resp)
}

