func (s *RedisLocalSkillListStore) Create(ctx context.Context, runtimeID string) (*RuntimeLocalSkillListRequest, error) {
	now := time.Now()
	req := &RuntimeLocalSkillListRequest{
		ID:        randomID(),
		RuntimeID: runtimeID,
		Status:    RuntimeLocalSkillPending,
		Supported: true,
		CreatedAt: now,
		UpdatedAt: now,
	}
	data, err := json.Marshal(req)
	if err != nil {
		return nil, fmt.Errorf("marshal list request: %w", err)
	}

	requestKey := localSkillListKey(req.ID)
	pendingKey := localSkillListPendingKey(runtimeID)
	// Creation does not require a Redis transaction: the request is not
	// observable by dispatchers until it is added to the pending set. A plain
	// pipeline also works on managed Redis deployments that deny MULTI.
	pipe := s.rdb.Pipeline()
	pipe.Set(ctx, requestKey, data, runtimeLocalSkillStoreRetention)
	pipe.ZAdd(ctx, pendingKey, redis.Z{
		Score:  float64(now.UnixNano()),
		Member: req.ID,
	})
	// Keep the pending ZSET alive a bit longer than the individual request
	// so stale members still in the zset can be swept lazily on PopPending
	// without blocking the create path on deletion.
	pipe.Expire(ctx, pendingKey, runtimeLocalSkillStoreRetention*2)
	if _, err := pipe.Exec(ctx); err != nil {
		_ = s.rdb.Del(ctx, requestKey).Err()
		_ = s.rdb.ZRem(ctx, pendingKey, req.ID).Err()
		return nil, fmt.Errorf("persist list request: %w", err)
	}
	return req, nil
}

func (s *RedisLocalSkillImportStore) Create(ctx context.Context, input LocalSkillImportRequestInput) (*RuntimeLocalSkillImportRequest, error) {
	now := time.Now()
	req := &RuntimeLocalSkillImportRequest{
		ID:               randomID(),
		RuntimeID:        input.RuntimeID,
		SkillKey:         input.SkillKey,
		Name:             input.Name,
		Description:      input.Description,
		Action:           input.Action,
		TargetSkillID:    input.TargetSkillID,
		SupportsConflict: input.SupportsConflict,
		Status:           RuntimeLocalSkillPending,
		CreatedAt:        now,
		UpdatedAt:        now,
		CreatorID:        input.CreatorID,
	}
	data, err := s.marshalImport(req)
	if err != nil {
		return nil, err
	}

	requestKey := localSkillImportKey(req.ID)
	pendingKey := localSkillImportPendingKey(input.RuntimeID)
	// Match the other request stores: creation only needs ordered batching, and
	// avoiding MULTI keeps this path compatible with restricted managed Redis.
	pipe := s.rdb.Pipeline()
	pipe.Set(ctx, requestKey, data, runtimeLocalSkillStoreRetention)
	pipe.ZAdd(ctx, pendingKey, redis.Z{
		Score:  float64(now.UnixNano()),
		Member: req.ID,
	})
	pipe.Expire(ctx, pendingKey, runtimeLocalSkillStoreRetention*2)
	if _, err := pipe.Exec(ctx); err != nil {
		_ = s.rdb.Del(ctx, requestKey).Err()
		_ = s.rdb.ZRem(ctx, pendingKey, req.ID).Err()
		return nil, fmt.Errorf("persist import request: %w", err)
	}
	return req, nil
}

func (s *InMemoryModelListStore) Create(_ context.Context, runtimeID string) (*ModelListRequest, error) {
	s.mu.Lock()
	defer s.mu.Unlock()

	// Garbage-collect stale entries so the map can't grow unbounded.
	for id, req := range s.requests {
		if time.Since(req.CreatedAt) > modelListStoreRetention {
			delete(s.requests, id)
		}
	}

	now := time.Now()
	req := &ModelListRequest{
		ID:        randomID(),
		RuntimeID: runtimeID,
		Status:    ModelListPending,
		// Default to true; the daemon overrides this in the report
		// for providers that don't support per-agent model selection.
		Supported: true,
		CreatedAt: now,
		UpdatedAt: now,
	}
	s.requests[req.ID] = req
	return req, nil
}

func (s *RedisUpdateStore) Create(ctx context.Context, runtimeID, targetVersion, initiatorUserID string) (*UpdateRequest, error) {
	now := time.Now()
	req := &UpdateRequest{
		ID:              randomID(),
		RuntimeID:       runtimeID,
		InitiatorUserID: initiatorUserID,
		Status:          UpdatePending,
		TargetVersion:   targetVersion,
		CreatedAt:       now,
		UpdatedAt:       now,
	}
	data, err := s.marshalRequest(req)
	if err != nil {
		return nil, err
	}

	activeKey := updateActiveKey(runtimeID)
	ok, err := s.rdb.SetNX(ctx, activeKey, req.ID, updateStoreRetention).Result()
	if err != nil {
		return nil, fmt.Errorf("reserve active update: %w", err)
	}
	if !ok {
		return nil, errUpdateInProgress
	}

	// The active reservation above provides the concurrency guarantee this
	// write needs. Use a plain pipeline so managed Redis deployments that allow
	// SET/ZADD but deny MULTI can still create update requests. Exec failures
	// remain safe because the compensation below removes every partially
	// written key and releases the reservation.
	pipe := s.rdb.Pipeline()
	pipe.Set(ctx, updateKey(req.ID), data, updateStoreRetention)
	pipe.ZAdd(ctx, updatePendingKey(runtimeID), redis.Z{
		Score:  float64(now.UnixNano()),
		Member: req.ID,
	})
	pipe.Expire(ctx, updatePendingKey(runtimeID), updateStoreRetention*2)
	if _, err := pipe.Exec(ctx); err != nil {
		_ = s.clearActiveIfMatches(ctx, runtimeID, req.ID)
		_ = s.rdb.Del(ctx, updateKey(req.ID)).Err()
		_ = s.rdb.ZRem(ctx, updatePendingKey(runtimeID), req.ID).Err()
		return nil, fmt.Errorf("persist update request: %w", err)
	}
	return req, nil
}

func (s *RedisModelListStore) Create(ctx context.Context, runtimeID string) (*ModelListRequest, error) {
	now := time.Now()
	req := &ModelListRequest{
		ID:        randomID(),
		RuntimeID: runtimeID,
		Status:    ModelListPending,
		Supported: true,
		CreatedAt: now,
		UpdatedAt: now,
	}
	data, err := s.marshalRequest(req)
	if err != nil {
		return nil, err
	}

	requestKey := modelListKey(req.ID)
	pendingKey := modelListPendingKey(runtimeID)
	// Creation does not require a Redis transaction: the request is not
	// observable by dispatchers until it is added to the pending set. A plain
	// pipeline also works on managed Redis deployments that deny MULTI.
	pipe := s.rdb.Pipeline()
	pipe.Set(ctx, requestKey, data, modelListStoreRetention)
	pipe.ZAdd(ctx, pendingKey, redis.Z{
		Score:  float64(now.UnixNano()),
		Member: req.ID,
	})
	// Keep the pending zset alive past the per-record retention so stale
	// members can be lazily swept on PopPending.
	pipe.Expire(ctx, pendingKey, modelListStoreRetention*2)
	if _, err := pipe.Exec(ctx); err != nil {
		_ = s.rdb.Del(ctx, requestKey).Err()
		_ = s.rdb.ZRem(ctx, pendingKey, req.ID).Err()
		return nil, fmt.Errorf("persist model list request: %w", err)
	}
	return req, nil
}

func (s cancellationLocalSkillStore) Create(ctx context.Context, runtimeID string) (*RuntimeLocalSkillListRequest, error) {
