func (s *Service) Create(ctx context.Context, r CreateRequest) (Job, error) {
	if r.IdempotencyKey == "" || len(r.IdempotencyKey) > 200 || len(r.Scope) > 200 {
		return Job{}, ErrInvalid
	}
	if err := r.Options.normalize(); err != nil {
		return Job{}, err
	}
	dry := r.DryRun == nil || *r.DryRun
	j := Job{Type: r.Type, Version: r.Version, Scope: r.Scope, DryRun: dry, Options: r.Options}
	p, err := s.processor(j)
	if err != nil {
		return Job{}, err
	}
	if len(r.Parameters) == 0 {
		r.Parameters = asJSON(struct{}{})
	}
	params, err := p.Validate(r.Scope, dry, r.Parameters)
	if err != nil {
		return Job{}, err
	}
	// Keep creation identity stable even after operational options are tuned.
	hash := fmt.Sprintf("%x", sha256.Sum256(asJSON([]any{r.Type, r.Version, r.Scope, dry, r.Options, params})))
	tx, err := s.pool.Begin(ctx)
	if err != nil {
		return Job{}, err
	}
	defer tx.Rollback(context.Background())
	if err = setTimeouts(ctx, tx, r.Options); err != nil {
		return Job{}, err
	}
	// Every processor relies on these shared identity/concurrency constraints.
	var count int
	if err = tx.QueryRow(ctx, `SELECT count(*) FROM pg_index i
 WHERE i.indrelid='maintenance_job'::regclass AND i.indexrelid IN
 (to_regclass('idx_maintenance_job_id'),to_regclass('idx_maintenance_job_idempotency'),to_regclass('idx_maintenance_job_active'))
 AND i.indisvalid AND i.indisunique`).Scan(&count); err != nil {
		return Job{}, err
	}
	if count != 3 {
		return Job{}, fmt.Errorf("maintenance indexes are missing or invalid; finish migrations 480-482")
	}
	// Serialize creation requests for this type/scope; the unique indexes remain the final guard.
	var locked bool
	err = tx.QueryRow(ctx, "SELECT pg_try_advisory_xact_lock(hashtextextended($1, 0))", "maintenance:"+r.Type+":"+r.Scope).Scan(&locked)
	if err != nil {
		return Job{}, err
	}
	if !locked {
		return Job{}, ErrBusy
	}
	existing, err := scan(tx.QueryRow(ctx, "SELECT "+columns+" FROM maintenance_job WHERE idempotency_key=$1", r.IdempotencyKey))
	if err == nil {
		if existing.RequestHash != hash {
			return existing, ErrConflict
		}
		return existing, nil
	}
	if !errors.Is(err, ErrNotFound) {
		return Job{}, err
	}
	if err = p.Preflight(ctx, tx); err != nil {
		return Job{}, err
	}
	j, err = scan(tx.QueryRow(ctx, `INSERT INTO maintenance_job
 (job_type,job_version,scope_key,idempotency_key,status,dry_run,options,parameters,request_hash)
 VALUES ($1,$2,$3,$4,'ready',$5,$6,$7,$8) RETURNING `+columns,
		r.Type, r.Version, r.Scope, r.IdempotencyKey, dry, asJSON(r.Options), params, hash))
	if err != nil {
		return Job{}, classify(err)
	}
	return j, tx.Commit(ctx)
}

func (s *ChatWakeupService) Create(ctx context.Context, task db.AgentTaskQueue, in ChatWakeupInput) (db.ChatWakeup, error) {
	q := s.Tasks.Queries
	session, err := s.chatTurnSession(ctx, q, task)
	if err != nil {
		return db.ChatWakeup{}, err
	}
	title, instruction, err := normalizeChatWakeupText(in)
	if err != nil {
		return db.ChatWakeup{}, err
	}
	now := s.clock()
	plan, err := in.plan(now)
	if err != nil {
		return db.ChatWakeup{}, err
	}

	requester := chatTurnRequester(task, session)

	var created db.ChatWakeup
	err = s.inTx(ctx, func(tx pgx.Tx, qtx *db.Queries) error {
		// Serializes with DeleteChatSession, which removes the session's
		// wakeups under its own lock on this row.
		locked, err := qtx.LockChatSessionForEnqueue(ctx, session.ID)
		if errors.Is(err, pgx.ErrNoRows) {
			return chatWakeupInputError("this conversation no longer exists")
		}
		if err != nil {
			return err
		}
		if locked.Status != "active" {
			return chatWakeupInputError("this conversation is archived")
		}
		if n, err := qtx.CountActiveChatWakeupsForSession(ctx, session.ID); err != nil {
			return err
		} else if n >= ChatWakeupMaxPerSession {
			return fmt.Errorf("%w: this conversation already has %d active wakeups; list them with `workpal chat wakeup list`, and ask the user which one to cancel", ErrChatWakeupLimit, n)
		}
		if n, err := qtx.CountActiveChatWakeupsForRequester(ctx, db.CountActiveChatWakeupsForRequesterParams{WorkspaceID: session.WorkspaceID, RequesterID: requester}); err != nil {
			return err
		} else if n >= ChatWakeupMaxPerRequester {
			return fmt.Errorf("%w: this person already has %d active wakeups across their conversations", ErrChatWakeupLimit, n)
		}
		if plan.kind == "condition" {
			agent, err := qtx.GetAgent(ctx, session.AgentID)
			if err != nil {
				return err
			}
			normalized, err := s.validateChatCondition(ctx, tx, qtx, session.WorkspaceID, requester, agent.OwnerID, plan.condition, now)
			if err != nil {
				return err
			}
			plan.condition = normalized
		}
		created, err = qtx.CreateChatWakeup(ctx, db.CreateChatWakeupParams{
			ID:              dbid.NewV7(),
			WorkspaceID:     session.WorkspaceID,
			ChatSessionID:   session.ID,
			AgentID:         session.AgentID,
			RequesterID:     requester,
			SourceTaskID:    task.ID,
			SourceMessageID: sourceMessage(ctx, qtx, task),
			Title:           title,
			Instruction:     instruction,
			Kind:            plan.kind,
			Condition:       plan.condition,
			IntervalSeconds: plan.interval,
			FireAt:          plan.fireAt,
			NextEvalAt:      pgtype.Timestamptz{Time: plan.nextEval, Valid: true},
			ExpiresAt:       pgtype.Timestamptz{Time: plan.expiresAt, Valid: true},
		})
		if err != nil {
			return err
		}
		created, err = s.baseline(ctx, tx, qtx, created)
		return err
	})
	if err != nil {
		return db.ChatWakeup{}, err
	}
	s.publish(ctx, created, pgtype.UUID{})
	return created, nil
}

